window.__D("text/torat-chaim/c027",{"p":[[2300540466,"דתהו פשוטים ותקיפים שלא יכילנו הכלים איך אפשר שיומשכו ויוגבלו בכלים דתיקון שנק' ישראל כו'. והב' מהו שאמר צדקת פרזונו למה ע\"י הצדקה דוקא כי מה שייכות יש<sup data-n=\"12275\">132</sup> צדקה [ל]ענין זה. אך הענין הוא דקושי' הב' תירוץ ל[קושי' ה]ראש[ונה], דלאחר שיובן ענין<sup data-n=\"12276\">133</sup> טעם צדקת פרזונו כו' ממילא יתורץ גם קושיא הא'. אך יש להקדים ענין א' בענין החיות שבמרכבה הנושאות את הכסא<sup data-n=\"12277\">134</sup> כידוע, לכאורה פלא גדול<sup data-n=\"12278\">135</sup> דבר זה האיך ביכולת המרכבה<sup data-n=\"12279\">*136</sup> שהם נבראים בע\"ג לרומם ולהעלות את הכסא שנא' בה על דמות הכסא כמראה אדם<sup data-n=\"12280\">136</sup> שהוא בחי' ז\"א דאצי' שנק' אדם דאצי' [כידוע]. אך הענין הוא להיות כי בחי' אדם שעל הכסא הוא בחי' אורות דתיקון שהוא אדם בציור הפרצוף אורות בריבוי כלים מכלים שונים, כמו פרצוף אדם שאברי האדם רבים הם עינים [ו]ידים [ו]פה [ו]אוזן וחוטם כו' וכן אברי' הפנימי' רבים הם כו'. וכ\"ז הוא בחי' התחלקות החיות לחלקים רבים שמזה נעשה בחי' ריבוי כלים כנ\"ל שההתחלקות והגבלה א' הוא וסיבת זה בא מצד הארת חו\"ב במדות כנ\"ל. אך הנה שרש החיות שבמרכבה כמו פני ארי' פני שור כו' נמשך מבחי' אורות דתהו שלמעלה מבחי' התיקון, כידוע שבחי' התהו עדיין לא הי' בחי' פרצוף אדם כלל רק בחי' בהמות וחיות בלבד (וכמו בבריאת הנבראי' למטה בי' מאמרות שהחיות והבהמות והעופות<sup data-n=\"12281\">137</sup> נברא[ו] תחלה לאדם וכמ\"ש תוצא הארץ נפש חי'<sup data-n=\"12282\">138</sup> כו' וכמארז\"ל אפי' יתוש קדמך<sup data-n=\"12283\">139</sup> וכמ\"ש במדרש ע\"פ אחור וקדם צרתני<sup data-n=\"12284\">140</sup> אחור למע\"ב כו'<sup data-n=\"12285\">141</sup> וקדם כו'. וככה יובן למעלה בבחי' האצי' שנאצלו בחי' אורות דתהו תחלה ואח\"כ בחי' אדם דתיקון כו'), וכמאמר הידוע באדר\"ז דבני עלמין<sup data-n=\"12286\">142</sup> ולא אתקיימו עד דאתבני פרצופא דאדם כו' (וכן בדרז\"ל הי' בונה עולמות ומחריבן<sup data-n=\"12287\">143</sup> ). וזהו הטעם שיש כח במרכבה לנשאות את הכסא כו' לפי ששרשם יותר נעלה מבחי' אדם דתיקון ע\"כ יש ביכולת להעלות לבחי' אדם למעלה מבחי' אדם, והוא מ\"ש כי לא אדם הוא להנחם דהיינו לבחי' מדות התהו שהם אורות תקיפים וחזקים הרבה כנ\"ל ואינם עשוים להשתנות מהיפך להיפך כנ\"ל, ואמנם בחי' המדות דתיקון עשוים להשתנו' ע\"פ השכל כנ\"ל וע\"כ אדם דתיקון עשוי להנחם משא\"כ בחי' המדות דתהו נאמר כי לא אדם הוא להנחם כו' וד\"ל.\n<b>אך</b> מה שיש בכח המרכבה לרומם לבחי' אדם דתיקון שעל הכסא כ\"כ, ולכאור' אין זה מובן דהלא החיות שבמרכבה נתהוו מאין ליש בבחי' מל' דאצי' שנק' ג\"כ אדם וכמ\"ש ופני",[["12275","132","<b>יש</b>: יד: ליתא."],["12276","133","<b>ענין</b>: זיד: ליתא."],["12277","134","<b>החיות. . הנושאות את הכסא</b>: נסמן לעיל קעט, ב."],["12278","135","<b>פלא גדול</b>: זיד: יפלא."],["12279","*136","<b>האיך ביכולת המרכבה</b>: ראה גם לקמן פ' ויקהל שצג, ד."],["12280","136","<b>על דמות הכסא כמראה אדם</b>: יחזקאל א, כו [ושם: ועל (נסמן לעיל פ' שמות כח, ג). . דמות כמראה]."],["12281","137","<b>והעופות</b>: ראה חולין כז, ב. רש\"י בראשית ב, ח (בסופו). יט."],["12282","138","<b>תוצא הארץ נפש חי'</b>: בראשית א, כד. ראה מאמרי אדה\"א דברים ח\"ד ע' א'שסד."],["12283","139","<b>אפי' יתוש קדמך</b>: ראה סנהדרין לח, א. ב\"ר פ\"א, ח."],["12284","140","<b>אחור וקדם צרתני</b>: תהלים קלט, ה. ראה ב\"ר שם."],["12285","141","<b>כו'</b>: זיד: ליתא."],["12286","142","<b>באדר\"ז דבני עלמין</b>: ראה זהר (אד\"ר) נשא קלה, א."],["12287","143","<b>הי' בונה עולמות ומחריבן</b>: קה\"ר פ\"ג, יא. יל\"ש שם רמז תתקסח. זח\"א בהשמטות רנב, סע\"ב. ב\"ר פ\"ג, ז."]]],[2300540485,"אדם לארבעתן<sup data-n=\"12288\">144</sup>, וגם ידוע בד' מחנות שכינה<sup data-n=\"12289\">145</sup> מחנה מיכאל במדריגת האהבה ומחנה גבריאל במדריגת היראה כו' כולם מקבלים מבחי' המל' ונק' י\"ב בקר והים עומד עליהם מלמעלה<sup data-n=\"12290\">146</sup> כו', והאיך יהי' בכוחם לרומם ולהעלות למקור חוצבם כו'. אך הענין ידוע שזהו כמו [למשל המאכל שמחי' לאדם הגם שהמאכל בחי' צומח כו', אך לפי ששרש] המאכל נמשך מבחי' התהו רק שנפל בשבה\"כ למטה מאד כו', וכך [בחי'] החיות שבמרכבה [ש]הם בחי' <span data-k=\"pg\">732</span> ּ [ה]תהו רק שנפלו למטה בשבה\"כ ונתגשמו. והמופת לזה ממה שאנו רואים בטבע מדות החיות והבהמות שהן תקיפים וחזקים הרבה יותר מן מדות שבאדם כנ\"ל בענין מדות הטבעי' שבבהמה כו', וגם בחי' המדות שבחיות שבמרכבה הם תקיפי' וחזקים מאד כי פני ארי' רק בחי' חסד בל ישנה תפקידו [לגבו'], ובחי' פני שור מהשמאל רק בחי' דין [וגם] לא ישנה תפקידו לעולם<sup data-n=\"12291\">147</sup> כו', וכן בד' מחנות מחנה מיכאל באהבה רבה בהתפעלות חזקה מאד כמו אהבה טבעי' הנ\"ל וכן מחנה גבריאל ביראה גדולה כ\"כ עד שמזיעתן של חיות<sup data-n=\"12292\">148</sup> כו'. והיינו מפני ששרשם מאורות דתהו ולכך יש ביכולתם להעלות לבחי' אדם שעל הכסא למעלה מעלה מבחי' אדם כנ\"ל וד\"ל.\n<b>ומעתה</b> יובן ג\"כ טעם ענין צדקת פרזונו שהוא ע\"י הצדקה דוקא כנ\"ל, דהנה בצדקה כתי' צדקה תרומם גוי<sup data-n=\"12293\">149</sup> פי' הפסוק<sup data-n=\"12294\">150</sup> הפשוט היינו הצדקה תרומם לבחי' נוגה דעשי' שנק' גוי<sup data-n=\"12295\">151</sup> כו'. וביאור הדבר הנה ארז\"ל<sup data-n=\"12296\">152</sup> דבחי' נוגה הוא להט החרב המתהפכת<sup data-n=\"12297\">153</sup> משום דמתהפך פעמים לטוב ופעמים לרע<sup data-n=\"12298\">154</sup> וכשא'<sup data-n=\"12299\">155</sup> הזהר דהאי נוגה מפתת לאתתא<sup data-n=\"12300\">156</sup> ונטלת נהורא כו', פי' כי ע\"ס דקדושה הם אורות עליונים שהם בבחי' אין דהיינו שהם בבחי' ביטול והתכללות ליכלל בעצמו' המאציל משום דאיהו וחיוהי חד<sup data-n=\"12301\">157</sup> בבחי' אין אמיתי כו'. אבל ע\"ס דקליפה את זה לעו\"ז<sup data-n=\"12302\">158</sup> עשה [ה]אלקי' שיהי' דוקא בחי' יש ודבר נפרד כו' היפך בחי' הביטול כו', כמו ע' שרים<sup data-n=\"12303\">159</sup> דקליפה שיודעים את רבונם ומכוונים למרוד<sup data-n=\"12304\">160</sup> לעשות א\"ע ליש ודבר כו' כמו שר של מצרים שא' לי יאורי<sup data-n=\"12305\">161</sup> ואני עשיתני<sup data-n=\"12306\">162</sup> כו' כמו שאמרו<sup data-n=\"12307\">163</sup> הגוים ידינו רמה ולא ה' פעל<sup data-n=\"12308\">164</sup> כו' כחי ועוצם ידי<sup data-n=\"12309\">165</sup> כו' וכיוצא. והממוצע ביניהם הוא בחי' נוגה, שהגם שהוא יש ו[דבר] נפרד לעצמו הוא מתבטל לפעמים לקדושה. ודוגמא לדבר זה אנו רואים בדצ\"ח",[["12288","144","<b>ופני אדם לארבעתן</b>: נסמן לעיל פ' שמות כח, א."],["12289","145","<b>בד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["12290","146","<b>י\"ב בקר והים. . מלמעלה</b>: מל\"א ז, כה. מד. דהי\"ב ד, טו."],["12291","147","<b>שבחיות שבמרכבה. . לא ישנה תפקידו לעולם</b>: ראה גם לעיל ריב, ד. וש\"נ."],["12292","148","<b>שמזיעתן של חיות</b>: חגיגה יג, ב."],["12293","149","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["12294","150","<b>הפסוק</b>: זיד: ליתא."],["12295","151","<b>נוגה דעשי' שנק' גוי</b>: ראה גם לעיל רמד, ד."],["12296","152","<b>ארז\"ל</b>: זיד: אמר(ו) בכ\"מ."],["12297","153","<b>נוגה הוא להט החרב המתהפכת</b>: נסמן לעיל רט, א."],["12298","154","<b>פעמים לטוב ופעמים לרע</b>: ראה תניא ‘\"ז (יא, ב). אוה\"ת מטות ע' א'דש ואילך."],["12299","155","<b>וכשא'</b>: וכמו שאמר. זיד: וכמאמ'."],["12300","156","<b>דהאי נוגה מפתת לאתתא</b>: ראה זהר ויקהל רג, ב."],["12301","157","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["12302","158","<b>את זה לעו\"ז</b>: נסמן לעיל פ' שמות לד, ג."],["12303","159","<b>ע' שרים</b>: נסמן לעיל פ' שמות לז, ג."],["12304","160","<b>שיודעים את רבונם ומכוונים למרוד</b>: נסמן לעיל פ' שמות ל, ג."],["12305","161","<b>שר. . לי יאורי</b>: נסמן לעיל פ' שמות ל, א."],["12306","162","<b>ואני עשיתני</b>: זיד: ליתא."],["12307","163","<b>שאמרו</b>: זיד: שאומרי'."],["12308","164","<b>ידינו רמה ולא ה' פעל</b>: האזינו לב, כז."],["12309","165","<b>כחי ועוצם ידי</b>: עקב ח, יז."]]],[2300540503,"שנמשכים מבחי' נוגה והם כל דברים המותרים לאכול<sup data-n=\"12310\">166</sup> (משא\"כ דברים האסורים נמשכו מג' קליפות<sup data-n=\"12311\">167</sup> הטמאות לגמרי כידוע), שכשהאדם אוכל אכילה גסה תמיד נתגשם מאד ונופל ברע גמור כמ\"ש וישמן ישורון ויבעט<sup data-n=\"12312\">168</sup> שמנת עבית כו' בניאוף ורציחה כו' וגזל וכה\"ג. ולפעמים יהי' להיפך שמן האכילה יתחזק שכלו להשגת שכלו<sup data-n=\"12313\">169</sup> ויתפעל יותר בתפלה (או כמו אכילת שבת שנאכל בקדושה ממש ואינו מתגשם<sup data-n=\"12314\">170</sup> ממנה לעולם כמ\"ש בענין לחם הפנים<sup data-n=\"12315\">171</sup> כו'). וזהו הוראה גמורה שבחי' נוגה שרש המאכל הוא בחי' ממוצע בין בחי' הפירוד לבחי' הביטול לפעמים הוא בבחי' הביטול כמו ע\"ס דקדושה ולפעמים הוא בבחי' הפירוד כמו ע\"ס דקליפה וע\"כ נק' להט החרב המתהפכת כו' וד\"ל. והנה כשהאדם נותן צדקה מיגיע כפו שבדצ\"ח הזה<sup data-n=\"12316\">172</sup> מעלה לבחי' ניצוצות דתהו שנפלו בנוגה כידוע ששרש בחי' נוגה הוא בעולם התהו כי שם נפל בשבירה כמ\"ש וימלוך וימת<sup data-n=\"12317\">173</sup> כו' ונק' ז' מלכים שמתו<sup data-n=\"12318\">174</sup>. וזהו צדקה תרומם גוי [ש]תרומם לבחי' נוגה שנק' גוי לבחי' התהו שקדם לתיקון כנ\"ל כמו בענין החיות שבמרכבה שנושאים את הכסא ג\"כ מטעם זה וד\"ל. וזהו טעם צדקת פרזונו ע\"י הצדקה דוקא, כי הצדקה למעלה מגיע לבחי' התהו שלפני התיקון כו', ובהגיע לשם ממשכת בחי' אור גדול ותוקף שבתהו שירד <span data-k=\"pg\">שסו</span> ּ ונמשך למטה בבחי' הכלים דתיקון שנק' ישראל כו', וז\"ש צדקת פרזונו בישראל כו'. ובזה יתורץ קושי' הראשונה איך יוגבל אורות דתהו בכלים דתיקון, כי הנה במצות הצדקה מיגיע כפו שבדצ\"ח דנוגה הרי נעשה מזה בחי' כלי לשכון בו אור אלקי, והיינו מטעם הידוע, כמו שהצדקה לעני להחיות רוח שפלים<sup data-n=\"12319\">175</sup> למטה כך למעלה נמשך אוא\"ס להחיות רוח שפלים כו' מטעם שמפני מעשה<sup data-n=\"12320\">176</sup> הצדקה נעשה בכלים דתהו שנפלו בנוגה בבחי' שבירה ע\"כ כשעולים למעלה נעש[י'] בחי' כלים רחבים להכיל את בחי' האורות הגדולים דתהו שהצדקה ממשכת למעלה. וז\"ש והי' מעשה הצדקה<sup data-n=\"12321\">177</sup> כו', בצדקה תרוממו<sup data-n=\"12322\">178</sup> בריבוי כלים להכיל את בחי' האור דפרזון דתהו כנ\"ל.\n<b>וזהו</b> מקול מחצצים<sup data-n=\"12323\">179</sup> בין משאבים שם יתנו צדקות ה' כו', פי' יתנו לשון תרגום<sup data-n=\"12324\">180</sup> הוא בהיות [כי] בחי' הבירורי' דנוגה הוא ע\"י החכ' דוקא כי בחכ' אתברירו<sup data-n=\"12325\">181</sup> כידוע. וז\"ש מקול מחצצים בין משאבים כו' כי החכ' נק'<sup data-n=\"12326\">182</sup> מעין<sup data-n=\"12327\">183</sup> להבינה<sup data-n=\"12328\">184</sup> כמ\"ש",[["12310","166","<b>נוגה. . דברים המותרים לאכול</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז</a>."],["12311","167","<b>דברים האסורים נמשכו מג' קליפות</b>: ראה תניא ספ\"ו."],["12312","168","<b>וישמן ישורון ויבעט</b>: האזינו לב, טו."],["12313","169","<b>להשגת שכלו</b>: ז: וישיג השגות אלקו'. יד: להשגת אלקות."],["12314","170","<b>אכילת שבת. . ואינו מתגשם</b>: ראה גם לעיל רי, ד. וש\"נ."],["12315","171","<b>לחם הפנים</b>: ראה גם לעיל רטז, א. הנסמן לעיל פ' בא קכז, ב הערה 679."],["12316","172","<b>הזה</b>: זיד: ה\"ז."],["12317","173","<b>וימלוך וימת</b>: וישלח לו, לב ואילך."],["12318","174","<b>ז' מלכים שמתו</b>: נסמן לעיל רמד, ד."],["12319","175","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["12320","176","<b>מטעם שמפני מעשה</b>: ז: מפני שמעשה."],["12321","177","<b>והי' מעשה הצדקה</b>: ישעי' לב, יז."],["12322","178","<b>בצדקה תרוממו </b>[זיד: תכונני]: ישעי' נד, יד."],["12323","179","<b>מקול מחצצים</b>: ס' שופטים ה, יא."],["12324","180","<b>יתנו לשון תרגום</b>: ראה מצו\"צ עה\"פ."],["12325","181","<b>בחכ' אתברירו</b>: נסמן לעיל פ' שמות י, ג."],["12326","182","<b>החכ' נק' מעין</b>: נסמן לעיל פ' בא קה, ב."],["12327","183","<b>מעין</b>: ז: אם(!) יד: ים. וראה בסמוך בפנים."],["12328","184","<b>להבינה</b>: שם: והבינה נק' נהר."]]],[2300540521,"בע\"ח בפי' שאול מרחובות הנהר<sup data-n=\"12329\">185</sup> כו', והנה עד\"מ המעיין שחוצבים<sup data-n=\"12330\">186</sup> אותו בהר קשה כך הוא בחי' החכ' שמברר בירורי נוגה לאהפכא חשוכא לנהורא<sup data-n=\"12331\">187</sup> כו', [ו]פי' משאבים היינו בחי' מים דבינה הנשאבים מ[ן ה]מעיין דחכ' לע\"ל וכמ\"ש ומעין יוצא מבית ה' והשקה<sup data-n=\"12332\">188</sup> כו' כמ\"ש ושאבתם מים בששון<sup data-n=\"12333\">189</sup> ממעייני הישועה (וכמ\"ש במ\"א בענין ניסוך המים בחג<sup data-n=\"12334\">190</sup>, ולמה נק' בית השואבה כו'). או יתפרש להיפך דמשאבים היינו השואבים מ[מי] החכ' לברר בירורים ומחצצים שבין משאבים הללו היינו לחצוב כל מסך מבדיל דנוגה. ולפ\"ז [יתפרש יותר כפשוטו שמחצצין באין בין משאבי' להוציא להאור<sup data-n=\"12335\">191</sup> עד למטה מטה וכן מעיינות תהום רבה נבקעו<sup data-n=\"12336\">192</sup> שהוא] מעיינות החכמה שנובעים<sup data-n=\"12337\">193</sup> ויוצאים דרך כל המסכים דנוגה ע\"י המחצצים כו' וד\"ל. ודוקא בחי'",[["12329","185","<b>בע\"ח בפי' שאול מרחובות הנהר</b>: בראשית לו, לז. ראה זהר (אד\"ר) נשא קמב, א. ע\"ח (שער דרושי נקודות) ש\"ח, פ\"ד. מבו\"ש ש\"ב ח\"ב, פ\"ח. עמה\"מ (שער עולם התוהו) ש\"ו, פמ\"ו (כה, א). פמ\"ח (כח, א). פנ\"א (ל, סע\"א ואילך)."],["12330","186","<b>שחוצבים</b>: יד: שמוצאין."],["12331","187","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["12332","188","<b>ומעין יוצא מבית ה' והשקה</b>: יואל ד, יח [ושם: מבית ה' יצא — ראה מאמרי אדה\"א דברים ח\"ג ע' א'א וש\"נ. שע\"ת סט, א ובהערה 1]."],["12333","189","<b>ושאבתם מים בששון</b>: ישעי' יב, ג."],["12334","190","<b>ניסוך המים בחג</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380913\" data-slug=\"likkutei-torah\" data-id=\"4001380913\">לקו\"ת נצבים מח, ג</a>. מאמרי אדה\"ז אתהלך ע' מט ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתנה."],["12335","191","<b>להאור</b>: ניתוסף ע\"פ ד."],["12336","192","<b>מעיינות תהום רבה נבקעו</b>: ע\"פ נח ז, יא."],["12337","193","<b>שנובעים</b>: זיד: שנבקעים."]]],[2300540539,"אחוריי' דחכ' הוא המברר בירורי נוגה ונק' נובלות חכ' שלמעלה תורה<sup data-n=\"12338\">194</sup> כו' כמ\"ש במ\"א בפי' ואתא מרבבות קדש<sup data-n=\"12339\">195</sup>, וזהו שם יתנו צדקות ה' יתנו לשון תרגום שהוא בחי' אחוריים דלה\"ק<sup data-n=\"12340\">196</sup> שהוא בחי' אחוריים דחכ' שנק' קדש<sup data-n=\"12341\">197</sup> כמבואר במ\"א וד\"ל. וזהו שאמרה דבורה חדלו פרזון בישראל חדלו<sup data-n=\"12342\">198</sup> שלא הי' אור דתהו מאיר בתיקון [מטעם ה]נ\"ל ע\"כ הי' סיסרא מושל על ישראל כי שרש ע\"ס דנוגה מז' מלכין קדמאין דתהו כנ\"ל. עד שקמתי דבורה<sup data-n=\"12343\">199</sup> שהוא בחי' עלי' המל' מן הבירורי' דנוגה כמ\"ש ותתן טרף<sup data-n=\"12344\">200</sup> כנ\"ל בביאור הראשון<sup data-n=\"12345\">201</sup> כו'<sup data-n=\"12346\">202</sup>, שקמתי אם בישראל<sup data-n=\"12347\">203</sup> היינו כמ\"ש הנני בורא חדשה<sup data-n=\"12348\">204</sup> נקבה תסובב גבר לפי שא\"ח תהי' עט\"ב<sup data-n=\"12349\">205</sup> ותהי' אם בישראל דתיקון שיהי'<sup data-n=\"12350\">206</sup> גילוי אורות דתהו בתיקון כנ\"ל וד\"ל.",[["12338","194","<b>נובלות חכ' שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["12339","195","<b>ואתא מרבבות קדש</b>: ברכה לג, ב. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' תקכז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381102\" data-slug=\"likkutei-torah\" data-id=\"4001381102\">לקו\"ת ברכה צג, ד</a> [ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381150\" data-slug=\"likkutei-torah\" data-id=\"4001381150\">לקו\"ת</a> ואתה אבל ראה שם שה\"ש ה, ב — ראה הנסמן במאמרי אדה\"א בראשית ע' כב]."],["12340","196","<b>תרגום. . אחוריים דלה\"ק</b>: ראה טעמי המצות — להרח\"ו — פ' ואתחנן ענין שמו\"ת."],["12341","197","<b>דחכ' שנק' קדש</b>: נסמן לעיל פ' וארא נח, ב."],["12342","198","<b>חדלו פרזון בישראל חדלו</b>: ס' שופטים פ\"ה, ז."],["12343","199","<b>עד שקמתי דבורה</b>: המשך הכתוב חדלו."],["12344","200","<b>ותתן טרף</b>: משלי לא, טו."],["12345","201","<b>בביאור הראשון</b>: לעיל רמה, ב."],["12346","202","<b>כו'</b>: ב: באריכות."],["12347","203","<b>שקמתי אם בישראל</b>: המשך הכתוב עד שקמתי דבורה."],["12348","204","<b>הנני בורא [יד נ</b>יתוסף: ארץ] חדשה: ירמי' לא, כא [ושם: כי ברא ה' — ראה מאמרי אדה\"א ויקרא ח\"ב ע' תערב. וש\"נ. שה\"א נז, א ובהערה 8]."],["12349","205","<b>שא\"ח. . עט\"ב</b>: משלי יב, ד."],["12350","206","<b>שיהי'</b>: זיד: שהוא."]]],[2300550041,"<b>בעזר\"ה</b>\n<span data-k=\"pg\">734</span> ּ<b>בחודש</b> השלישי<sup data-n=\"1\">1</sup> לצאת בנ\"י מאמ\"צ ביום הזה באו מדבר סיני<sup data-n=\"2\">2</sup> כו', וד[רשו] רז\"ל שהוא בר\"ח<sup data-n=\"3\">3</sup> סיון, כי מאחר שלא פי' באיזה יום באו למדו ממ\"ש בחדש הזה<sup data-n=\"4\">4</sup> וכתיב הכא ביום הזה כו'. וי\"ל למה חודש הזה דר\"ח סיון נשתנה משאר חדשים שלא פי' אותו להדיא אלא סתם וכתיב ביום הזה סתם, אע\"פ שפי' בחדש השלישי לא פי' שמו. אך יש להקדים תחלה שרש ענין קבלת התורה לישראל דוקא בזה הזמן, והלא כבר היו צדיקי' גדולים שהיו ראוים ליתן להם כל התורה והמצות כמו אברהם אע\"ה שהי' ראשון המאמינים<sup data-n=\"5\">5</sup> בהוי' אחד והי' בחי' מרכבה<sup data-n=\"6\">6</sup> ממש, שהרי נק' אברהם אוהבי<sup data-n=\"7\">7</sup> רחימא דמלכא<sup data-n=\"8\">8</sup> כו', וכתי' בי' הלוך ונסוע<sup data-n=\"9\">9</sup> כו' ואיתא בזהר שהי' הולך ועולה מדרגא לדרגא בעילוי אחר עילוי ברוב עומק עוז התקשרות ודביקות האמיתי בה' אחד<sup data-n=\"10\">10</sup> במס\"נ, ורוח אייתי רוח<sup data-n=\"11\">11</sup> כו' והי' שורה עליו אור אהבה רבה העליונה כמים הפנים אל פנים<sup data-n=\"12\">12</sup> כו'. ואע\"פ שקיים אברהם כל התומ\"צ<sup data-n=\"13\">13</sup> כמ\"ש עקב אשר שמע אברהם בקולי<sup data-n=\"14\">14</sup> וישמור משמרתי כו' וכתיב כי ידעתיו את אשר יצוה<sup data-n=\"15\">15</sup> את בניו [כו'] לעשות צדקה ומשפט כו', [הרי] עכ\"ז לא קיים רק ברוחניות ולישראל ניתנה התו\"מ בגשמיות וכמ\"ש במ\"א בפי' ושמי הוי' לא נודעתי להם<sup data-n=\"16\">16</sup> כו'. אך הנה ידוע שהתורה נק' עוז ותושי'<sup data-n=\"17\">17</sup> עוז וכח לנשמה האלקי' כמ\"ש ה' עוז לעמו יתן<sup data-n=\"18\">18</sup> ואין",[["1","1","<b>בחודש השלישי</b>: מיוסד על מאמר ד\"ה זה הנחת כ\"ק אדה\"א שנדפס במאמרי אדה\"ז תקס\"ז ע' קמו. והנחה אחרת בתו\"א ר\"פ יתרו סו, סע\"ג וראה בהנסמן במ\"מ לשם. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים לקמן בהמראי מקומות]."],["2","2","<b>בחודש השלישי. . סיני</b>: יתרו יט, א. בתו\"ח כאן: ביום — תוקן בפנים ע\"פ כל הכת\"י."],["3","3","<b>וד[רשו] רז\"ל שהוא בר\"ח</b>: שבת פו, ב."],["4","4","<b>בחדש הזה</b>: בא יב, ב [ושם החדש — וכן לכאו' צ\"ל כאן]."],["5","5","<b>אברהם. . ראשון המאמינים</b>: [גד: הראשון שהאמין]: ראה שמו\"ר פכ\"ג, ה. שהש\"ר פ\"ד ח, ג."],["6","6","<b>אברהם. . מרכבה</b>: ראה להלן הערה 55."],["7","7","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["8","8","<b>רחימא דמלכא</b>: ראה זהר ואתחנן רסב, ב. מאמרי אדה\"א שמות ח\"ב ע' שמג. וש\"נ."],["9","9","<b>הלוך ונסוע</b>: לך יב, ט. ראה זהר לך פ, א. פד, א."],["10","10","<b>אחד</b>: גד: ליתא."],["11","11","<b>ורוח אייתי רוח</b>: ראה זהר תרומה קסב, רע\"א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["12","12","<b>כמים הפנים אל פנים</b>: נסמן לקמן פ' משפטים רצ, ב."],["13","13","<b>התומ\"צ</b>: ד: התורה כולה עד שלא ניתנה וגם כל המצות."],["14","14","<b>עקב אשר שמע אברהם בקולי</b>: תולדות כו, ה."],["15","15","<b>כי ידעתיו את אשר יצוה</b>: וירא יח, יט [ושם למען אשר יצוה וכ\"ה בד — אמנם כהלשון בפנים מובא גם לקמן רנז, ג. ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670485\" data-slug=\"torat-chaim\" data-id=\"2300670485\">תו\"ח לך פט, א</a>. ג: כי ידעתיו אשר יצוה — ראה מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע שלט. לקמן פ' ויקהל תלג, א. ש\"א נ, ב ובהערה 41]."],["16","16","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' יב. מאמרי אדה\"א בראשית ע' קעט. שמות ח\"א ע' רנז ובהנסמן בהנ\"ל. ש\"א נ, א. לקמן רנז, ג."],["17","17","<b>שהתורה נק' עוז ותושי'</b>: ראה מכילתא דרשב\"י יתרו פי\"ט, טז. לעיל פ' בשלח קפד, א. וש\"נ."],["18","18","<b>ה' עוז לעמו יתן</b>: תהלים כט, יא."]]],[2300550073,"עוז אלא תורה<sup data-n=\"19\">19</sup> וכמ\"ש חגרה בעוז מתני'<sup data-n=\"20\">20</sup> כו', ותושי' שמתשת כח הגוף החומרי והא בהא תליא שכבר<sup data-n=\"21\">21</sup> היא עוז לנשמה ממילא מתשת כח הגוף וכמ\"ש בזהר תוקפא דנפשא חולשא דגופא<sup data-n=\"22\">22</sup>.\n<b>ולהבין</b> זה יש להבין<sup data-n=\"23\">23</sup> תחלה שרש ענין אהבה דאברהם אוהבי [הנ\"ל, שה]אבות סימן לבנים<sup data-n=\"24\">24</sup> ויש מעין אהבה זו בכל א' וא' מישראל מצד [ה]ירושה מאבותינו<sup data-n=\"25\">25</sup> שנטוע ומושרש כמו טבע בנפשינו, עד שכל א' יכול לומר מתי יגיעו מעשי למעשה אבותי<sup data-n=\"26\">26</sup>. והנה המסעות דאברהם הי' תחלה בארץ כנען שהוא א\"י דכתי' (בפ' לך לך) ויעבור אברם בארץ<sup data-n=\"27\">27</sup> עד מקום שכם כו', ויאמר לזרעך אתן את הארץ הזאת<sup data-n=\"28\">28</sup> [כו'] ויעתק משם ההרה<sup data-n=\"29\">29</sup> כו' עד ויסע אברם הלוך ונסוע הנגבה<sup data-n=\"30\">30</sup> ואח\"כ אמר וירד אברם מצרימה<sup data-n=\"31\">31</sup> לגור שם עד ויעל אברם ממצרים<sup data-n=\"32\">32</sup> הוא ואשתו וכל אשר לו<sup data-n=\"33\">33</sup> הנגבה וילך למסעיו<sup data-n=\"34\">34</sup> כו' עד [אל] מקום המזבח כו' ויקרא שם בשם ה'<sup data-n=\"35\">35</sup>. והענין הוא דאבות סימן לבנים והי' מסעות שלו בא\"י הלוך ונסוע הנגבה שזה הי' כח ועוז לבניו לקיים התומ\"צ בארץ<sup data-n=\"36\">36</sup> ע\"י כל היחודים העליונים באהבה<sup data-n=\"37\">37</sup> ודביקות במס\"נ עד מקום המזבח שעשה ויקרא שם [בשם ה'] כו', ואח\"ז ירד למצרים לבער<sup data-n=\"38\">38</sup> הרע דקליפת מצרים וכמ\"ש ויעל אברם ממצרים כו' שעלה משם בקדושה יתירה ע\"י בירור והכנעת הרע בתכלית לאהפכא חשוכא לנהורא<sup data-n=\"39\">39</sup> כו', וזה הי' כח ועוז לבניו להיות בכוחם לסור מרע בתכלית, והוא מה שנתנה להם התורה [ומצות] שנק' עוז ותושי' עוז לנשמה ותושי' להתיש הסט\"א כו' וד\"ל.\n<b>וביאור</b> הדברים<sup data-n=\"40\">40</sup> יובן בענין מהות התפעלו' אהבה האלקי' בכל אדם שעיקר מהות התפעלות הזאת אינו רק ענין ובחי' הזזה והעתקה שנעתק וניזוז ממקומו הראשון, כמו <span data-k=\"pg\">שסז</span> ּ ההולך ונוסע ממקום למקום אחר שכ[ל] שהולך ונסע ונתקרב למקום שהלך לשם הרי לפ\"ע זה נתרחק יותר ממקום הראשון<sup data-n=\"41\">41</sup> שיצא משם. כך כל שנתקרב האדם יותר בקרבת אלקי' ע\"י בחי' התפעלות עומק הלב באהבה ותשוקה [אלקי'] לידבק בה' אחד",[["19","19","<b>ואין עוז אלא תורה</b>: ראה ספרי ברכה לג, ב. הנסמן לעיל קפג, ג."],["20","20","<b>חגרה בעוז מתני'</b>: משלי לא, יז."],["21","21","<b>שכבר</b>: גד: שכאשר."],["22","22","<b>תוקפא דנפשא חולשא דגופא</b>: ראה זהר וישב קפ, ב. תולדות קמ, ב."],["23","23","<b>להבין</b>: גד: להקדים."],["24","24","<b>שה]אבות סימן לבנים</b>: ראה ב\"ר פ\"מ, ו. הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251123\" data-slug=\"likkutei-sichot\" data-id=\"1300251123\">לקו\"ש תולדות (כרך כה) ע' 123</a>."],["25","25","<b>אהבה. . [ה]ירושה מאבותינו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["26","26","<b>מתי יגיעו מעשי למעשי אבותי</b>: ראה תדא\"ר ר\"פ כה. תו\"ח ויצא קעו, ב ובהערה 36."],["27","27","<b>ויעבור אברם בארץ</b>: לך יב, ו."],["28","28","<b>ויאמר לזרעך אתן את הארץ הזאת</b>: שם יב, ז."],["29","29","<b>ויעתק משם ההרה</b>: לך שם, ח."],["30","30","<b>ויסע אברם. . הנגבה</b>: שם יב, ט."],["31","31","<b>וירד אברם מצרימה</b>: לך שם, י."],["32","32","<b>ויעל אברם ממצרים</b>: לך יג, א."],["33","33","<b>וכל אשר לו</b>: גד: כו'."],["34","34","<b>וילך למסעיו</b>: שם יג, ג."],["35","35","<b>[אל] מקום. . בשם ה'</b>: לך שם, ד [בדילוג]."],["36","36","<b>בארץ</b>: גד: בא\"י."],["37","37","<b>באהבה</b>: שם: (ש)באה\"ר."],["38","38","<b>לבער</b>: שם: לברר."],["39","39","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["40","40","<b>הדברים</b>: גד: הענין."],["41","41","<b>הראשון</b>: שם: ליתא."]]],[2300550105,"לבדו, כך לפ\"ע זה נתרחק ונעתק ממקום התקשרותו בחומרי הגוף כו', כמשל עוף הפורח באויר למקום [מחוז] חפצו, או אדם השט במים שמפני גודל חפצו ורצונו לבא למקום זה שרוצה לקרב<sup data-n=\"42\">42</sup> אליו בכל כחו עי\"ז נתרחק [ב]כל השטה יותר ממקומו הראשון כו'. וכך בכל עת התפעלות אהבה ורצון מעומק הלב ביותר מדי יום ביום עי\"ז נתרחק ונעתק וניזוז יותר מכל רצון זר הגופני עד שכאשר יוגבר עוז אהבה רבה בכלות הנפש לה' ממש אז י[ת]רחק ויופשט לגמרי בריחוק גדול יותר מכל רצון זר עד שהוא מואס ברע בתכלית ולבו חלל בקרבו<sup data-n=\"43\">43</sup> כו'. ונמצא מובן שכל שהנשמה נתחזקה בכחה ביותר בקשר אמיץ וחזק מאד באלקות נעשה חולשת כח ביותר לנפש הטבעי' החומרית, כמ\"ש בזה\"ק תוקפא דנפשא חולשא דגופא ובהיפוך תוקפא דגופא חולשא דנפשא<sup data-n=\"44\">44</sup> דאת זה לעו\"ז<sup data-n=\"45\">45</sup> כו' וכמ\"ש ולאום מלאום יאמץ<sup data-n=\"46\">46</sup> כו' כשזה קם זה נופל<sup data-n=\"47\">47</sup> כידוע, בהיות הנשמה והגוף המה ב' הפכים מנגדים ממש כמ\"ש כי רוח האדם<sup data-n=\"48\">48</sup> הוא העולה למעלה ורוח הבהמה יורדת למטה בגופני', וידוע שהנפש האלקי' [היא] מוגבלת ומצומצמת במאסר חומר הגוף עד שגם אם נפש האלקי' [נ]תפעל[ה] באהוי\"ר שכליי' בחו\"ב שבה עומד לנגדה חומר הגס הגופני הנק' רוח הבהמה ממש שלא תוכל לעלות ולילך<sup data-n=\"49\">49</sup> למעלה כמו שלא יוכל אדם לצאת ממאסר ותפיסת המלך<sup data-n=\"50\">50</sup>, אך כאשר תתגבר הנה\"א להתפעל באה\"ר [ב]תוקף גדול מאד אזי יחלש כח החומר[י] ויפול ותצא ממאסר<sup data-n=\"51\">51</sup> הגופני נקי מכל סיג עד שיהי' לו רק לב אחד לאביו שבשמים<sup data-n=\"52\">52</sup> כו' כמו כלה שארי<sup data-n=\"53\">53</sup> כו'. ונמצא יש כאן ב' ענינים, א' שיצא ממאסר<sup data-n=\"54\">54</sup> גסות הגופני, והב' שעלתה ונתדבקה באלקים חיים, אמנם קירוב ודיבוק זה באלקות הוא העושה הריחוק שנתרחקה והופשטה מגסות הגופני.\n<b>ומזה</b> יובן בקצת דוגמא עכ\"פ לאמיתית אור האהבה האלקי' שהי' באברהם אוהבי הנ\"ל כמ\"ש הלוך ונסוע מדרגא לדרגא כו' שהאבות הן המרכבה<sup data-n=\"55\">55</sup> ממש כידוע, דהיינו שהי' נפשו דבוקה וקשורה [למעלה] באלקי' חיים ממש בבחי' קירוב גמור והי' הולך ועולה במעלות [ו]מדרגות התקשרו' ודביקות אמיתי זו מדי יום [ו]יום בעומק אחר עומק ועילוי אחר עילוי יותר. [ו]זהו הלוך ונסוע כמשל הנסיעה שנעתק ממקום למקום כו' שנתדבקו ונתקרבו יותר באור האלקי בכלות הנפש יותר נתרחק בהפשטת הגופני לגמרי מכל וכל כו', וזהו שהי' מסעות",[["42","42","<b>שרוצה לקרב</b>: שם: הולך ונתקרב."],["43","43","<b>ולבו חלל בקרבו</b>: ע\"פ תהלים קט, כב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשנד. וש\"נ. שמות ח\"ב ע' תעה."],["44","44","<b>תוקפא דגופא חולשא דנפשא</b>: ראה לעיל הערה 22."],["45","45","<b>דאת זה לעו\"ז</b>: קהלת ז, יד. ראה ביאוה\"ז פקודי נט, ב. מאמרי אדה\"א שמות ח\"ב ע' תצה. שע\"ת סט, א ובהערה 10."],["46","46","<b>ולאום מלאום יאמץ</b>: תולדות כה, כג. ראה מאמרי אדה\"א דברים ח\"ד ע' א'תצה. וש\"נ."],["47","47","<b>כשזה קם זה נופל</b>: רש\"י תולדות כה, כג."],["48","48","<b>כי רוח האדם</b>: קהלת ג, כא [ושם: מי יודע רוח בני האדם העולה היא למעלה ורוח הבהמה היורדת היא למטה — בהוספת תיבת ”כי\" מובא גם לעיל עט, ב. וש\"נ]."],["49","49","<b>ולילך</b>: גד: ולידבק."],["50","50","<b>ותפיסת המלך</b>: שם: ותפיסה ממש."],["51","51","<b>ממאסר</b>: שם: מחומר."],["52","52","<b>לב אחד לאביו שבשמים</b>: ברכות נז, א."],["53","53","<b>כלה שארי</b>: תהלים עג, כו."],["54","54","<b>ממאסר</b>: גד: מנרתק."],["55","55","<b>שהאבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה לקמן פ' משפטים ש, ג על יד הערה 384. מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 42."]]],[2300550137,"שלו תחלה בא\"י להיות הולך וקרב אלי'<sup data-n=\"56\">56</sup> עד רום המעלות שהוא הנגבה תוקפא דדרום שהוא תוקף האה\"ר העליונה. ואח\"כ א' ויעל אברם ממצרים שהי' ביכולתו לעלות מכל טומאת מצרים הוא ואשתו וכל אשר לו לבער ולברר הרע בתכלית, לפי שזה הי' לפ\"ע עוצם מעלתו<sup data-n=\"57\">57</sup> ודביקותו במסעות שלו בא\"י עד ששב והולך למסע[י]ו [בא\"י] אל מקום המזבח ויקרא שם בשם הוי' בתוס' <span data-k=\"pg\">736</span> ּ עילוי יותר מבתחילה מטעם יתרון אור מן החשך<sup data-n=\"58\">58</sup> כאשר נהפך חשך לאור כידוע וד\"ל. ואבות סימן לבנים להיות גם בהם עוז וכח התפעלות וקרבת אלקי' בכאו\"א בכל דור ודור וזמן הולך ונוסע כו', עד שלפ\"ע יוכל כל א' לצאת ממצרים בכל יום שהוא לצאת מחומר הגופני המחשיך על אור הנשמה ולהיות סור מרע לאכפייא או למאוס ברע לאהפכא כו' כמ\"ש באברהם ויעל אברם ממצרים כו' כנ\"ל. רק שא\"א להיות זה בישראל כמו שהי' באברהם ממש כ\"א ע\"י התורה שנק' עוז ותושי' עוז לנשמה האלקי' שיהי' בה תוקף התגברות האה\"ר במס\"נ, וממילא תושי' להתיש כח הגוף לצאת ממצרים מן המיצר וצמצום דחשך [ד]קליפת נוגה משום דהא בהא תליא לפ\"ע כו' וד\"ל.\n<b>והנה</b> בסדר התפלה צ\"ל תחילה בחי' לב נשבר ונדכה קודם התפלה בתשובה אמיתי' על ח\"נ במרירות ושפלות והכנעה יתירה כמאמר שאין מתפללים אלא מתוך כובד ראש<sup data-n=\"59\">59</sup> כו', ולפ\"ע זה דוקא יוכל להיות התפעלות אלקי' באהוי\"ר בהתבוננו' גדולת ה' בפסוד\"ז עד ק\"ש ושמו\"ע, וכמ\"ש מי זאת עולה מן המדבר<sup data-n=\"60\">60</sup> מק\"נ ואח\"כ מתרפקת על דודה<sup data-n=\"61\">61</sup> בפסוד\"ז כו' וכידוע בסדר ד' תיקונין מטה שולחן כסא ומנורה<sup data-n=\"62\">62</sup> כו', וכמ\"ש סו\"מ ואח\"כ ועשה טוב<sup data-n=\"63\">63</sup> וכמו שהי' ביצ\"מ שיצאו מן הרע דנו\"ן שערי טומאה<sup data-n=\"64\">64</sup> תחילה מאפילה לאור גדול דמ\"ת כו', ובאברהם הי' מסעות שלו בא\"י תחילה בבחי' קירוב ודביקות כו' ואח\"כ נסע וירד למצרים לבער הרע כו'. ואע\"פ שהאבות סימן לבנים כו' וא\"כ הי' ראוי שיהי' בבנים ג\"כ כמו באבות, הענין הוא דאברהם הי' בחי' מרכבה ממש לאה\"ר העליונה [ד]חסד דאצי' כמ\"ש אברהם אוהבי והי' בו תחילה גילוי אור האלקי דאצי' מלמעלה למטה בבחי' ירידה והמשכה דרוח אייתי רוח ואמשיך רוח כו', וע\"כ הי' תחלה מסעות שלו בא\"י ששם מקור<sup data-n=\"65\">65</sup> גילוי שכינה מלמעלה למטה כמ\"ש אל מקום המזבח כו'. ולפ\"ע תוקף גילוי אור<sup data-n=\"66\">66</sup> ירידת אור דיחו\"ע<sup data-n=\"67\">67</sup> דאצי' בבי\"ע ע\"י מסעות בא\"י כן הי' בחי' הבירורי' שלו [ב]מצרים לבער הרע, לפי שגופו הי'",[["56","56","<b>אלי'</b>: גד: אל ה'."],["57","57","<b>מעלתו</b>: שם: עלייתו."],["58","58","<b>יתרון אור מן החשך</b>: קהלת ב, יג. ראה מאמרי אדה\"א ויקרא ח\"א ע' קסט. וש\"נ. בראשית ע' קפ. וש\"נ. לעיל פ' בא פח, א הערה 46."],["59","59","<b>שאין מתפללים. . כובד ראש</b>: ברכות ל, ב. ראה גם לעיל קעז, א."],["60","60","<b>מי זאת עולה מן המדבר</b>: שה\"ש ח, ה. ראה גם לקמן פ' תצוה שיח, ד ואילך. לעיל פ' בא קכב, ד. וש\"נ."],["61","61","<b>מתרפקת על דודה</b>: גד: יפה כלבנה — שה\"ש ו, י. וראה לקמן על יד הערה 282."],["62","62","<b>מטה שולחן כסא ומנורה</b>: ראה זהר תרומה קלג, א. לעיל פ' וארא עד, ב. וש\"נ."],["63","63","<b>סו\"מ. . ועשה טוב</b>: תהלים לד, טו."],["64","64","<b>דנו\"ן שערי טומאה</b>: ראה גם לקמן פ' תצוה שכה, א. שע\"ת ד, ב ובנסמן במ\"מ לשם."],["65","65","<b>מקור</b>: גד: מקום."],["66","66","<b>אור</b>: שם: ליתא."],["67","67","<b>דיחו\"ע</b>: ג: דחסד עליון. ד: דחכמה עילאה."]]],[2300550169,"מופשט מגשמיות כמו בנשמתו שזהו ענין בחי' המרכבה, וידוע שהאבות היו מעין העוה\"ב<sup data-n=\"68\">69</sup> שהגשמיות אינו מסתיר לרוחני' כלל ולכך הי' ברכתם בגשמי' כמו ברוחני' בשוה (וראי'<sup data-n=\"69\">68</sup> ממה שרדף אחר המלכים<sup data-n=\"70\">70</sup> כו'). אבל כאשר נמשך מהשרש אל הענפי' שהן בנ\"י, הרי צ\"ל בהיפך שמתחילה יעלה מן הרע כענין כובד ראש הנ\"ל וכיצ\"מ שקודם מ\"ת, ולפי שגם אם תתפעל הנשמה אלקי' באהוי\"ר אמיתי' לא יועיל להפוך חומר גסות וחומריות<sup data-n=\"71\">71</sup> הגופני להיות שהארה אלקי' שבנשמה מצומצמת מאד, והוא [ב]מאסר גמור בחומר הגופני עד שגם בהתפעלות הנשמה יחשיך עלי' גסות וחומרי' הגוף ומונע לנשמה לעלות בדביקות כו', רק שצ\"ל יצ\"מ תחלה שהוא לצאת מן הרע ע\"י תשובה בלב נשבר כו', וכל שנתרחק יותר מן הרע החומרי יותר יתקרב לה' בהתפעלו' הנשמה באהוי\"ר בפסוד\"ז עד ק\"ש כנ\"ל, וזהו הנסיעה שנתרחק ממקומו הראשון כנ\"ל וכמ\"ש אחרי ה' תלכו<sup data-n=\"72\">72</sup>. אבל באברהם הי' להיפך כמ\"ש התהלך לפני<sup data-n=\"73\">73</sup> דוקא כנ\"ל<sup data-n=\"74\">74</sup>, והוא כל מה<sup data-n=\"75\">75</sup> שבא לקירוב יותר בתחילה יותר נתרחק מן הרע עד שהי' בכחו לברר ולהוציא כל חלקי הטוב שנפל בק\"נ כמ\"ש <span data-k=\"pg\">שסח</span> ּ ויעל אברם כו'. וכך הוא ג\"כ בענין עוז ותושי' דתורה שתחילה עוז לנשמה להיות הארת אור האלקי יורד ונמשך בה לחזק כחה ביותר בהתפעלות אהוי\"ר כו', לפי שהתורה נקרא מזון לנשמה<sup data-n=\"76\">76</sup> ממש כמ\"ש כי אמרתך חייתני<sup data-n=\"77\">77</sup> וכמ\"ש כי הוא חייך<sup data-n=\"78\">78</sup> כו', ואח\"כ תושי' ממילא להתיש כח הסט\"א כו', לפי שהתורה מלמעלה למטה ירדה כו' (אבל כאשר ניתנה התורה לישראל שהוא הבירור דעה\"ד טו\"ר מלמטה למעלה צ\"ל תחלה סו\"מ דשס\"ה ל\"ת ואח\"כ ועשה טוב דרמ\"ח מ\"ע<sup data-n=\"79\">79</sup>, אבל בירידת התורה נא' אנכי תחלה<sup data-n=\"80\">*80</sup> שכולל לרמ\"ח מ\"ע ואח\"כ ולא יהי' לך שכולל לשס\"ה ל\"ת)<sup data-n=\"81\">80</sup> ומ\"ש במ\"א בענין שמי עם י\"ה<sup data-n=\"82\">*82</sup> שס\"ה<sup data-n=\"83\">82</sup> ל\"ת והרי י\"ה קודם לו\"ה דרמ\"ח מ\"ע זהו מצד בחי' העלא' דרפ\"ח כו'<sup data-n=\"84\">81</sup>.\n<b>אך</b> הנה עדיין יש להבין למה צריך לקבלת התורה שתהי' עוז לנשמה ותושי' לגוף כו', אחר שכבר הוטבע מאברהם בדרך ירושה דאבות סימן לבנים כו' שיש ביכולת כאו\"א להיות סו\"מ",[["68","69","<b>שהאבות היו מעין העוה\"ב</b>: ראה ב\"ב טז, סע\"ב ואילך. לעיל פ' בשלח קצו, א."],["69","68","<b>שזהו. . (וראי'</b>: גד: (שזהו. . וראי'."],["70","70","<b>שרדף אחר המלכים</b>: לך יד, יד ואילך. ראה מאמרי אדה\"ז הקצרים ע' קמה. שע\"ת נא, ב. לקמן פ' ויקהל תכט, א."],["71","71","<b>וחומריות</b>: גד: ליתא."],["72","72","<b>אחרי ה' תלכו</b>: פ' ראה יג, ה [ושם: ה\"א]."],["73","73","<b>התהלך לפני</b>: לך יז, א."],["74","74","<b>כנ\"ל</b>: ג: ליתא."],["75","75","<b>מה</b>: גד: ליתא."],["76","76","<b>שהתורה. . מזון לנשמה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a> ובמ\"מ הגהות והערות קצרות שם מציין: זח\"ב סא, ב."],["77","77","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["78","78","<b>כי הוא חייך</b>: נצבים ל, כ."],["79","79","<b>דשס\"ה ל\"ת. . דרמ\"ח מ\"ע</b>: מכות כג, סע\"ב."],["80","*80","<b>בירידת התורה נא' אנכי תחלה</b>: ראה לקמן פ' פקודי תנו, ד."],["81","80","<b>אנכי. . לרמ\"ח מ\"ע. . ולא יהי' לך. . לשס\"ה ל\"ת</b>: יתרו כ, ב. ג. ראה זח\"ב (יתרו) צא, א. (תוספות) רעו, א. של\"ה ר\"פ יתרו (שטו, ב). תניא רפ\"כ."],["82","*82","<b>בענין שמי עם י\"ה</b>: ראה לקמן פ' פקודי תמב, ד. תמו, א ואילך. תנ, ג. תנב, ג ואילך."],["83","82","<b>שמי עם י\"ה שס\"ה</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a> מציין: ת\"ז בהקדמה ד' ד' סע\"ב. וד' ה' ע\"א (וראה הנסמן במראי מקומות לשם). לעיל פ' בא קיד, א הערה 152."],["84","81","<b>ל\"ת). . כו'</b>: גד: ל\"ת. . כו')."]]],[2300550201,"ועשה טוב בפ\"מ<sup data-n=\"85\">83</sup> עכ\"פ יהי' איך שיהי'. אמנם הנה י\"ל תחלה ענין הידוע במהות ההתבוננו' שמחמתה תתפעל הנשמה וגם הנה\"ט<sup data-n=\"86\">84</sup> בלב בשר החומרי כו'. וידוע שיש בזה ב' מדרגות, א' בבחי' ממכ\"ע<sup data-n=\"87\">85</sup> שהוא בחי' שם אלקי'<sup data-n=\"88\">86</sup> כו', והוא כאשר מתבונן האדם איך שהוא ית' מחי' ומהווה את כל העולמות מאין ליש ממש בכל רגע ורגע כמ\"ש ואתה מחי' את כולם<sup data-n=\"89\">87</sup> וכתיב מלכותך מכ\"ע<sup data-n=\"90\">88</sup>, שבחי' השפעה האלקי' הזאת נמשך ע\"י בחי' המל' שהוא בחי' הדיבור<sup data-n=\"91\">89</sup> העליון כמ\"ש דבר מלך שלטון<sup data-n=\"92\">90</sup> כמלך שגוזר וכן יקום, כן בדבר [ה'] שמים נעשו<sup data-n=\"93\">91</sup> וברוח פיו כו' כמו ויאמר [ה'] יהי אור<sup data-n=\"94\">92</sup> ויהי אור וכן כל מע\"ב, וכן<sup data-n=\"95\">93</sup> בוי\"ו ימי בראשית כך מחדש בכל יום מע\"ב ע\"י בחי' אותיות הדבור דוקא, וע\"כ נתחלקו לרבוא רבבות עולמות עד אין שיעור כמ\"ש היש מספר לגדודיו<sup data-n=\"96\">94</sup> כו' מצד רבוא רבבות צירופי אותיות כמ\"ש בס\"י וקבען בפה<sup data-n=\"97\">95</sup> כו' ה' אבנים בונות ק\"כ בתים<sup data-n=\"98\">96</sup> שהם ק\"כ צירופי' ומכאן ואילך צא וחשוב כו' כידוע. ועד\"מ באדם שיש צירופי אותיות רבים עד אין שיעור בדבור וכללותן אינו רק חכ' ושכל א' הכוללם יחד, כך כתי' מה רבו מעשיך ה' כולם בחכ' עשית<sup data-n=\"99\">97</sup> חכמה א' ונק' ח\"ת חכ' שבדבור והוא מאמר דבראשית בחוכמתא<sup data-n=\"100\">98</sup>, כידוע דהמאמר דבראשי' נמי מאמר הוא<sup data-n=\"101\">99</sup> רק שהוא מאמר כללי<sup data-n=\"102\">100</sup> שהוא כולל כל המאמרות בכלל שכולל כל הפרטים המסתעפים ממנו כו', ושרש של הראשון דחכ' זו שבדבור הוא בחכ' שבראש שנק' ח\"ע כידוע, וע\"ז אמר והחכ' מאין תמצא<sup data-n=\"103\">101</sup> גם על ח\"ע כמ\"ש במ\"א.\n<b>וזהו</b> התחלת והקדמת פסוד\"ז הכוללת כל השבחים במאמרו ברוך שאמר והי' העולם, פי' שאמר מאמר א' לבד<sup data-n=\"104\">102</sup> שזהו מאמר דבראשית כמ\"ש והלא במאמר א' יכול להבראות<sup data-n=\"105\">103</sup> אלא שנתחלקו ליו\"ד מאמרות [ול]צרופי' רבים עד אין שיעור כו' שזהו בחי' החכ' שכוללת לכל הכחות הנמצאים מפרטי צירופי אותיות של הדבור וכמ\"ש כולם בחכ' עשית (ועוד יתפרש שאמר והי' העולם ממילא כמו הוא צוה ונבראו<sup data-n=\"106\">104</sup> דהיינו בבחי' הרצה\"ע שלמעלה גם מהחכ', כי פי' שאמר <span data-k=\"pg\">738</span> ּ שרצה<sup data-n=\"107\">105</sup> כמו כי אמרתי עולם [חסד יבנה<sup data-n=\"108\">106</sup> ] כו', וכתרגום בראשית בקדמין<sup data-n=\"109\">107</sup> כו'",[["85","83","<b>בפ\"מ</b>: גד: ליתא."],["86","84","<b>הנה\"ט</b>: ד: הנפש השכלית."],["87","85","<b>ממכ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."],["88","86","<b>ממכ\"ע. . שם אלקי'</b>: ראה גם לעיל פ' וארא עג, ב. וש\"נ."],["89","87","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["90","88","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["91","89","<b>המל'. . הדיבור</b>: ראה זהר לך פו, ב. לעיל פ' שמות לד, א. וש\"נ."],["92","90","<b>דבר מלך שלטון</b>: קהלת ח, ד."],["93","91","<b>בדבר [ה'] שמים נעשו</b>: תהלים לג, ו."],["94","92","<b>ויאמר [ה'] יהי אור</b>: בראשית א, ג."],["95","93","<b>וכן</b>: גד: וכמו."],["96","94","<b>היש מספר לגדודיו</b>: איוב כה, ג."],["97","95","<b>וקבען בפה</b>: ראה ס\"י פ\"ב, מ\"ג."],["98","96","<b>ה' אבנים בונות ק\"כ בתים</b>: ראה ס\"י פ\"ד, מי\"ב [הלשון שהובא בפנים הוא במהדורת מנטובא שכ\"ב — צילום ירושלים תשכ\"ב פ\"ד, מ\"ד — בדילוג]."],["99","97","<b>מה רבו מעשיך. . עשית</b>: תהלים קד, כד."],["100","98","<b>דבראשית בחוכמתא</b>: בראשית א, א וראה תרגום ירושלמי שם."],["101","99","<b>דבראשי' נמי מאמר הוא</b>: ר\"ה לב, א."],["102","100","<b>מאמר כללי</b>: נסמן בסמוך הערה 103."],["103","101","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה לעיל פ, ב."],["104","102","<b>ברוך שאמר. . מאמר א' לבד</b>: נוסח ברוך שאמר. ראה גם שע\"ת עג, א ובהערה 26."],["105","103","<b>מאמר דבראשית. . והלא במאמר א' יכול להבראות</b>: אבות רפ\"ה. ראה מאמרי אדה\"א דברים ח\"ב ע' תעז. קונטרסים ע' תקלו ובהנסמן בהנ\"ל. לקמן רסה, ב."],["106","104","<b>הוא צוה ונבראו</b>: תהלים קמח, ה. ראה גם שערי אורה סט, רע\"א. וש\"נ."],["107","105","<b>שאמר שרצה</b>: ראה גם לעיל פ' בא קכו, ב. וש\"נ."],["108","106","<b>כי אמרתי. . יבנה</b>: תהלים פט, ג."],["109","107","<b>וכתרגום בראשית בקדמין</b>: ת\"א לבראשית א, א."]]],[2300550233,"שקדם לח\"ע<sup data-n=\"110\">108</sup> ואח\"כ ברוך אומר ועושה בחו\"ב<sup data-n=\"111\">109</sup> ביו\"ד מאמרות כידוע). והנה אנו אומרים תתברך ה' [אלקינו] על כל [שבח] מעשה ידיך<sup data-n=\"112\">110</sup> כו' הרי כל הנבראים כולם נק' רק בשם עשי' לבד [וכ]פועל מעשה ידי אדם כמ\"ש כולם בחכ' עשית כו' וכתיב אתה עשית את השמים<sup data-n=\"113\">111</sup> כו' וכתיב אף ידי יסדה ארץ<sup data-n=\"114\">112</sup> וימיני טפחה שמים כו' וכה\"ג, ועד\"מ כח המעשה שבאדם שהוא כח היותר חיצוני שבנפש הרבה יותר חיצוני מכח הדבור וכח המח' שהרי אינו אלא כמו כח התנועה שבידים, וכך כל מע\"ב נק' מעשה אע\"פ שהן אלפים רבבות עולמות הרוחני' בג\"ע העליון והתחתון וכמלאכים דבי\"ע עכ\"ז הן כולם רק בבחי' עשי' שבאלקו' שהיא המדרגה היותר תחתונה, וז\"ש על כל שבח מעשה ידיך לבד כו' וד\"ל.\n<b>ובאמת</b> י\"ל הלא בדבר ה' שמים נעשו וברוח פיו כל צבאם בי' מאמרות שהוא בחי' הדבור שלמעלה הרבה מבחי' המעשה. אך הנה ידוע שהתהוות העולמות מאין ליש יש בזה ג' מדרגות שנזכרים בג' לשונות בי\"ע, שהרי אמר בראשית ברא אלקי'<sup data-n=\"115\">113</sup> ויברא ה'<sup data-n=\"116\">114</sup> כו' וגם בלשון יצירה וייצר ה'<sup data-n=\"117\">115</sup> וגם בלשון עשי' כו' וכמ\"ש ביום עשות ה'<sup data-n=\"118\">116</sup> כו'. וגם בנשמות שהן בבחי' פנימיות העולמות בכלל נאמר כל הנקרא בשמי<sup data-n=\"119\">117</sup> ולכבודי בראתיו יצרתיו אף עשיתיו שהן ג' מדריגות דבי\"ע וכנ\"ל, וכמו שאנו אומרים בראת יצרת נפחת<sup data-n=\"120\">118</sup> כו'. וגם בחיצוני' העולמות כמלאכים וחיות כו' יש ג' מדרגות אלו דבי\"ע גם בכל עולם בפרט בג' עולמות בי\"ע כידוע. והענין הוא לפי שגם העשי' כלול [מ]מח' ודבור<sup data-n=\"121\">119</sup> ונק' מח' ודבור שבעשי', וכן הדבור כלול מעשי' ונק' עשי' שבדבור וכן מח' שבדבור, וגם המח' כלול מדבור ומעשה שבמח' כו' וכמ\"ש במ\"א. ולזאת הכל אמת דברא ויצר ועשה כו', רק שבדרך כלל נחלק לג' עולמות בי\"ע שהן עולמות שנבראו מבחי' אותיות המח' שבאלקו' נק' עולם הבריאה ונק' עלמין סתימין דלא אתגליין, ועולם היצי' הוא עלמין דאתגליין<sup data-n=\"122\">120</sup> מבחי' אותיות הדבור ועולם העשי' נמשך מבחי' כח המעשה לבד כמו אתה עשית<sup data-n=\"123\">121</sup> כו', אבל גם בעולם העשי' יש מבחי' הדבור די\"מ והמח' שבהם ונק' דבור ומח' שבעשי', וכך הוא בכל עולם בפרט. וכמו\"כ הוא בנשמות דכתי' בראתי[ו] כו', והנה בד\"כ הנשמות הן בבחי' בריאה כמו בורא קדושים כו' והמלאכים הם בבחי' יצי' כמו יוצר משרתים<sup data-n=\"124\">122</sup> [כו'] גם בכל עולם בפרט. כי",[["110","108","<b>לח\"ע</b>: גד: לחכ'."],["111","109","<b>ברוך אומר ועושה בחו\"ב</b>: ראה גם לעיל קכ, ב."],["112","110","<b>תתברך. . מעשה ידיך</b>: ברכת יוצר [בדילוג]."],["113","111","<b>אתה עשית את השמים</b>: נחמי' ט, ו."],["114","112","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["115","113","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["116","114","<b>ויברא ה'</b>: בראשית א, כא. כז."],["117","115","<b>וייצר ה'</b>: בראשית ב, ז. יט."],["118","116","<b>ביום עשות ה'</b>: בראשית ב, ד."],["119","117","<b>כל הנק' בשמי</b>: ישעי' מג, ז."],["120","118","<b>בראת יצרת נפחת</b>: ברכת אלקי נשמה [בדילוג]."],["121","119","<b>העשי'. . ודבור</b>: ראה לעיל פ' שמות ל, א."],["122","120","<b>עלמין סתימין דלא אתגליין. . עלמין דאתגליין</b>: ת\"ז בהקדמה (יז, א)."],["123","121","<b>אתה עשית</b>: גד: עת לעשות — תהלים קיט, קכו."],["124","122","<b>בורא קדושים. . יוצר משרתים</b>: ברכת יוצר."]]],[2300550264,"הנשמות נמשכים מבחי' שם הוי'<sup data-n=\"125\">123</sup> כמ\"ש נר הוי' נשמת אדם<sup data-n=\"126\">124</sup> והמלאכים נמשכי' מבחי' אלקי'<sup data-n=\"127\">125</sup> ונק' בני האלקי'<sup data-n=\"128\">126</sup> כידוע, וע\"כ הנשמות הן חלק אלקות ממש<sup data-n=\"129\">127</sup> ונק' קדושים כמו לקדושים אשר בארץ<sup data-n=\"130\">128</sup> כו' כמו קדוש ה'<sup data-n=\"131\">129</sup> כו' (וע\"כ עתידים המלאכים לומר לפני נשמות הצדיקים קדוש<sup data-n=\"132\">130</sup> כו'), לפי שהבריאה היא יש מאין האלקי ממש כמשל המח' הנמשכת מחכמה שמאין ממש, משא\"כ המלאכים שמבחי' דבור שהוא יש מיש כו'. ובחי' המעשה הוא בעולם עשי' במדרגות התחתונ[ות] דכלים דמל' דעשי'. ועכ\"ז בראתיו יצרתיו שהנשמה כלולה מהכל ממח' ודבור שהרי נק' רוח ממללא<sup data-n=\"133\">131</sup>, ואף עשיתיו בבחי' <span data-k=\"pg\">שסט</span> ּ עשי' בכלי הגוף בציור אדם גשמי כאדה\"ר שהי' יציר כפיו כו', כתיב בי' וייצר ויברא כו', ואף זה הפסיק הענין<sup data-n=\"134\">132</sup> לפי שהוא מדרגה התחתונה ביותר כמו כח המעשה באדם שרחוק ערכה לגבי המח' והדיבור כנ\"ל (ובמ\"א מבואר דאף זה לרבותא יתירה<sup data-n=\"135\">133</sup> קאמר משום דבמעשה יש שרש עליון יותר גם מן המח' והחכ' משום דנעוץ תחלתן בסופן כו').\n<b>וזה</b> שאנו אומרים תתברך על כל שבח מעשה ידיך שהן המלאכים, שהן בבחי' מלאכים דעשי' עד התהוות הגלגלים ודצח\"מ דעוה\"ז השפל גם שם תתברך לפי שאומרים שירה כו', ואח\"כ עליי' המלאכים דיצי' ובריאה (כידוע בג' מדרגות דג' פעמים הבו שהן ג' עולמות דבי\"ע<sup data-n=\"136\">134</sup> ), ועליהם אין אומרים תתברך על כל שבח מעשה ידיך אלא אומרים ישתבח שמך לעד מלכינו כו', והיינו לפי שמקבלים מבחי' שמך דוקא וכמו משובח ומפואר בלשון חסידיו ועבדיו שהן נשמות שנק' חסידים ומלאכים<sup data-n=\"137\">135</sup> שנק' עבדים כידוע, והן ב' מדרגות דבריאה ויצי' בכללות שהנשמות שנק' קדושים והמלאכים נק' משרתים כמו יוצר משרתים ובורא קדושים כנ\"ל וד\"ל. והנה ידוע בענין משל השם שבאדם<sup data-n=\"138\">136</sup> הגם שאינו מעצמות האדם כלל רק שנק' בשמו למי שק[ו]ראו, ומ\"מ יש בבחי' שם זה מבחי' של עצמותה מאחר שנפנה כל עצמו ע\"י קריאת שם זה (כמו ויקרא האדם שמות<sup data-n=\"139\">137</sup> כו' שהשם מורה על העצם דוקא כמ\"ש במ\"א). משא\"כ מעשה ידי אדם אין במעשה פעולתו רק הארה כח חיצוניות מחיצוניות שבנפשו שאין לו חיבור כלל עם עצמותו כשידיו מסולקות מפעולתו ומעשיהו באיזה בנין או כלי וכידוע, לבד מה שכח הפועל בנפעל כבר נבדל מן העצמות והשם הוא כלול בעצמותו",[["125","123","<b>הנשמות. . שם הוי'</b>: ראה אגה\"ת פ\"ד."],["126","124","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["127","125","<b>והמלאכים. . אלקי'</b>: ראה אגה\"ת שם. מאמרי אדה\"א קונטרסים ע' שה. וש\"נ."],["128","126","<b>בני האלקי'</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' עז וע' קלח. הנסמן בהערה שלפנ\"ז."],["129","127","<b>הנשמות הן חלק אלקות </b>[ד: אלוקה ממעל]<b> ממש</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא</a> רפ\"ב. לעיל פ' וארא נא, ד. וש\"נ."],["130","128","<b>לקדושים אשר בארץ</b>: תהלים טז, ג."],["131","129","<b>קדוש ה'</b>: ישעי' ו, ג."],["132","130","<b>עתידים המלאכים לומר. . קדוש</b>: ראה ב\"ב עה, ב."],["133","131","<b>רוח ממללא</b>: ת\"א לבראשית ב, ז."],["134","132","<b>ואף זה הפסיק הענין</b>: נסמן לעיל פ' בשלח קמד, ג."],["135","133","<b>דאף זה לרבותא יתירה</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרא (נוסח שני'). ע' תרז (נוסח א'). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380589\" data-slug=\"likkutei-torah\" data-id=\"4001380589\">לקו\"ת בלק סז, ד</a>. מאמרי אדה\"א במדבר ח\"ד ע' א'תקח. לקמן פ' תרומה שיד, ב תצוה שעג, ג."],["136","134","<b>דג' פעמים הבו. . דבי\"ע</b>: ראה פע\"ח (שער השבת) שי\"ח, פ\"ב. פ\"ו. פ\"ח. מאמרי אדה\"א בראשית ע' מו. וש\"נ."],["137","135","<b>משובח ומפואר. . נשמות. . ומלאכים</b>: ברכת ברוך שאמר. ראה פע\"ח (שער הזמירות) ש\"ז, פ\"ד. לעיל פ' וארא סא, ב. וש\"נ."],["138","136","<b>השם שבאדם</b>: ראה מאמרי אדה\"א קונטרסים ס\"ע תקס ואילך. וש\"נ."],["139","137","<b>ויקרא האדם שמות</b>: בראשית ב, כ. ראה מאמרי אדה\"א דברים ח\"ד ע' א'רסח ואילך."]]],[2300550294,"ממש כידוע. וכן יובן למעלה בענין מה שאומר ישתבח שמך כו' שהן ע\"י המלאכים ונשמות דבריאה ויצי' ששרשם באותיות ושמות דהוי' ואלקים במח' ודבור כו' כנ\"ל, ואחוזים וקשורים באותיות שמו יתברך וכמ\"ש לכו חזו מפעלות אלקים<sup data-n=\"140\">138</sup> אשר שם שמות בארץ א\"ת ש’מות אלא ש מות<sup data-n=\"141\">139</sup> כו' וע\"כ ודאי המה קרובים יותר לאור האלקי בבחי' עצמותו יותר הרבה ממלאכים ועולמות התחתונים שנק' מעשה ידיך לבד (ואע\"פ שבנשמות אמר ג\"כ אף עשיתיו זהו לרבותא מפני שכולל האדם לכל העולמות, וגם מלאכים התחתונים דעשי' מקבלים על ידו מצד בחי' המעשה שבו בתומ\"צ כו').\n<b>והנה</b> כ\"ז הוא רק בבחי' ממכ\"ע דשם אלקים שנק' שמך, הגם שכלול מג' מדרגו' דבי\"ע מח' ודבור ומעשה כנ\"ל הכל הוא רק מבחי' זיו ואור הארה בעלמא מבחי' מל' דאצי' כמ\"ש מלכותך מכ\"ע כו' כידוע. אבל בחי' סוכ\"ע הוא בשם הוי' שלמעלה מעלה מכל ההשתל' דג' עולמות דבי\"ע כידוע, וכמ\"ש כי עמך מקור חיים<sup data-n=\"142\">140</sup> כו' שע\"י צמצום דשם אלקי' מסתיר על שם הוי' הוא שנעשה מקור כל העולמות, וזהו כי שמש ומגן הוי' אלקי'<sup data-n=\"143\">141</sup> כידוע. וזהו שאמר אני הוי' לא שניתי<sup data-n=\"144\">142</sup> פי' בלתי שינויים בהוי' דבחי' סוכ\"ע בין קודם ההשתל' דבעולמות דבי\"ע<sup data-n=\"145\">143</sup> <span data-k=\"pg\">740</span> ּ לאחר השתלשלו', וכמו שאומר אתה הוא<sup data-n=\"146\">144</sup> כו' מאחר שאין כל ההשתל' העולמות רק בבחי' הארה דהארה לגבי עצמות האור דשם הוי' דע\"ס דאצי' כו' וד\"ל. וזהו שאמר אני הוי' לא שניתי ואתם בני יעקב לא כליתם, פי' כמו שאני הוי' לא שניתי כך אתם בני יעקב ששרשם משם הוי' ממש כמ\"ש כי חלק הוי' עמו<sup data-n=\"147\">146</sup> ממש כו' ג\"כ לא כליתם<sup data-n=\"148\">145</sup>, מפני שאין קץ וכליון שייך רק בבחי' הגבול והתכלית שנמשך בבחי' השתלשלו' העולמות מאין ליש בע\"ג בג' מדרגות הנ\"ל [ש]הוא נמשך מבחי' המעשה והדבור העליון כו', אבל שרש הראשון דנש\"י הוא בשם הוי' דעצמות א\"ס שבאצי' כמו כי אתה אבינו<sup data-n=\"149\">147</sup> ע\"כ כמו שהוא ית' לא יתכן בו קץ וסוף כמו שאמר אין קצבה לשנותיך<sup data-n=\"150\">148</sup> ואין קץ כו' כך בנ\"י אין להם כליון כי הם נצחי' בבחי' נצחיות דא\"ס ממש וכמ\"ש לא מאסתים כו' לכלותם<sup data-n=\"151\">149</sup> כו' וד\"ל. אך זהו מצד השרש של הנשמות דוקא מטעם הנ\"ל שהן בבחי' פנימי' דשם הוי' דאצי' כו', אבל מצד ירידת הנשמה בגוף החומרי יתפרש להיפך ואתם בנ\"י לא כליתם כו' כמו מתמי' עליהם מדוע לא כליתם<sup data-n=\"152\">150</sup> מפני מה אין לכם מס\"נ בכלות הנפש ממש, מאחר",[["140","138","<b>לכו חזו מפעלות אלקים</b>: ראה תהלים מו, ט ובמנחת שי שם. מאמרי אדה\"א נ\"ך ע' תעב. וש\"נ. לעיל פ' וארא ס, ד. וש\"נ."],["141","139","<b>א\"ת שמות אלא שמות</b>: ברכות ז, ב. ראה גם לעיל פ' וארא עה, ג."],["142","140","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["143","141","<b>כי שמש ומגן הוי' אלקי'</b>: תהלים פד, יב. ראה שער היחוה\"א רפ\"ו. לעיל פ' שמות לד, ד. וש\"נ."],["144","142","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["145","143","<b>דבעולמות דבי\"ע</b>: גד: דבי\"ע בין."],["146","144","<b>אתה הוא</b>: נוסח תפלת השחר."],["147","146","<b>כי חלק הוי' עמו</b>: האזינו לב, ט."],["148","145","<b>כך אתם. . לא כליתם</b>: ראה גם שה\"א א, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670045\" data-slug=\"torat-chaim\" data-id=\"2300670045\">תו\"ח נח נט, א</a> ובהערה 12."],["149","147","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["150","148","<b>אין קצבה לשנותיך</b>: תפלת מוסף לימים נוראים קודם קדושת כתר."],["151","149","<b>לא מאסתים. . לכלותם</b>: בחוקותי כו, מד."],["152","150","<b>מדוע לא כליתם</b>: ראה גם בהדרושים שבהערה 1. לעיל פ' שמות ז, ג. וש\"נ."]]],[2300550321,"ששרשם בשם הוי' ואני הוי' לא שניתי להיות למעלה מכל ההשתל' דממלא כו' באין שינוי כלל וד\"ל. וא\"כ הרי שוין לפניו היותר עליון שבהשתלשלו' בג\"ע העליון עם היותר תחתון שמתחת לארץ וחשך<sup data-n=\"153\">151</sup> דק\"נ כמ\"ש אם אסק<sup data-n=\"154\">152</sup> כו' בשמים ממעל ועל הארץ<sup data-n=\"155\">153</sup> כו' וכמשל העיגול<sup data-n=\"156\">154</sup> שאין בו מעלה ומטה כידוע, וע\"כ אמר כחשיכה כאורה<sup data-n=\"157\">155</sup> ממש בשוה, וא\"כ למה יהי' מניעה למס\"נ מצד חומר הגוף המחשיך על הנשמה מאחר ששרש הנשמה אלקי' משם הוי' שלא שניתי כלל גם חושך לא יחשיך<sup data-n=\"158\">156</sup> כלל כו', ולא יוכל הגסות דגוף למנוע כלל לפי שגם הוא יכול להיות שיבא<sup data-n=\"159\">157</sup> לכלל מס\"נ כמו הנשמה מטעם זה, וכמו שאין שינוי כלל בעצם שם הוי' כך צריך שלא יהי' שינוי בנר הוי' נשמת אדם, וז\"ש כמתמי' ואתם בנ\"י לא כליתם במס\"נ בגוף בפו\"מ כמו נכספה וגם כלתה נפשי<sup data-n=\"160\">158</sup> שהוא לשם הוי' דוקא כמ\"ש אליך ה' נפשי אשא<sup data-n=\"161\">159</sup> כו' וד\"ל.\n<b>והנה</b> לזה אמר ה' עוז לעמו יתן כו' שהוא עוז דתורה דוקא שנק' עוז ותושי' כנ\"ל שמחזקת ומוספת כח לנשמה האלקי' לבלי יסתיר לה חומר הגופני מפני שמתשת כח הגוף, ובאים כאחד עוז לנשמה ותושי' לגוף דהא בהא תליא שתוקף הנשמה הוא העושה חולשא דגוף כו' כידוע. ולהיפך תוקפא דגופא הוא חולשא דנשמתא וכמ\"ש כשל בעוני כחי<sup data-n=\"162\">160</sup> שבעוונות נפגם צלם האלקי' ונחלש כח הנשמה שהוא צל דצלם, שהוא הכח ומקור שלה שהוא בבחי' מקיף שמשם נמשך הרהורי תשובה ויראה ואהבה כו', וכמ\"ש עוונותי עברו ראשי<sup data-n=\"163\">161</sup> כו'. ואף לא בעון וחטא גמור אלא עוונות שאדם דש בעקביים<sup data-n=\"164\">162</sup> ואינו מרגיש כמ\"ש עון עקבי יסובני<sup data-n=\"165\">163</sup> בבחי' מקיף להחליש בחי' כח הנשמה, וז\"ש כשל בעווני כחי וכמ\"ש בזהר דתוקפא דגופא חולשא דנפשא, והוא התוקף דגוף [ב]גסות וחומריות עוה\"ז שמחליש <span data-k=\"pg\">שע</span> ּ ומחשיך אור וכח דנשמה עד שאין בכח הנשמה להתעורר בתשובה אמיתית או באהוי\"ר האמיתי' במס\"נ לצאת מהתקשרות רצונות הזרות שבעוה\"ז, ולכך אמר ואתם בנ\"י לא כליתם במס\"נ מחמת חלישות כח הנשמה מצד תוקפא דגופא כנ\"ל (ולפי' הא' לא כליתם בכליון והפסד דגוף החומרי לפי שאני הוי' לא שניתי שהוא נותן תוקפא דנשמתא בגוף<sup data-n=\"166\">164</sup> ). ואמנם לזאת ניתנה התורה כדי לחזק הכח של הנשמה כי כל אות מאותיות התורה הוא שרש ומקור חיי הנשמות כמ\"ש כי אמרתך חייתני, ואף לחיות כל העולמות כמ\"ש ואשים דברי בפיך<sup data-n=\"167\">165</sup>",[["153","151","<b>וחשך</b>: ג: בשוה בחשך. ד: חסר."],["154","152","<b>אם אסק</b>: תהלים קלט, ח."],["155","153","<b>בשמים ממעל ועל הארץ</b>: ואתחנן ד, לט."],["156","154","<b>וכמשל העיגול</b>: ראה גם לעיל פ' שמות לח, ד. וש\"נ."],["157","155","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["158","156","<b>גם חושך לא יחשיך</b>: תהלים שם."],["159","157","<b>להיות שיבא</b>: גד: לבא."],["160","158","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["161","159","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["162","160","<b>כשל בעוני כחי</b>: תהלים לא, יא. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'קעא. וש\"נ. שמות ח\"ב ע' תקלו. נ\"ך ע' רסח. הנחות תקע\"ז ע' שלג."],["163","161","<b>עוונותי עברו ראשי</b>: תהלים לח, ה."],["164","162","<b>עוונות שאדם דש בעקביים </b>[גד: בעקביו]: ע\"ז יח, א. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תתצג."],["165","163","<b>עון עקבי יסובני</b>: תהלים מט, ו."],["166","164","<b>בגוף</b>: גד: כנ\"ל."],["167","165","<b>ואשים דברי בפיך</b>: ישעי' נא, טז [בדילוג]."]]],[2300550346,"לנטוע שמים כו' (לפי שג' קשרים הן<sup data-n=\"168\">166</sup> ישראל מתקשראן באורייתא כו'), וממילא מתשת כח הסט\"א דאת זה לעו\"ז כשזה קם זה נופל כו' דתוקפא דנפשא חולשא דגופא כו' וד\"ל. וזהו הוי' עוז לעמו יתן שהוא עוז דתורה ה' יברך את עמו בשלום דמבחי' עוז דתורה נמשך בחי' השלום בכנס\"י שהוא בחי' יחו\"ע דמשפיע במקבל כמ\"ש אדברה נא שלום בך<sup data-n=\"169\">167</sup> וכתי' או יחזיק במעוזי<sup data-n=\"170\">168</sup> יעשה שלום לי כו' שלום בפמשמ\"ע ושלום בפמשמ\"ט, וכמו ורב שלום בניך<sup data-n=\"171\">169</sup> ביחו\"ע דאצי' שמשם נמשך<sup data-n=\"172\">170</sup> שרש חיי הנשמות שהוא עוז לנשמה ובחי' יחו\"ת דפמשמ\"ט להפריד ולהתיש כח הסט\"א שהוא להחליש כח נה\"ב כו', והכל ע\"י התורה שנק' עוז ותושי' כנ\"ל. וכך הי' במ\"ת שנמשך עוז לנשמה והוחלש כח הסט\"א שפסקה מהן<sup data-n=\"173\">171</sup> כו' וכמ\"ש וירד הוי' על ה\"ס<sup data-n=\"174\">172</sup> שירדה שנאה לאוה\"ע<sup data-n=\"175\">173</sup> והי' חירות ממות<sup data-n=\"176\">174</sup> כעין עוה\"ב משום דעוז דתורה לעמו יתן כו' וד\"ל.\n<b>אך</b> הנה לכאורה י\"ל כיצד תהי' התורה עוז ותושי' עוז לנשמה לעשות שלום בפמשמ\"ע ביחו\"ע דאצי' שתקשר ותדבק באלק[ו]' במס\"נ ממש כנ\"ל ה[ל]א התו\"מ מלובשים בעניני' גשמיי' דדצ\"ח כו', כמו מצות ציצית מצמר ותפילין בקלף גשמי ומצות תרומות ומעשרות בתבואות. וכך בכל המצות שמתלבשי' בדברים גשמיי' ואיך תהי' התורה עוז וכח לנשמה ע\"י לימוד ההלכות שאינו אלא באו\"ה בטומאה וטהרה בדברים גשמיים<sup data-n=\"177\">175</sup> שהוא רק לברר לעה\"ד טו\"ר לבד כידוע, ואיך יכול להיות שמתשת כח הסט\"א בהבדלת הרע מן הטוב במה שאומר זה כשר וזה פסול בדבור בפה לבד, וגם אם מקיים במעשה בסו\"מ ועשה טוב אין זה עוז וכח לנשמה והתשת כח הרע בעצם. אך הנה יש להקדים<sup data-n=\"178\">176</sup> תחלה כללות ענין קבלת התורה, דהנה בהתחלת הדברות אמר וידבר אלקי' את כל הדברים האלה לאמר<sup data-n=\"179\">177</sup>, וי\"ל תיבת לאמר מהו דא\"א לפרש כמו כל לאמר שבכל פ' שהוא לומר לזולתו לישראל כמו ויאמר ה' אל משה לאמר<sup data-n=\"180\">178</sup> לכנס\"י כו', שהרי כאן שמעו כל ישראל בעצמם כידוע דדבור דאנכי מפי הגבורה שמענו<sup data-n=\"181\">179</sup> עצמו ולא ע\"י זולתו<sup data-n=\"182\">180</sup> ולא ע\"י משה כמ\"ש פב\"פ דיבר ה' עמכם<sup data-n=\"183\">181</sup> כו', אלא פי' לאמור היינו ענין ציווי לכל ישראל",[["168","166","<b>שג' קשרים הן</b>: ראה זהר אחרי עג, א. לעיל ב, ד. וש\"נ."],["169","167","<b>אדברה נא שלום בך</b>: תהלים קכב, ח."],["170","168","<b>או יחזיק במעוזי</b>: ישעי' כז, ה. סנהדרין צט, ב. ראה לקמן רצ, ד."],["171","169","<b>ורב שלום בניך</b>: ישעי' נד, יג."],["172","170","<b>נמשך</b>: גד: ליתא."],["173","171","<b>הסט\"א שפסקה מהן</b>: ראה שבת קמו, א."],["174","172","<b>וירד הוי' על ה\"ס</b>: יתרו יט, כ."],["175","173","<b>שירדה שנאה לאוה\"ע</b>: שבת פט, סע\"א."],["176","174","<b>חירות ממות</b>: ראה שמו\"ר רפל\"ב. פמ\"א, ז. זהר בראשית לז, ב."],["177","175","<b>בדברים גשמיים</b>: גד: ודיני ממונות כו'."],["178","176","<b>להקדים</b>: ג: חסר. ד: להבין."],["179","177","<b>וידבר אלקי'. . לאמר</b>: יתרו כ, א. ראה גם ד\"ה וידבר אלקים שבועות תשכ\"ט נדפס בסה\"מ מלוקט ח\"ד ע' רעא ובהנסמן שם. ש\"א ב, ב ובהערה 38."],["180","178","<b>ויאמר ה' אל משה לאמר</b>: תשא לא, יב."],["181","179","<b>דאנכי מפי הגבורה שמענו</b>: מכות כד, א. ראה מו\"נ ח\"ב פל\"ג. <a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא</a> פ\"כ. לעיל פ' וארא סט, א. וש\"נ."],["182","180","<b>שמענו. . זולתו</b>: ג: עצמה נשמעו. ד: בעצמן שמענו."],["183","181","<b>פב\"פ דיבר ה' עמכם</b>: ואתחנן ה, ד."]]],[2300550369,"בעצמם<sup data-n=\"184\">182</sup> שכל הדברים האלה יאמרו תמיד לדורות בכל עת קביעת העתים לתורה יאמרו בדבור בפה אותן הדברים עצמן כהווייתן שכבר נאמרו, כמו והיו הדברים האלה<sup data-n=\"185\">183</sup> כו' ודברת בם<sup data-n=\"186\">184</sup> שהוא מצות ת\"ת רק להיות דבריהם<sup data-n=\"187\">185</sup> בפיהם תמיד כמ\"ש למען תהי' תורת ה' בפיך<sup data-n=\"188\">186</sup> דוקא. <span data-k=\"pg\">742</span> ּ וגם מה שנאמרו כבר למשה בסיני בע\"פ יאמרו בדבור כמו הלכות שבמשנה וגמרא שנק' תושבע\"פ שהוא ג\"כ דבר ה' ממש, כי גם כל מה שתלמיד ותיק עתיד לחדש<sup data-n=\"189\">187</sup> הכל ניתן למשה בסיני. ומה שמזכירין שמות התנאים ואמוראים במשנה וגמ' כמו ב\"ש וב\"ה או ר' פלוני אומר, היינו דבר ה' ממש שניתן למשה בסיני<sup data-n=\"190\">188</sup> שיצא בפי ר\"פ את אשר כבר נאמר למשה בסיני (כידוע בענין מ\"ש משה שפיר קאמרת<sup data-n=\"191\">189</sup> כלומר כאלו מפי משה נאמר דבר זה כו'), וזהו ודברי אשר שמתי בפיך<sup data-n=\"192\">190</sup> דברי ממש. וכללותן הן יו\"ד הדברות שזהו עיקר ענין קבלת התורה בפ' זו דיו\"ד הדברות, דהיינו שנתקבלו בכנס\"י לדורות שיאמרו אותם תמיד והוא במ\"ש וידבר את כל הדברים האלה לאמר שיהיו נאמרים תמיד וכמו תען לשוני אמרתיך<sup data-n=\"193\">191</sup> ממש כו'. וזהו שרש ענין קבלת התורה לעתיד והוא כאשר נאמר ביו\"ד הדברות שהוא מ\"ש הדברים האלה לאמר שיאמרו בנ\"י כל האמור למשה כנ\"ל, כי כל<sup data-n=\"194\">192</sup> יו\"ד הדברות כללות כל התורה<sup data-n=\"195\">193</sup> הוא ודבריו חיים וקיימים לעד<sup data-n=\"196\">194</sup> כו', הרי בתיבת לאמר זה הוקבע עי\"ז<sup data-n=\"197\">195</sup> ציווי זה בכל פרטי דברי התורה שיקבלו בכנס\"י שתאמר בפיהם בדבור והוא שיהי' דבר ה' ממש בפיהם בשעה שלומדי' ההלכות כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן מארז\"ל ע\"פ והודעתם לבניך כו' וסמוך ל[י]' יום אשר עמדת<sup data-n=\"198\">196</sup> לפני ה' כו' מה להלן באימה ויראה<sup data-n=\"199\">197</sup> ורתת וזיעה אף כאן באימה ויראה כו', וזהו פלא גדול לכאורה איך יכול להיות עכשיו בזמן הסתר אלקות אימה ויראה ופחד אלקי שהי' בזמן מ\"ת שהיו רואים את הקולות<sup data-n=\"200\">198</sup> ועמדו על הר סיני<sup data-n=\"201\">199</sup> פב\"פ כו' עד שעל כל דבור ודבור פרחה נשמתן<sup data-n=\"202\">200</sup> כו', והיו מופשטים מגשמיות חומר גופם לגמרי כו', ואיך יוכל אדם ללמוד עכשיו דבר ה' זו הלכה<sup data-n=\"203\">201</sup> באימה ויראה שהי' בזמן מ\"ת עד שא' מה להלן כו'. אך הענין הוא משום דגם עכשיו בכל עת",[["184","182","<b>בעצמם</b>: גד: ליתא."],["185","183","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה גם לקמן פ' פקודי תמח, ב. וש\"נ."],["186","184","<b>ודברת בם</b>: שם, ו, ז."],["187","185","<b>דבריהם</b>: גד: דבר ה'."],["188","186","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."],["189","187","<b>כל מה שתלמיד ותיק עתיד לחדש</b>: ראה מגילה יט, ב. ירושלמי פאה פ\"ב, ה\"ד. הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191265\" data-slug=\"likkutei-sichot\" data-id=\"1300191265\">לקו\"ש</a> דברים (כרך ד) ע' 1088. ח\"י אלול (כרך יט) ע' 252."],["190","188","<b>שמות התנאים ואמוראים. . דבר ה' ממש שניתן למשה בסיני</b>: ראה גם פסיקתא פרשת פרה. תנחומא חוקת ח. במד\"ר פי\"ט, ז. כתר שם טוב סש\"כ (מהדורת קה\"ת). לקוטי לו\"י אגרות ע' רסו."],["191","189","<b>משה שפיר קאמרת</b>: ראה גם לעיל פ' שמות י, ב. וש\"נ."],["192","190","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["193","191","<b>תען לשוני אמרתיך</b>: תהלים קיט, קעב."],["194","192","<b>כל</b>: גד: ליתא."],["195","193","<b>יו\"ד הדברות כללות כל התורה</b>: ראה גם מאמרי אדה\"ז תקס\"ז כאן (ע' קמט). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א כאן (סז, ב</a>). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370050\" data-slug=\"torah-or\" data-id=\"3901370050\">לעיל יא, ג</a>. וש\"נ."],["196","194","<b>ודבריו חיים וקיימים לעד</b>: ברכת אמת ויציב."],["197","195","<b>עי\"ז</b>: גד: ע\"י."],["198","196","<b>והודעתם לבניך. . יום אשר עמדת</b>: ואתחנן ד, ט. י."],["199","197","<b>מה להלן באימה ויראה</b>: ראה ברכות כב, א."],["200","198","<b>שהיו רואים את הקולות</b>: יתרו כ, טו."],["201","199","<b>על הר סיני</b>: גד: בהר סיני."],["202","200","<b>שעל כל דבור ודבור פרחה נשמתן</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. נ\"ך ע' שפא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670525\" data-slug=\"torat-chaim\" data-id=\"2300670525\">תו\"ח בראשית יז, ב</a>."],["203","201","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."]]],[2300550388,"וזמן לימוד האדם דבר ה' זו הלכה גם ביחיד הרי דבר ה' הוא שמדבר בפיו וכמ\"ש ודברי אשר שמתי בפיך בזמן מ\"ת שנק' קבלת התורה כנ\"ל בפי' לאמר, ודבריו חיים וקיימים בלי שינוי כלל וכלל (שאין גשמיות<sup data-n=\"204\">202</sup> וחומריות מחשיך לגבי אור האלקי דדבר ה' כמו במ\"ת שא' בהגלותך מלכינו כו' גם בריות בראשית חרדו ממך<sup data-n=\"205\">203</sup> כו'). וא\"כ בדבר [ה'] זה יוכל לבא לבחי' האימה ויראה שהי' במ\"ת ממש שהרי הוא כאלו שומע עכשיו אותו דבר ה' ששמעו במ\"ת כמ\"ש אני הוי' לא שניתי והוא דבר הוי' שאין בו שינוי, ואם השינוי הוא מצד המקבלים אין זה שינוי כלל בעצם דבר ה' שמדבר בפיו (וראי' לזה ממה שבעל קרי ג\"כ מותר בדברי תורה שאין ד\"ת מקבלים טומאה<sup data-n=\"206\">204</sup> ו[מ]מה שת\"ח אין הגיהנם שולטת בהם<sup data-n=\"207\">205</sup> כו') (והעיקר הוא משום דגם נשמות דעכשיו היו בזמן מ\"ת<sup data-n=\"208\">206</sup> וכמ\"ש ואשר איננו פה<sup data-n=\"209\">207</sup> כו', ומצד שרש כל הנשמו' באותיות התורה דג' קשרים הן<sup data-n=\"210\">208</sup> כו' וכידוע). וזהו מה להלן באימה כי דבר ה' שבפי היחיד עכשיו הוא אותו דבר ה' שבמ\"ת (אמנם אין זה בא בגילוי כמו במ\"ת רק במי שתורתו אומנתו<sup data-n=\"211\">209</sup> כרבא דא'<sup data-n=\"212\">210</sup> דיתיב באימתא<sup data-n=\"213\">211</sup> ופתח בשמעתתא<sup data-n=\"214\">212</sup> וכר\"י דאימתא דמרי' עליו<sup data-n=\"215\">213</sup> כו'). ועכ\"ז יובן יותר ענין עוז ותושי' דתורה מטעם הנ\"ל דאור <span data-k=\"pg\">שעא</span> ּ דבר הוי' אין בו שינוי כלל מכמו שהי' במ\"ת ע\"כ יש ביכולת האור דתורה ליתן כח ועוז לנשמה העוסקת בתורה בדבור גם עכשיו להאירה באור ה' בחיזוק גדול ולהתיש כח הגוף כמו במ\"ת ממש. וז\"ש ה' עוז לעמו יתן לשון להבא שתמיד יתן עוז הגם שכבר ניתנה התורה, אך מצד דברי אשר שמעת<sup data-n=\"216\">214</sup> בקבלת התורה תמיד יתן כח ועוז לנשמות העוסקים בתורה כנ\"ל (וע\"כ מברכים נותן התורה לשון הוה<sup data-n=\"217\">215</sup> כידוע) וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל באור דתורה שנק' עוז ותושי' להתיש ממילא לכח הסט\"א כו', כך יש ג\"כ במצות ק\"ש בפסוק א'<sup data-n=\"218\">216</sup> שמע ישראל<sup data-n=\"219\">217</sup> כו' שהוא מס\"נ דנשמה האלקי' בהוי' אחד ממש שהוא בבחי' יחו\"ע דע\"ס דאצי' במאציל עצמו כידוע ומבואר למעלה",[["204","202","<b>גשמיות</b>: גד: חושך וגסות."],["205","203","<b>בהגלותך מלכינו. . חרדו ממך</b>: ועד\"ז הובא גם במאמרי אדה\"א שמות ח\"א ע' קעד. במדבר ח\"ב ע' שלט. ע' תסב. ע' תשעה — ע\"פ נוסח ברכת שופרות (מוסף לר\"ה)."],["206","204","<b>שאין ד\"ת מקבלים טומאה</b>: ברכות כב, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081363\" data-slug=\"likkutei-sichot\" data-id=\"1300081363\">לקו\"ש</a> בין המצרים (כרך ח) ע' 352 הערות 5-6. ד\"ה ציון במשפט תפדה תשל\"ה נדפס בסה\"מ מלוקט ח\"א ע' קנה הערות 46-48."],["207","205","<b>שת\"ח אין הגיהנם שולטת בהם</b>: ראה חגיגה כז, א. לקמן רסב, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשצד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081258\" data-slug=\"likkutei-sichot\" data-id=\"1300081258\">לקו\"ש שבועות (כרך ח) ע' 247</a> בהערה [נדפס גם באג\"ק שלו חכ\"ב ע' תנא]. ויקהל (כרך טז) ע' (434) 436 ואילך."],["208","206","<b>נשמות דעכשיו היו בזמן מ\"ת</b>: ראה פדר\"א פמ\"א. תנחומא יתרו יא. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שלח."],["209","207","<b>ואשר איננו פה</b>: נצבים כט, יד [ושם: ואת אשר — וכ\"ה בגד. ראה מאמרי אדה\"א דברים ח\"ג ר\"ע תשנו. מאמרי אדה\"א נ\"ך ע' רצד. וש\"נ]."],["210","208","<b>הן</b>: גד: הנ\"ל."],["211","209","<b>שתורתו אומנתו</b>: שם: שהוא."],["212","210","<b>כרבא דא'</b>: ג: כרבא. ד: כרבה."],["213","211","<b>כרבא. . דיתיב באימתא</b>: ראה שבת ל, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא</a> פ\"ז. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתלז. ע' תתנה (נוסח א). ע' תתסב (נוסח א). תו\"ח ח\"ש קכח, א. תולדות קמג, ד. מאמרי אדה\"א קונטרסים ע' שפא. וש\"נ. ש\"א מא, א ובהערה 24."],["214","212","<b>כרבה. . דיתיב באימתא ופתח בשמעתתא</b>: שבת ל, ב. מאמרי אדה\"א קונטרסים שם. שע\"ת ו, ד. כג, ג ובהערה 35."],["215","213","<b>וכר\"י דאימתא דמרי' עליו</b>: נדה יג, סע\"א."],["216","214","<b>שמעת</b>: גד: שמתי."],["217","215","<b>נותן התורה לשון הווה</b>: ראה של\"ה כה, א. מאמרי אדה\"א הנחות תקע\"ז ע' שז. וש\"נ. לעיל פ' שמות לב, ד. וש\"נ."],["218","216","<b>א'</b>: ג: ראשון. ד: ליתא."],["219","217","<b>שמע ישראל</b>: ואתחנן ו, ד."]]],[2300550405,"דבחי' שם הוי' דאצי' אין בו שינוי כלל כמ\"ש אני הוי' לא שניתי כו', ע\"כ האהבה הזאת בפסוק ואהבת את הוי'<sup data-n=\"220\">218</sup> כו' הרי הוא בבחי' ביטול במציאות ממש בשם הוי' דאצי' שהוא בחי' אחדות הפשוטה דבחי' סוכ\"ע דקמי' כחשיכה כו', ואז ממילא נעשה כח ועוז לנשמה האלקי' ולהתיש כח הסט\"א שבגוף כנ\"ל בעוז ותושי' דתורה. וזהו מ\"ש בכל לבבך בשני יצריך<sup data-n=\"221\">219</sup> שגם יצה\"ר יבטל ממציאותו ויתהפך לגמרי לקדושה האלקי' מפני שמתשת כח הגוף לגמרי כמו שהי' בזמן מ\"ת [ממש], אע\"פ שפ' זאת משה אמרה לישראל כמ\"ש שמע ישראל כו', אבל היא כללות כל התו' כולה שזהו עיקר ענין קבלת התורה כנ\"ל. וזהו פי' ואהבת לשון ממילא<sup data-n=\"222\">220</sup> שממילא תאהב את הוי' בב' יצריך כו' מפני שיחו\"ע דהוי' באהבה זו הוא עוז לנשמה ולהתיש כח היצה\"ר כא' עד שלבו חלל בקרבו ממש כו' מטעם הנ\"ל וד\"ל. וזהו שאנשי יריחו היו כורכים את שמע<sup data-n=\"223\">221</sup> דהיינו שלא היו מפסיקים בבשכמל\"ו כו', כי א\"א להיות אהבה כזו בשני יצריך כ\"א בהתבוננו' דיחו\"ע דשמע ישראל<sup data-n=\"224\">222</sup> הוי' אלקינו כו' מטעם הנ\"ל, אבל בבחי' יחו\"ת דבשכמל\"ו<sup data-n=\"225\">223</sup> שהוא בחי' הכח הפועל האלקי בנבראי' שנק' בחי' ממכ\"ע כו', שמחי' את הכל כו' הרי יש מזה שרש ליניקה ג\"כ לע\"ש<sup data-n=\"226\">224</sup> דנוגה דעשי' מבחי' מ\"ח צירופי' אחרונים דשם אלקים<sup data-n=\"227\">225</sup> כידוע בענין דמלך אלקי' על גוים<sup data-n=\"228\">226</sup> כו', [ו]א\"כ א\"א להיות ביטול הרע דסט\"א לגמרי מכל וכל רק לאכפיי' לבד להיות סו\"מ בפו\"מ ע\"י קבלת עומ\"ש דבשכמל\"ו כו' ולא לאהפכא חשוכא לנהורא כנ\"ל בענין בכל לבבך הנ\"ל, משא\"כ בבחי' יחו\"ע דשם הוי' דכתי' [בי'] אני הוי' לא שניתי ומטעם הנ\"ל אין מקום ושרש שם כלל ליניקת החיצוני' כידוע, וע\"כ היו אנשי יריחו מדלגין לבשכמל\"ו. אך עכ\"ז אין הלכה כמותם שהרי אומרים אותו בחשאי<sup data-n=\"229\">227</sup>, כי הרי מתייחד יחו\"ע ביחו\"ת למהוי אחד באחד ממש ואין הצמצום ומסך מפסיק כלל לגבי אור העצמות דאור א\"ס<sup data-n=\"230\">228</sup> ב\"ה (וראי' מלע\"ל כמו בעוה\"ב שיאמרו בשכמל\"ו בקול רם<sup data-n=\"231\">229</sup>, וגם עכשיו אומרים אותו ביו\"כ בקול רם<sup data-n=\"232\">230</sup> מפני שנק' שבת שבתון<sup data-n=\"233\">231</sup> מעין",[["220","218","<b>ואהבת את הוי'</b>: ואתחנן ו, ה."],["221","219","<b>בכל לבבך בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א (במשנה). ראה הנסמן בש\"א ו, א הערה 9."],["222","220","<b>ואהבת לשון ממילא</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' שצו. לקמן פ' ויקהל תלו, ג."],["223","221","<b>שאנשי יריחו היו כורכים את שמע</b>: ראה פסחים נה, ב (במשנה). נו, א. מאמרי אדה\"ז אתהלך לאזניא ע' מג. תקס\"ד ע' רז. תקס\"ז כאן (ע' קנ). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">תו\"א כאן (סז, ג</a>). שה\"א מד, ב. מאמרי אדה\"א במדבר ח\"ג ע' א'קא. דברים ח\"ב ע' תמו. וש\"נ. הנחות תקע\"ז ע' רלח. ס\"ע רמא ואילך."],["224","222","<b>דיחו\"ע דשמע ישראל</b>: זהר בראשית יח, ב."],["225","223","<b>יחו\"ת דבשכמל\"ו</b>: פסחים נו, א. זהר שם."],["226","224","<b>לע\"ש</b>: ראה זהר בראשית מו, סע\"ב. לעיל לז, ג הערה 52."],["227","225","<b>מ\"ח צירופי'. . אלקים</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ה. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיג ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670110\" data-slug=\"torat-chaim\" data-id=\"2300670110\">תו\"ח נח סד, ד</a> ובהערה 52."],["228","226","<b>דמלך אלקי' על גוים</b>: תהלים מז, ט."],["229","227","<b>אומרים אותו בחשאי</b>: ראה גם לעיל פ' וארא עה, ד. וש\"נ."],["230","228","<b>דאור א\"ס</b>: גד: דא\"ס."],["231","229","<b>מלע\"ל. . שיאמרו בשכמל\"ו בקול רם</b>: ראה גם לעיל עה, ד."],["232","230","<b>בשכמל\"ו. . ביו\"כ בקול רם</b>: ראה שו\"ע אדה\"ז הל' יוה\"כ סתרי\"ט, ס\"ט. לעיל שם. וש\"נ."],["233","231","<b>ביו\"כ. . שנק' שבת שבתון</b>: אחרי טז, לא. אמור כג, לב. ראה גם לעיל פ' בא צד, ב. וש\"נ."]]],[2300550422,"עוה\"ב<sup data-n=\"234\">232</sup> כידוע), וכידוע דועד בחילופי אתוון דאחד<sup data-n=\"235\">233</sup> ממש, וע\"כ אין הלכה כאנשי יריחו (ואדרבה מה שמתיש כח הסט\"א הוא מהתפעלו' יחו\"ת דבשכמל\"ו שהוא בחי' הבירור דשם ב\"ן דעה\"ד טו\"ר כו', וכמ\"ש ביום ההוא יצאו מ\"ח מירושלים<sup data-n=\"236\">234</sup> כו' דנעוץ <span data-k=\"pg\">744</span> ּ תחב\"ס<sup data-n=\"237\">235</sup> דוקא וא\"כ עוז לנשמה בשמע ישראל ולהתיש כח הגוף בבשכמל\"ו דוקא, וכמו בענין עוז ותושי' דתורה הוא ההפרש בין תושב\"כ שנק' עוז לנשמה ולהתיש כח הגוף בתושבע\"פ דוקא מל' קרינן לה<sup data-n=\"238\">236</sup> כידוע).\n<b>ובכ\"ז</b> יובן מ\"ש וידבר אלקים כו' אנכי ה' אלקיך אשר הוצאתיך מאמ\"צ<sup data-n=\"239\">237</sup>, פי' אנכי מי שאנכי<sup data-n=\"240\">238</sup> בחי' סדכ\"ס<sup data-n=\"241\">239</sup> דלית מח' תפיסא בי' כלל<sup data-n=\"242\">240</sup>, והיינו בחי' גילוי אור<sup data-n=\"243\">241</sup> עצמות אור א\"ס ב\"ה ממש שע\"ז אמר אני הוי' לא שניתי כלל הוא אשר מתגלה באור דתומ\"צ להיות הוי' אלקיך ממש, והוא שיתפשט אור דשם הוי' בנשמת אדם ע\"י דבר הוי' דתורה דוקא כנ\"ל בפי' לאמור שיאיר בכאו\"א להיות אלקיך ממש, ואנכי זה הוא אשר הוצאתיך מאמ\"צ כו'. כי הנה האבות סימן לבנים וכבר ע\"י אברהם הי' כח זה בכנס\"י לצאת ממצרים והוא במ\"ש ויעל אברהם<sup data-n=\"244\">242</sup> ממצרים כו', ואמנם הי' זה מכח עצמו שהי' מרכבה מלמטה למעלה בהעלאת מ\"ן דיחו\"ע באה\"ר במס\"נ שעשה במסעות<sup data-n=\"245\">243</sup> שלו בא\"י. והנה ביעקב אמר אנכי ארד עמך מצרימה<sup data-n=\"246\">244</sup> ואנכי אעלך גם עלה, וי\"ל מה גם זה שהוא ריבוי<sup data-n=\"247\">245</sup> גדול כו', אך יעקב ירד בע' נפש<sup data-n=\"248\">246</sup> אנוס ע\"פ הדבור<sup data-n=\"249\">247</sup> כו', והוא בשביל עלי' גדולה שיעלו כנס\"י משם ע\"י בחי' אנכי דוקא, והוא מ\"ש אנכי ארד עמך ואנכי אעלך כו', והוא אנכי דמ\"ת שאמר אנכי אשר הוצאתיך כו', ויש בזה רבותא יתירה מאד להיות למעלה הרבה מעלי' דאברהם ממצרים כמ\"ש ויעל אברם כו' שלא הי' רק לפ\"ע מדריגתו בבחי' חסד עליון דאצי' כו', אבל מ\"ש אנכי אעלך אנכי ממש בבחי' סדכ\"ס דלית מח' תפיסא בי' כלל כו' וכמ\"ש ושמי הוי' ממש לא נודעתי להם רק במ\"ת לבד כו' וד\"ל. ומ\"ש רבותא עוד יותר מזה גם עלה קאי על כניסת בנ\"י לא\"י שנק' ארץ טובה ורחבה<sup data-n=\"250\">248</sup> שלמעלה גם ממדרגת דמ\"ת, וגם גם עלה עלי' גדולה יותר ממ\"ת וכמ\"ש ואעלה אתכם מעני מצרים<sup data-n=\"251\">249</sup> כו' אל ארץ טובה ורחבה<sup data-n=\"252\">250</sup> שהוא גילוי עצמות אוא\"ס ב\"ה במעשה",[["234","232","<b>ביו\"כ. . מעין עוה\"ב</b>: ראה לקו\"ת להאריז\"ל נח, ו, יג. לעיל פ' וארא עה, ד. וש\"נ."],["235","233","<b>דועד בחילופי אתוון דאחד</b>: ראה זהר תרומה קלד, א. מאמר ד\"ה זה במאמרי אדה\"א דברים ח\"א ע' רכד. וש\"נ."],["236","234","<b>ביום ההוא. . מירושלים</b>: זכרי' יד, ח."],["237","235","<b>דנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["238","236","<b>בתושבע\"פ. . מל' קרינן לה</b>: ראה ת\"ז בהקדמה (יז, א)."],["239","237","<b>אנכי ה' אלקיך אשר הוצאתיך מאמ\"צ</b>: יתרו כ, ב."],["240","238","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. אבן עזרא תולדות כז, יט. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["241","239","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["242","240","<b>דלית מח' תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["243","241","<b>אור</b>: גד: ליתא."],["244","242","<b>אברהם</b>: ג: חסר. ד: אברם."],["245","243","<b>במסעות</b>: ג: ביחו\"ע."],["246","244","<b>אנכי ארד עמך מצרימה</b>: ויגש מו, ד."],["247","245","<b>גם. . שהוא ריבוי</b>: ראה גם לעיל פ' שמות כא, א. וש\"נ."],["248","246","<b>יעקב ירד בע' נפש</b>: ראה ויגש מו, כז."],["249","247","<b>יעקב. . אנוס ע\"פ הדבור</b>: הגדה של פסח (פסקא וירד מצרימה)."],["250","248","<b>ארץ טובה ורחבה</b>: נסמן בהערה 250."],["251","249","<b>ואעלה אתכם מעני מצרים</b>: שמות ג, יז [ושם: ואמר אעלה — ראה גם לקמן רנה, א ובהערה 276. מאמרי אדה\"ז תקס\"ה ח\"א ע' שפא. תקס\"ז כאן (ע' קנ). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א כאן (סז, סע\"ב</a>). מאמרי אדה\"א שמות ח\"ב ע' תמז]."],["252","250","<b>אל ארץ טובה ורחבה</b>: שמות ג, ח. במאמרי אדה\"ז ובתו\"א שבהערה שלפנ\"ז, וכן בתו\"א תצוה פד, ג. דרך מצותיך יג, א. צה, ב. סה\"מ תרכ\"ז ס\"ע רט. מובא זה בהמשך אחד [בלי תיבת כו' המובא בפנים] עם הכתוב ואעלה אתכם."]]],[2300550438,"המצות בא\"י דוקא שנעוץ תחלתן בסופן דוקא שהוא תכלית השלימות דמ\"ת שהוא רק בחי' קבלת התו\"מ בהתחלה בלבד וד\"ל.\n<b>וביאור</b> ענין זה הנה יובן עד\"מ שאנו רואים בענין מולד הלבנה<sup data-n=\"253\">251</sup>, דהנה הלבנה קודם חידושה היא מתמעטת מאד ואין בה אור כלל רק כאשר היא כמו נקודה אחת זהו הנק' מולד הלבנה שמקבלת מאור השמש דסיהרא לית לה מגרמה כלום<sup data-n=\"254\">252</sup> כידוע, [ו]קודם שתקבל מהשמש הוא בבחי' ביטול במציאות ואינה רק כנקודה א' ואח\"כ מעט מעט מתחלת היא לקבל אור השמש עד שתתמלא אור בכולה כידוע. אך זה האור שמקבלת אינה בחצי העליון שבה שעומדת לנגד השמש כי מצד קירובה לשמש מתבטלת מפני אור השמש ואינה מאירה שם כלל כי שרגא בטיהרא<sup data-n=\"255\">253</sup> כו', רק בחצי התחתון שבה הוא שתאיר על הארץ ממה שקיבלה מאור השמש וכנ\"ל וכל שתתרחק יותר מן השמש יותר תתמלא אורה בחצי התחתון שלה וכנ\"ל, ויש דיעה להיפוך שבחצי העליון שבה מקבלת מן השמש בריחוקה ביותר ובחצי התחתון שבה אינה מאירה (כמ\"ש בסידור<sup data-n=\"256\">254</sup> ). וכך יובן בכללות נש\"י שמונים ללבנה ע\"כ בקידוש הלבנה שמקבלים פני <span data-k=\"pg\">שעב</span> ּ אביהם שבשמים ממש כו' להיותם רק בחי' כלי קיבול לקבל אור הוי' ולית להם מגרמייהו כלום, והוא אור ה' המאיר בנשמתם מאור דתו\"מ שנק' תורת ה' כאור השמש שמאיר בלבנה כמ\"ש וזרחה לכם יראי שמי<sup data-n=\"257\">255</sup> שמש צדקה כו' (וכמו שהלבנה בחצי העליון שבה תתבטל לגבי השמש, כך הוא בנש\"י בחי' ביטולה במציאות ממש לגמרי בקירובם פב\"פ במ\"ת כו', וכנ\"ל בפי' לאמור שיאמר בפיהם מפי ה' ששמתי דברי בפיך כו' גם עכשיו בכל לומד תורה יאיר דבר ה' בפיו ויש בכל א' בחי' ביטול במציאות מטעם זה וכמו מה להלן באימה ויראה כו' (ואין אור דתומ\"צ מאיר רק בחצי התחתון שהן בחי' נהי\"מ בחי' השפע דאור תומ\"צ כשבא לידי קיום במעשה דוקא כו'. וזהו וזרחה לכם יראי שמי בתומ\"צ [שמש] צדקה, שמש הוא אורות<sup data-n=\"258\">257</sup> שמאיר בנש\"י כשמש בלבנה, וצדקה הן המצות כידוע וכמ\"ש וצדקה תהי' לנו<sup data-n=\"259\">258</sup> כו', כמו הצדקה שהוא להחיות רוח שפלים<sup data-n=\"260\">259</sup> כך המצות כאשר הן נעשים בפו\"מ מחי' רוח שפלים דנש\"י כמ\"ש וחי בהם<sup data-n=\"261\">260</sup> ממש כו'. וכמו האור שאינו אלא להאיר החשך",[["253","251","<b>בענין מולד הלבנה</b>: בהבא להלן מציין בסמוך בפנים: בסידור. ראה שם שחרית לשבת קפב, ד ואילך. מאמרי אדה\"ז תקס\"ז כאן (ס\"ע קנ, ואילך). מאמרי אדה\"א דברים ח\"א ע' רטז. וש\"נ. נ\"ך ע' תסב. וש\"נ."],["254","252","<b>דסיהרא לית לה מגרמה כלום</b>: ראה זהר תולדות קלה, סע\"ב. ויחי רלו, ב. רמט, ב. ויקהל רטו, א. בחוקותי קיג, ב. מאמרי אדה\"ז הקצרים ע' שפג."],["255","253","<b>שרגא בטיהרא</b>: חולין ס, ב."],["256","254","<b>בסידור</b>: נסמן בהערה 251."],["257","255","<b>וזרחה לכם יראי שמי</b>: מלאכי ג, כ. 256) כו': ג: וד\"ל). ד: וד\"ל."],["258","257","<b>אורות</b>: גד: אור דתורה."],["259","258","<b>וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה לעיל פ' שמות יד, א. וש\"נ."],["260","259","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["261","260","<b>וחי בהם</b>: אחרי יח, ה."]]],[2300550453,"דוקא שזהו השפע מגבוה לנמוך כו' וע\"כ אמר דתורה ושפע [ו]צדקה דמצות אחד הוא, כמו הטעם שנק' התורה טוב מפני מ\"ש האור כי טוב<sup data-n=\"262\">261</sup> וטבע הטוב להטיב<sup data-n=\"263\">262</sup> להחיות רוח שפלים שהן המצות שנק' צדקה כמ\"ש צדיק ה' צדקות אהב<sup data-n=\"264\">263</sup> כו' וכמו והאר עינינו בתורתיך<sup data-n=\"265\">264</sup> כו' וזהו שמש וצדקה ענין אחד הוא וד\"ל.\n<b>והנה</b> יש בזה ג' מדרגות א' כאשר הלבנה עומדת בקירוב גדול לשמש שאז אין בה אפי' נקודה א' ואינה מאירה כלל (כענין הכלה הופכת פניה<sup data-n=\"266\">265</sup> כו') ואינו נק' מולד הלבנה כלל. והב' כאשר הלבנה מתחלת לקבל מן השמש הנק' מולד הלבנה כנקודה קטנה. והג' בהתמלאותה אורה<sup data-n=\"267\">266</sup> מעט מעט עד חצי חדש שנתמלא[ה] בכל חצי האחרון שבה כנ\"ל. וכך הוא בכנס\"י שבמצרים היו בתכלית הקטנות ולא יוכלו לקבל אור ה' בגילוי גמור בנפשם פב\"פ (והוא מפני שנגלה עליהם<sup data-n=\"268\">267</sup> כו' כמו קירוב השמש ללבנה שנתבטלו ממציאותם ורק מרחוק ה' נראה להם<sup data-n=\"269\">268</sup> בבחי' מקיף וכמו לכתך אחרי<sup data-n=\"270\">269</sup> כו' והוא בחי' האמונה שנק' אירוסין<sup data-n=\"271\">270</sup> ולא נישואין כידוע). והב' בשעת עמדן במ\"ת שהי' תחלה קולות וברקים וקול השופר<sup data-n=\"272\">271</sup> הולך וחזק מאד כנ\"ל<sup data-n=\"273\">272</sup> עד שנפלה עליהם אימה ופחד גדול בבחי' ביטול במציאות לגמרי כמו מה להלן באימה כו' וכמ\"ש וירא העם וינועו<sup data-n=\"274\">273</sup> ויעמדו מרחוק. אך אח\"כ התחיל להאיר בנש\"י מאור הוי' עצמו באמרו אנכי כו' שהוא אור דתורה שהוא כאור השמש כנ\"ל, אבל עדיין לא הי' האור מתפשט בכל המקומות שלהם<sup data-n=\"275\">274</sup> רק כנקודה א' וכמ\"ש ויצא כברק חיצו<sup data-n=\"276\">275</sup> כו' ע\"כ על כל דבור פ\"נ מצד שלא יכלו הכלים שלהם לקבל האור כו', עד שנסעו מ\"ב מסעות שבמדבר נכנס בהם האור מעט מעט עד שבא\"י נתמלא האור בכל קומת בנין כלבנה בחצי החדש כו'. וזהו אנכי אשר הוצאתיך מאמ\"צ בקירוב גדול כנ\"ל וקרבם להר סיני להיות בבחי' פב\"פ בבחי' ביטול במציאות והתחיל להאיר בהם אור דתורה כנ\"ל, ואח\"כ הכניסם לא\"י שהוא כמו בחי' מילוי הלבנה ע\"י הקיום התו\"מ בא\"י דוקא, וזהו ואעלה<sup data-n=\"277\">276</sup> אתכם מעני מצרים <span data-k=\"pg\">746</span> ּ כו' אל ארץ טובה ורחבה שקבלו עצמות אור א\"ס שמתו\"מ שם באים<sup data-n=\"278\">277</sup> בבחי' התרחבות ומילוי ולכך נק' ארץ טובה ורחבה כו' כמ\"ש כי רחבה מצותך מאד<sup data-n=\"279\">278</sup> וד\"ל. וגם עכשיו מקודם שיתחיל אדם ללמוד התורה יפול עליו אימה ופחד ויראה בבחי' ביטול במציאות כמו במ\"ת ממש<sup data-n=\"280\">279</sup> כמ\"ש מה להלן באימה כנ\"ל מאחר",[["262","261","<b>האור כי טוב</b>: בראשית א, ד."],["263","262","<b>וטבע הטוב להטיב</b>: ראה שער היחוה\"א פ\"ד. לעיל פ' שמות לד, ג. וש\"נ."],["264","263","<b>צדיק ה' צדקות אהב</b>: תהלים יא, ז."],["265","264","<b>והאר עינינו בתורתיך</b>: ברכת אהבת עולם (שחרית)."],["266","265","<b>הכלה הופכת פניה</b>: ראה פסחים פו, א (במשנה). ראה גם שע\"ת קא, א ואילך."],["267","266","<b>אורה</b>: גד: ליתא."],["268","267","<b>שנגלה עליהם</b>: הגדה של פסח פיסקא מצה זו."],["269","268","<b>מרחוק ה' נראה להם</b>: ע\"פ ירמי' לא, ב."],["270","269","<b>לכתך אחרי</b>: ירמי' ב, ב."],["271","270","<b>האמונה שנק' אירוסין</b>: ראה גם לעיל פ' בא קי, א ובהנסמן שם."],["272","271","<b>קולות וברקים וקול השופר</b>: יתרו יט, טז. יט."],["273","272","<b>כנ\"ל</b>: ד: ליתא. וראה לעיל רנג, ד."],["274","273","<b>וירא העם וינועו</b>: יתרו כ, טו."],["275","274","<b>המקומות שלהם</b>: גד: קומה שלימה."],["276","275","<b>ויצא כברק חיצו</b>: זכרי' ט, יד."],["277","276","<b>ואעלה</b>: ד: אעלה — ראה לעיל הערה 249."],["278","277","<b>באים</b>: גד: בא\"י."],["279","278","<b>כי רחבה מצותך מאד</b>: תהלים קיט, צו [בהוספת תיבת ”כי\"]."],["280","279","<b>ממש</b>: גד: ליתא."]]],[2300550468,"שדבריו חיים וקיימים בכנס\"י שנק' קבלת התורה כנ\"ל בפי' לאמר כו', ואחר שיתחיל ללמוד הוא<sup data-n=\"281\">280</sup> מקבל אור השם<sup data-n=\"282\">281</sup> שבדבר ה' בנפשו כנקודה [א'] עד שמתפשט בכולה ע\"י הקיום התומ\"צ בפו\"מ דוקא וד\"ל. (וזהו מי זאת עולה מן המדבר יפה כלבנה בזמן מ\"ת שהתחיל להאיר בהם שם הוי' דתורה שנק' שמש עד שנק' יפה כנ\"ל, אבל שלימות דכנ\"י הי' בבנין בהמ\"ק דשלמה שהי' גילוי שכינה בהיכל ק\"ק בתמידות שע\"ז אמר ברה כחמה<sup data-n=\"283\">282</sup> עצמה כו' וד\"ל).\n<b>והנה</b> התורה ניתנה בששה בסיון<sup data-n=\"284\">283</sup> כידוע, והטעם הוא כי הנה קודם מ\"ת מיד שיצאו ממצרים נצטוו לספור ז' שבועות<sup data-n=\"285\">284</sup> בשביל שיוכלו לקבל התורה פב\"פ כמו האשה הסופרת ז'<sup data-n=\"286\">286</sup> נקיים<sup data-n=\"287\">285</sup> כדי שתטהר לבעלה ותהי' ראוי ליחוד כו' והוא ענין בחי' הבירור דז' מדות דק\"נ שנאחזים במדות דקדושה להפריד הרע מן הטוב לגמרי וכידוע בענין ספה\"ע. והנה בשבוע הז' ביום הג' דוקא (שהוא ת\"ת שבמל') שהוא ר\"ח סיון התחיל להאיר בכנס\"י בבחי' נקודה א' לבד כנ\"ל להיות כי בר\"ח הוא זמן מולד הלבנה מגילוי אור השמש לבד<sup data-n=\"288\">287</sup> כנקודה קטנה, וכך כנס\"י מתחילים לקבל מאור הוי' ביום ר\"ח סיון דוקא אחרי בחי' הביטול שהי' בהם תחלה, והוא שהתחיל להתנוצץ בהם אור האהבה האלקי' שנק' אור שהאהבה הוא בחי' המשכת [ה]חסד וטוב כמ\"ש באור כי טוב וכתיב כי טוב חסדך<sup data-n=\"289\">288</sup> כו' וכתיב חסד אל כל היום<sup data-n=\"290\">289</sup> והאור נק' יום כמ\"ש ויקרא אלקים לאור יום<sup data-n=\"291\">290</sup> כו' כידוע וד\"ל. והנה מפני שנתעוררה גילוי אור האהבה והחסד לכנס\"י ממילא נמשך שנאה לאוה\"ע כמ\"ש אהבתי אתכם אמר ה'<sup data-n=\"292\">291</sup> וממילא ואת עשו שנאתי<sup data-n=\"293\">292</sup>, וז\"ש ע\"פ<sup data-n=\"294\">293</sup> ביום הזה באו מדבר סיני שירדה שנאה לאוה\"ע<sup data-n=\"295\">294</sup> משום דאת זלעו\"ז עשה האלקי' כו' וכשזה קם זה נופל, דהיינו בבחי' עלי' דכנס\"י בקירוב עוז וחיבה יתירה ממילא באותה שעה ממש יורד ונמשך שנאה לאוה\"ע כנ\"ל. ודוגמא לדבר [זה מ]מה שמבואר למעלה בענין עוז ותושי' דתורה שהתורה נק'<sup data-n=\"296\">295</sup> עוז לנשמה ותושי' להתיש כח הגוף משום דתוקפא דנפשא חולשא דגופא כו' וכנ\"ל באריכות. וכמו שהוא בדרך פרט בכל ניצוץ אלקי גם<sup data-n=\"297\">296</sup> הוא ממש בכללות נש\"י, כאשר האיר אור דתורה שנק' עוז לכללות נש\"י בר\"ח סיון הרי ממילא ירדה שנאה לאוה\"ע להתיש כחם ולהשפילם, משום דהתורה נק' עוז ותושי' עוז לנשמה ותושי' לאוה\"ע ברגע א' ממש מטעם הנ\"ל וד\"ל.",[["281","280","<b>הוא</b>: ג: ליתא. ד: התורה."],["282","281","<b>השם</b>: ג: הוי'. ד: ה'."],["283","282","<b>יפה כלבנה. . ברה כחמה</b>: שה\"ש ו, י."],["284","283","<b>התורה ניתנה בששה בסיון</b>: ראה שו\"ע אדה\"ז חאו\"ח רסתצ\"ד."],["285","284","<b>נצטוו לספור ז' שבועות</b>: ראה זהר אמור צז, ב. טור ברקת הל' פסח סתפ\"ט. במאמרי אדה\"ז תקס\"ז כאן (ע' קנא): התחילו לספור. ראה גם לעיל פ' בא קכא, ג. וש\"נ."],["286","286","<b>האשה הסופרת ז' נקיים</b>: מצורע טו, כח."],["287","285","<b>ז' שבועות. . ז' נקיים</b>: ראה גם לעיל קיא, ד. וש\"נ."],["288","287","<b>לבד</b>: גד: ליתא."],["289","288","<b>כי טוב חסדך</b>: תהלים סג, ד."],["290","289","<b>חסד אל כל היום</b>: תהלים נב, ג."],["291","290","<b>ויקרא אלקים לאור יום</b>: בראשית א, ה."],["292","291","<b>אהבתי אתכם אמר ה'</b>: מלאכי א, ב."],["293","292","<b>ואת עשו שנאתי</b>: שם, א, ג."],["294","293","<b>ע\"פ</b>: גד: ליתא."],["295","294","<b>מדבר סיני שירדה שנאה לאוה\"ע</b>: שבת פט, רע\"ב."],["296","295","<b>נק'</b>: גד: ליתא."],["297","296","<b>גם</b>: שם: כך."]]],[2300550483,"<b>וז\"ש</b> בחדש השלישי לצאת בנ\"י מאמ\"צ שהוא ר\"ח סיון ביום הזה אע\"פ שלא פי' באיזה יום אלא שחכמים דרשו שהוא בר\"ח סיון, לפי שעדיין לא האיר בכנס\"י כלל מאור ה' עד יום הזה שבאו מדבר סיני. וזהו ביום הזה שהוא יום שמאיר בו מבחי' חסד ואהבה העליונה ע\"כ נק' יום הזה כנ\"ל, ובזה היום ירדה שנאה לאוה\"ע, וזהו מדבר סיני כנ\"ל. אך זה הי' רק כנקודה א' עדיין<sup data-n=\"298\">297</sup> כמו מולד <span data-k=\"pg\">שעג</span> ּ הלבנה עדיין עד יום ששה בסיון שהי' קבלת התורה פב\"פ שהאיר ה' להם בגילוי והתפשטות אור ממש (אך לפ\"ז הי' צריך שיהי' זמן מ\"ת בז' בסיון כמבואר בפע\"ח<sup data-n=\"299\">298</sup> בזמן קידוש הלבנה שהוא בז' ימים למולד מטעם שיתמלא האור בז' מדות שלה, מצד שכאשר עבר עלי' ז' ימים<sup data-n=\"300\">299</sup> אז כבר נמשך בה ז' מדות באור ושפע השמש וראוי' לקידוש [אז דוקא] כנ\"ל. הענין הוא כידוע דז' שבועות הספירה [ש]הן מ\"ט שערי<sup data-n=\"301\">301</sup> בינה<sup data-n=\"302\">300</sup> והוא בחי' בירור ז' המדות שנמשך למל' שהוא שם ב\"ן<sup data-n=\"303\">302</sup>, וע\"כ הן [ז'] שבועות דוקא כמו בקידוש הלבנה שזמנה אחר ז' ימים בחדש דוקא מטעם שאז נשלם בה ז' מדות דז\"א שנק' שמשא<sup data-n=\"304\">303</sup> כנ\"ל, וכך בענין הספירה בז' שבועות הנ\"ל שהן ז' ימים דז\"א נשלם כל המשכות דז\"א במל' ממ\"ט שע\"ב כו' לברר למדות דק\"נ. אך בהגיע יום הג' בשבוע הז' שהוא בחי' ת\"ת שבמל', וידוע דבחי' ת\"ת כלול מחו\"ג ומנו\"ה ומל', וממילא ע\"כ בבחי' ת\"ת שבמל' נשלם כל בנין המל' בג' קוין שבה כי יש בת\"ת מכללות ג' הקוין מפני שעולה עד הכתר<sup data-n=\"305\">304</sup> רק שהוא בכלל עדיין (ובמ\"ת בא כח<sup data-n=\"306\">305</sup> הגילוי דרך פרט), וא\"כ בהגיע יום הג' בשבוע הז' שהוא ר\"ח סיון בחי' ת\"ת שבמל' ה\"ז כאלו נשלם ובא<sup data-n=\"307\">306</sup> כל הז' ספירות דשבוע זאת וכללות כל הז' שבועות נכלל[ו] בה וכלולי' מכללות דמ\"ט שע\"ב כו'. ולכך ביום הזה מאיר בה בחי' נקודה אחת עכ\"פ שהוא כמו בחג השבועות כאשר מאיר מאור הכתר<sup data-n=\"308\">307</sup> ממש, רק שביום זה יש בהעלם ובכח כל מה שעתיד להיות בגילוי גמור במ\"ת כמו במולד הלבנה דגם שהוא רק<sup data-n=\"309\">308</sup> כנקודה אחת הרי הנקודה הזאת נתפשט ונתמלא. ואע\"פ שהי' צריך להיות ביום הז' לסיון כלבנה שמתקדשת בז' בחדש, אבל מצד שנשלם ביום זה כל ז' השבועות דספה\"ע שהוא העיקר לקידוש וליחוד ע\"כ לא צריך להיות הכנה רק עד יום ה' לסיון שהכנה זאת אינה רק ה' ימים שהן ה\"ח דז\"א במל' כו' בשביל קבלת אור הכתר בשבועות (והוא ענין ג'<sup data-n=\"310\">309</sup> ימי הגבלה שאחר ר\"ח סיון, וזה שירד שנאה לאוה\"ע ביום זה כמו במ\"ת",[["298","297","<b>עדיין</b>: ג: ליתא. ד: חסר."],["299","298","<b>כמבואר בפע\"ח</b>: במהדורת קאריץ תקמ\"ב סדר מוצאי שבת פי\"א (צ, ג). וכ\"ה גם במאמרי אדה\"ז תקס\"ז כאן ע' קנא. ובהביאור שם ע' קנה: בע\"ח (נדפס גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370485\" data-slug=\"torah-or\" data-id=\"3901370485\">תו\"א יתרו קט, ג</a>)."],["300","299","<b>קידוש הלבנה שהוא בז' ימים. . עבר עלי' ז' ימים</b>: במאמרי אדה\"ז כאן: ביום הז', אבל בהביאור שם כבפנים. ראה ביאורי הזהר תשא נה, ג. דרך מצותיך ע, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460055\" data-slug=\"or-hatorah-hb\" data-id=\"8316460055\">אוה\"ת יתרו ס\"ע תתע</a> ואילך. מאמרי אדה\"א במדבר ח\"א ע' קמא. נ\"ך ע' תסג. הגהות מכ\"ק אדמו\"ר מוהרש\"ב [בסידור תו\"א רמה, א]. שער הכולל (מהדורת תשמ\"ז) פל\"ג, ס\"ב ובהערה שם. ס' השיחות תשנ\"ב ע' 68."],["301","301","<b>מ\"ט שערי בינה</b>: ראה ר\"ה כא, ב."],["302","300","<b>דז' שבועות. . מ\"ט שערי בינה</b>: ראה גם לעיל פ' בא קיא, ד. וש\"נ."],["303","302","<b>למל'. . ב\"ן</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ג. הנסמן בשער היחוד קמה, א הערה 14."],["304","303","<b>דז\"א שנק' שמשא</b>: ע\"ח (שער לידת המוחין) שכ\"א, פ\"ב."],["305","304","<b>בת\"ת. . שעולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט."],["306","305","<b>כח</b>: ג: בה. ד: ליתא."],["307","306","<b>נשלם ובא</b>: שם: נשלמו בה."],["308","307","<b>בחג השבועות. . הכתר</b>: ראה פע\"ח (שער חה\"ש) שכ\"ג, פ\"א."],["309","308","<b>רק</b>: גד: ליתא."],["310","309","<b>ג'</b>: שם: ליתא."]]],[2300550498,"ממש לפי שכמו שאין שליטה לחיצוני' בבחי' אור הכתר כך [גם] ביום זה שנשלם כל הז' שבועות דספירה מטעם הנ\"ל, משא\"כ בימי הספי' בחו\"ג כנ\"ל יש יניקה לאוה\"ע כי אברהם יצא ממנו ישמעאל<sup data-n=\"311\">310</sup> כו' וד\"ל). וזהו ביום הזה באו מדבר סיני שהוא בר\"ח סיון שהוא מולד הלבנה כנקודה א' וידוע שבנקודה אין התחלקות כלל רק כוללת [כל] מה שיתפשט מנקודה זו כנ\"ל, כך כל מה שנתפשט אור האלקי בכנס\"י אח\"כ במ\"ת הכל כלול בנקודה זאת, והוא ענין ביטול המציאות עד שלא נשאר רק כנקודה כמ\"ש בזהר ע\"פ שחורה אני<sup data-n=\"312\">311</sup> כו' אזעירת גרמה ואתעבידת נקודה חדא כו', וכידוע בבחי' ראשית עליות המל' בבחי' אצי' שנעשה בבחי' נקודה תחת יסוד<sup data-n=\"313\">312</sup> ז\"א כו' ואח\"כ נעשה בחי' הנקודה בפרצוף שלם בבחי' <span data-k=\"pg\">748</span> ּ האצי' בעשר ספי' אורות וכלים לעמוד פב\"פ והוא מ\"ת כידוע וד\"ל.\n<b>אך</b> הנה עדיין יש להבין למה נק' בשם מדבר סיני שזהו המורה על בחי' עלי' זאת דכנס\"י שהוא בחי' המל' לקבל אור הוי' דתומ\"צ בבחי' נקודה עכ\"פ כנ\"ל, דהנה מבואר למעלה בעיקר ענין קבלת התורה שהוא מ\"ש וידבר אלקים כנ\"ל<sup data-n=\"314\">313</sup> לאמר לדורות מה שכבר נאמר בסיני כנ\"ל, וכענין ודברי אשר שמתי בפיך כו' וכנ\"ל, וזהו פי' מדבר כמו [ו]מדברך נאוה<sup data-n=\"315\">314</sup>. דהנה כמו שהמדבר הוא בגשמיות שאין שם זריעה וצמיחה<sup data-n=\"316\">315</sup> רק חלק הדומם שבעפר כי אין בארץ המדבר<sup data-n=\"317\">316</sup> כח הצומח וגידול מצד עצמו, כך הוא במדבר הרוחני שהוא בחי' ארץ הרוחני<sup data-n=\"318\">317</sup> העליונה שנק' דבור כי שרש תיבה זאת דמדבר הוא דבור או דבר והמ\"ם שבראש התיבה הוא מאותיות האמנתי\"ו שהוא להקטין הענין כידוע. וענין הקטנה זאת להיות ידוע שיש בדבור ב' מדרגות, א' הדבור שיש בו רצון ובחירה ושכל שמדבר [ב]רצונו ושכלו ומדותיו בלב ובמח' שבמוח שאותיות הדבור מקבלים מן הרצון ושכל ומדות (וזהו כזריעה בארץ שצומח בתוס' וריבוי כן ירבה בדבור ויתוסף כו'). והב' הוא הדיבור שאין בו מעצמו כלום שאינו בא ע\"י בחירה ורצון כלל ולא ע\"פ שכלו ומדותיו, רק כמו העונה אחר הקורא כתינוק קטן שאומר מה שקורין לפניו שאין בדבור זה בחירה ורצון ודעת כלל, רק שמדבר מה שידברו וכעונה אחר הקורא וכמאמר המשנה עונין מה שהן אומרים<sup data-n=\"319\">318</sup> כו'. וזהו שנק' מדבר שמ\"ם זה בא להקטין הענין. דהיינו שדבור כזה שאינו בא מצד הבחירה ורצון הוא",[["311","310","<b>אברהם יצא ממנו ישמעאל</b>: ראה פסחים נו, א. הנסמן לעיל פ' בא קיז, ג."],["312","311","<b>שחורה אני</b>: שה\"ש א, ה. ראה זהר בלק קצא, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תמז."],["313","312","<b>נקודה תחת יסוד</b>: ראה זהר בלק שם ובהגהת הרח\"ו שם. לעיל פ' וארא עא, ד. וש\"נ."],["314","313","<b>כנ\"ל</b>: גד: כו'."],["315","314","<b>[ו]מדברך נאוה</b>: שה\"ש ד, ג."],["316","315","<b>שהמדבר. . שאין שם זריעה וצמיחה</b>: ראה חולין פח, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תמא. נ\"ך ע' ק ובהנסמן שם. וראה גם אגרות קודש כ\"ק אדמו\"ר מהוריי\"צ נ\"ע חי\"ד ע' פב."],["317","316","<b>המדבר</b>: גד: ליתא."],["318","317","<b>הרוחני</b>: שם: ליתא."],["319","318","<b>עונין מה שהן אומרים</b>: ראה סוכה פ\"ג, מ\"י."]]],[2300550512,"מתדבר ממילא אחר הדבור שכבר נאמר מפי הקורא כו', וכך הוא בענין מצות ת\"ת שהוא בדבור בפה<sup data-n=\"320\">319</sup> דוקא כנ\"ל<sup data-n=\"321\">320</sup>, שאין זה דבור שע\"פ בחירה ורצון ושכל עצמו כלל רק כעונה אחר הקורא כו' כמ\"ש תען לשוני אמרתיך כו' פי' תען כעונה אחר הקורא שאין לכנס\"י בחי' דבור כלל בפ\"ע בדברו בד\"ת הדבור הזה הוא רק דבר ה' כמ\"ש ודברי אשר שמתי בפיך כנ\"ל בפי' לאמור, ולפי שדבור זה דד\"ת מקבל רק מדבור העליון כו'<sup data-n=\"322\">321</sup> מדבר שמתדבר ומתנהג רק ע\"פ דבור העליון שכבר נאמר בסיני וכמ\"ש תען לשוני אמרתיך כו' (וזה יותר עליון ממ\"ש אד' שפתי תפתח כו' שגם שאין מלה בלשוני<sup data-n=\"323\">322</sup> רק ע\"י שנפתח לו כח הדבור אבל מ\"מ נק' דבור עצמו אח\"כ, משא\"כ דבור בד\"ת כל מה שידבר אינו דבור עצמו כלל רק דבר ה' ממש וה\"ז כדבר ה' בפי הנביא, וכמו שליח המלך שמדבר דבריו בשם המלך שהוא כאלו המלך עצמו מדבר ואין פיו רק כלי לבד לדבור המלך וכן דבר ה' בפי הנביא כו', וזהו מתניתין מלכתא<sup data-n=\"324\">323</sup> כמלך עצמו שגוזר כו', וזהו יתרון מעלה ד\"ת על התפלה). וזהו ומדברך נאוה להיות שע\"י קבלת התו' כנ\"ל בפי' לאמר הוקבע בכנס\"י לדורות בחי' כח הביטול במציאות הזה שהוא ביטול מן העצמות לגמרי רק להיות כלי לדבר ה' (וכמו ואהרן אחיך יהי' לך לפה<sup data-n=\"325\">324</sup> <span data-k=\"pg\">שעד</span> ּ כמ\"ש במ\"א), וכמו תען לשוני אמרתיך כו' לקבל מדבר ה' שבאותיות התורה שזהו גילוי אור דתורה שנק' שמשא כנ\"ל, ע\"כ א' [ו]מדברך נאוה שגם בחי' המדבר<sup data-n=\"326\">325</sup> שלך שהוא בחי' הדבור העליון<sup data-n=\"327\">326</sup> בד\"ת בביטול אמיתי נאוה כמו היופי<sup data-n=\"328\">327</sup> הנמשך בדבור שע\"פ בחירה ורצון וחכמה לפי שמקבל מכל יופי העליון שברצון העליון וח\"ע שהוא יו\"ד הדברות שדיבר פב\"פ דחכמת אדם תאיר פניו<sup data-n=\"329\">328</sup> ועל כל דבור כו' [מאחר ש]דבריו חיים וקיימים לעד וד\"ל. וזהו ביום הזה באו מדבר סיני בר\"ח סיון שנעשי' בחי' כלי קיבול לקבל בבחי' נקודה עכ\"פ שהוא בחי' הביטול במציאות האמיתי שכולל כל כלי הדבור בד\"ת להיות תען לשוני אמרתיך כו' וזהו ביום הזה דוקא באו מדבר סיני כו' וד\"ל.\n<b>ובכ\"ז</b> יובן שרש ענין מצות ת\"ת שהוא בדבור דוקא להיות שאין דבור זה רק כעונה אחר הקורא כמ\"ש תען כו', וידוע שהדבור שע\"פ השכל ורצון שרשו רק בחכ' שברצון שנק' ח\"ס שהוא בחי' כתר שבחכ' דהיינו התפשטו' הרצון שבא בבחירה בשכל כך ידבר או כך כו' (והוא דבור דמע\"ב שבחכ' ורצון המתפשט כו'), אבל הדבור שאינו תלוי ברצונו כלל רק",[["320","319","<b>מצות ת\"ת שהוא בדבור בפה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. לעיל פ' וארא פ, ג. וש\"נ."],["321","320","<b>כנ\"ל</b>: ג: ליתא. ד: חסר."],["322","321","<b>כו'</b>: גד: נק'."],["323","322","<b>אד' שפתי תפתח. . שאין מלה בלשוני</b>: תהלים נא, יז. קלט, ד. ראה מאמרי אדה\"א קונטרסים ע' שז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, סע\"ב</a> ובהערה 21."],["324","323","<b>מתניתין מלכתא</b>: ביצה כח, ב. ד: מתניתא מלכתא — כתובות סא, ב."],["325","324","<b>ואהרן אחיך יהי' לך לפה</b>: וארא ז, א (ואהרן אחיך יהי'). שמות ד, טז (לך לפה)."],["326","325","<b>בחי' המדבר</b>: ד: כח הדיבור."],["327","326","<b>העליון</b>: גד: ליתא."],["328","327","<b>היופי</b>: ג: ניתוסף: עליון. ד: העליון."],["329","328","<b>דחכמת אדם תאיר פניו</b>: קהלת ח, א."]]],[2300550526,"לפי הקורא כנ\"ל, שרשו מגיע בפנימי' ומקור הרצון שלמעלה מהתפשטותו במדות שברצון ושכל כו' שנק' רעדכ\"ר<sup data-n=\"330\">329</sup> בחי' גלגלתא דא\"א כו' וכמו שאמרו כל אשר דיבר ה' נעשה<sup data-n=\"331\">330</sup> כו'. וכך הי' במ\"ת עצמו ששמעו דבור דאנכי שהוא בחי' הרצון הפשוט ועצמי טרם שבא להתחלקות קוין דחו\"ב, וזהו עיקר קבלת התורה כנ\"ל. וכך הוא ממש בדיבור בד\"ת לדורות שהוא רק בחי' הביטול בתכלית לבעל הרצון שמלובש בדבר ה' שבמדבר כו' ולכך נק' מדבר (שלמעלה גם מבחי' מדבר דאדם כו'), וזהו שרש מצות ת\"ת גם עכשיו בד\"ת שהוא דברי אשר שמתי בפיך כו'. וע\"כ מי שתורתו אומנתו פטור מן התפלה<sup data-n=\"332\">331</sup> שדבור דתפלה הוא בכוונה ורעו\"ד שמצד [עצמו] שנק' העלאת מ\"ן ולפ\"ע ההעלאה כן ערך ההמשכה בא' יהי רצון מלפניך כו', אבל דבר ה' שבתו' [הרי] מעצמו בא והדבור דאדם אינו רק כלי שאינו לפ\"ע ההעלאה [כלל], וע\"כ ממילא נכלל בזה כל ההעלאת מ\"ן דתפלה ונק' חיי עולם<sup data-n=\"333\">332</sup> כמו ביו\"ד הדברות ממש שדבריו חיים וקיימים כו'. ולא שזהו דוקא בצדיקי' גדולים כרבא<sup data-n=\"334\">333</sup> ורב יהודה דכולי תנויי בנזיקין<sup data-n=\"335\">334</sup> כו', אלא כל מי שיש בו בחי' הביטול הנ\"ל<sup data-n=\"336\">335</sup> קודם הלימוד שהוא כמו במ\"ת מה להלן באימה כמו שאמר כל<sup data-n=\"337\">337</sup> תלמיד<sup data-n=\"338\">336</sup> כו' מלובש בד\"ת שלו דבר ה' שביו\"ד הדברות, [ו]אפי' מי שאין לו יראה ואימה כלל כתשב\"ר שאין יודעים מה שאומרים רק שמדברים דבר ה' שבמקרא הרי העולם מתקיים ע\"י רק [כ]שהוא הבל שאין בו חטא<sup data-n=\"339\">338</sup> שמלובש בהבל קול ד\"ת שלהם מבחי' דבר ה' [ש]ביו\"ד הדברות ממש [ש]דבריו חיים וקיימים כנ\"ל וד\"ל.\n<b>והנה</b> עם כל הנ\"ל יובן איך שבר\"ח סיון שבאו למדבר סיני כמ\"ש ביום הזה באו מדבר סיני [ש]הוא הי' עיקר הכנה למ\"ת להיות שהאיר אז בכנס\"י בבחי' נקודה עכ\"פ ומנקודה זאת נתפשטה מעט מעט עד יום הששי בחדש סיון שהוא זמן מ\"ת, והיינו גם עכשיו בבחי' הביטול במציאות באימה ויראה בשעה שי[ו]שב אדם ללמוד ד\"ת שהוא בחי' הנקודה <span data-k=\"pg\">750</span> ּ הנ\"ל שיוכל להתפשט אח\"כ בשעה שעוסק בתורה לקבל בנפשו דבר ה' ממש שבי' הדברות כנ\"ל, וע\"כ מברכים נותן התורה לשון הוה כו' כידוע וד\"ל. אך הנה כ\"ז לא יתכן רק במצות ת\"ת שבדבור דוקא כמ\"ש ודברת בם כו', אבל מצות עיון והגיון שבתורה<sup data-n=\"340\">339</sup> כמו והגית בו יומם ולילה<sup data-n=\"341\">340</sup> כו' וכן ובתורתו יהגה<sup data-n=\"342\">341</sup> יומם ולילה<sup data-n=\"343\">342</sup> איך שייך בזה ענין הנ\"ל בבחי' קבלת התורה שנגלה אור ה'",[["330","329","<b>רעדכ\"ר</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a> הערה 23."],["331","330","<b>כל אשר דיבר ה' נעשה</b>: יתרו יט, ח. משפטים כד, ז."],["332","331","<b>שתורתו אומנתו פטור מן התפלה</b>: שבת יא, א. ראה גם לעיל פ' וארא ע, ג. שע\"ת קב, ג ואילך. וראה גם לקמן פ' ויקהל שצח, ד."],["333","332","<b>שבתו'. . חיי עולם</b>: שבת י, א."],["334","333","<b>כרבא</b>: גד: כרבי. וראה לעיל על יד הערה 210."],["335","334","<b>ורב יהודה דכולי תנויי בנזיקין</b>: ברכות כ, א. ראה גם מאמרי אדה\"א בראשית ע' רעא. וש\"נ. שע\"ת פ, ג ובהערה 21. וראה גם לעיל על יד הערה 213."],["336","335","<b>הנ\"ל</b>: גד: באימה (כמו שאמר כל תלמיד כו')."],["337","337","<b>כל תלמיד</b>: שבת ל, ב."],["338","336","<b>באימה. . תלמיד</b>: גד: ליתא. וראה הערה שלפנ\"ז."],["339","338","<b>הבל שאין בו חטא</b>: שבת קיט, ב. ראה גם הנסמן לעיל פ' וארא פא, ד."],["340","339","<b>מצות עיון והגיון שבתורה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. לעיל פ' בשלח קסט, ב. וש\"נ."],["341","340","<b>והגית בו יומם ולילה</b>: יהושע א, ח."],["342","341","<b>ובתורתו יהגה</b>: תהלים א, ב."],["343","342","<b>יומם ולילה</b>: גד: כו'."]]],[2300550539,"דתורה כו'. והענין הוא דבאמת יש יתרון מעלה במצות עיון והגיון יותר ממצות הדבור דדברי תורה, שהרי במ\"ת שכאשר שמעו דבר ה' אנכי כו' לא הי' בהם בחי' דבור כלל וכלל כי הרי היו בתכלית הביטול במציאות עד שעל כל דבור פרחה נשמתן כו' רק ששמעו בשמיעה בלבד, והיינו כמו השומע דבר המלך שהוגה בעיון המחשבה להטות אזנו היטב לכל אשר יגזור אומר כו' שיש בזה ענין ביטול במציאות הרבה יותר מדבור שעונה אחר הקורא כו', כתלמיד שש[ו]מע מרבו שאין יכול לדבר ולהשיב לשואלו דבר ולא לדבר דברי הרב ששומע כי איידי דטריד למבלע<sup data-n=\"344\">343</sup> כו'. וכך הוא מצות הגיון התורה שמקשר כל פנימי' כח מחשבתו וחכמתו באותיות התורה כמ\"ש והגית בו כו' ובתורתו יהגה כו' שזהו בחי' ביטול עמוק בהעלם כח הרצון ו[ה]מח' שא\"א לבוא כלל בדבור בפה כמו במ\"ת ממש שלא הי' בהם הדבור רק שמיעה כמ\"ש נעשה ונשמע<sup data-n=\"345\">344</sup> בביטול עצמי' לקבל דבר ה' ברצון העצמי כשומע דבר מלך כו' שזהו ביטול עצמיות הרצון ושכל לקבל רצון המלך כו'. ובזה יש יתרון מעלה למצות עיון והגיון דתורה על מצות הדבור בד\"ת שהדבור בד\"ת נמשך ממש<sup data-n=\"346\">*345</sup> לאמור לדורות וכמו תען לשוני כו', אבל העיון והגיון הוא מגיע בעצם הרצון והחכ' שביו\"ד הדברות שלמעלה [מ]התגלות בדבור רק ששמעו מבחי' הדבור, וה\"ז [כ]דברים האלה עצמו שלמעלה מבחי' לאמור בדבור למה שכבר אמור כו' (והוא מדריג' משה שהי' כבד פה תושבע\"פ וכבד לשון תושב\"כ<sup data-n=\"347\">345</sup> ועכ\"ז אמר משה ידבר<sup data-n=\"348\">346</sup> כו', וכן תורה צוה לנו משה<sup data-n=\"349\">347</sup> בע\"פ כו' וכן בכל פרשה ויאמר<sup data-n=\"350\">348</sup> ה' אל משה לאמור לבנ\"י כו' וכמ\"ש במ\"א בענין מי שם פה לאדם<sup data-n=\"351\">349</sup> כו') (וז\"ש כ\"א בתורת ה' חפצו<sup data-n=\"352\">350</sup> כו' כי עביד אינש<sup data-n=\"353\">351</sup> אדעתי' דנפשי' קעביד להאיר שם הוי' דתורה בנפשו שזה בדבור דוקא כנ\"ל, ואח\"כ ובתורתו יהגה כו' במצות עיון שנק' תורתו ממש מטעם הנ\"ל והיינו עוסק בתורה לשמה לשם התורה<sup data-n=\"354\">352</sup> עצמה להאיר [מ]מקורה כו').\n<b>ובכ\"ז</b> יובן מה שמצינו בענין מחר חדש דיהונתן ודוד שא' ויסתר דוד בשדה<sup data-n=\"355\">353</sup> ויהי החדש כו'<sup data-n=\"356\">354</sup> וישב המלך על הלחם לאכול ויש בזה קרי וכתיב הקרי אל הלחם והכתיב על<sup data-n=\"357\">355</sup>",[["344","343","<b>איידי דטריד למבלע</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["345","344","<b>נעשה ונשמע</b>: משפטים כד, ז."],["346","*345","<b>ממש</b>: אוצ\"ל: ממ\"ש."],["347","345","<b>משה שהי' כבד פה. . תושב\"כ</b>: שמות ד, י. ראה זהר (רע\"מ) צו כח, א. מאמרי אדה\"א דברים ח\"ג ע' תתצו. וש\"נ. לעיל מז, ד. וש\"נ."],["348","346","<b>משה ידבר</b>: יתרו יט, יט. ראה גם לקמן פ' תצוה שכג, ג."],["349","347","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["350","348","<b>בכל פרשה ויאמר</b>: ראה גם לעיל פ' וארא נט, א הערה 30."],["351","349","<b>מי שם פה לאדם</b>: ראה לעיל פ' שמות מז, ד."],["352","350","<b>כ\"א בתורת ה' חפצו</b>: תהלים א, ב. ראה גם לקמן פ' משפטים רצ, ד. ויקהל תיז, א. וש\"נ."],["353","351","<b>כי עביד אינש</b>: פסחים סח, סע\"ב."],["354","352","<b>לשמה לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד. לעיל פ, ד. וש\"נ."],["355","353","<b>ויסתר דוד בשדה</b>: שמו\"א כ, כד."],["356","354","<b>כו'</b>: גד: ליתא."],["357","355","<b>הקרי אל. . והכתיב על</b>: ראה רד\"ק ומנחת שי שם."]]],[2300550552,"הלחם כו' עד ויהי ממחרת החדש השני ויפקד מקום דוד<sup data-n=\"358\">356</sup> כו', דהנה מבואר למעלה דמר\"ח סיון הוא הכנה למ\"ת מטעם שבר\"ח הוא בחי' מולד הלבנה כו' וכנ\"ל. והנה ידוע בענין דוד<sup data-n=\"359\">357</sup> ויהונתן<sup data-n=\"360\">358</sup> למעלה שזהו בחי' יסוד ומל' דדוד הוא בחי' המל' (וכמ\"ש בקידוש הלבנה דוד מלך ישראל<sup data-n=\"361\">359</sup> חי וקיים כו' כידוע). וזהו מחר חדש ונפקדת<sup data-n=\"362\">360</sup> שהוא מולד <span data-k=\"pg\">שעה</span> ּ הלבנה ופקידה זאת כמו וה' פקד<sup data-n=\"363\">361</sup> כו' שיאיר אור השמש בה וגם פקידה לשון חסרון כי הרי נעשה בבחי' ביטול המציאות קודם שתקבל כו' כנ\"ל, ויהונתן הוא אור השפע דשם הוי' כו' דיו\"ד ה' ו' ג' אותיות משם הוי' ונתן הוא הנתינה ושפע דז\"א במל', וזהו ענין בנין המל' למעלה. כי הנה ידוע במ\"ש וישב ה' מלך לעולם<sup data-n=\"364\">362</sup> וכן ה' מלך גיאות לבש<sup data-n=\"365\">363</sup> שבחי' המל' להחיות כל העולמות מאין ליש הוא בחי' צמצום וירידה גדולה להיות מלך על עם נפרד, שאין ערך כלל לבע\"ג<sup data-n=\"366\">364</sup> לבלתי בע\"ג, וכדי שיהי' מלכותו מכ\"ע הוצרך להיות ע\"י בחי'<sup data-n=\"367\">365</sup> צמצום ולבוש, וזהו ה' מלך על עולמות גיאות לבש נתלבש בלבוש וצמצום כו'. והוא כמו ענין אור הלבנה בארץ דכתי' המאור הקטן לממשלת הלילה<sup data-n=\"368\">366</sup> שהוא ירידת המל' בבי\"ע שנק' מלך לעולם דאין מלך בלא עם<sup data-n=\"369\">367</sup> ונק' מלכא תתאה<sup data-n=\"370\">368</sup> מלך זוטא<sup data-n=\"371\">369</sup>, וכמ\"ש<sup data-n=\"372\">370</sup> וישב ה' מלך לעולם היינו בחי' סוכ\"ע שנק' שמשא בחי' המאור הגדול לממשלת היום<sup data-n=\"373\">371</sup> דאצי' שמשם נמשך כח ועוז לבחי' המל' להיות מלך על עם כו' ונק' מלכא עילאה<sup data-n=\"374\">372</sup> וזהו ה' מלך גיאות לבש מגיאות הוי' דסוכ\"ע המתנשא כו' (והיינו בחי' התנשאות שמצד עצמו שנק' מלך יחיד<sup data-n=\"375\">373</sup> כו'). וזהו לבש הוי' עוז ואין עוז אלא תורה כמ\"ש בתורה בי מלכים ימלוכו<sup data-n=\"376\">374</sup> כו', דכתר מל' נמשך מכתר תורה דוקא, והיינו כמו שהשמש מאיר בלבנה במילואה כך אור הוי' דסוכ\"ע מאיר במל' שנק' ממכ\"ע כמ\"ש כי שמש ומגן הוי' אלקי'<sup data-n=\"377\">375</sup> כידוע. והיינו שלבש הוי' עוז דתורה כאשר הוי' מלך ואז תכון תבל בל תמוט שבחכ' שבתורה תכון תבל כו' והיינו ג\"כ וישב הוי' דסובב למלך לעולם בבחי' האר[ת] הוי' באלקים להיות מלך לעולם כו', והוי' עוז לעמו יתן עוז דתורה מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> ויהי החדש וישב המלך על הלחם לאכול פי' המלך הוא בחי' מלך עילאה דבחי' שם הוי' שנא' וישב ה' מלך",[["358","356","<b>ויהי ממחרת. . מקום דוד</b>: שמו\"א כ, כז."],["359","357","<b>דוד. . ומל'</b>: ראה פרדס (שער ערה\"כ) שכ\"ג, מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["360","358","<b>ויהונתן. . יסוד</b>: ראה לקו\"ת להאריז\"ל שמואל א כ, כ. מאמרי אדה\"א ויקרא ח\"א ע' שנה. וש\"נ. דברים ח\"ב ע' תכא. וש\"נ. דרושי חתונה ח\"ב ר\"ע תב."],["361","359","<b>בקידוש הלבנה דוד מלך ישראל</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' קנז ואילך."],["362","360","<b>מחר חדש ונפקדת</b>: שמו\"א כ, יח."],["363","361","<b>וה' פקד</b>: וירא כא, א."],["364","362","<b>וישב ה' מלך לעולם</b>: תהלים כט, י."],["365","363","<b>ה' מלך גיאות לבש</b>: תהלים צג, א. ראה גם לעיל פ' וארא עה, א. וש\"נ."],["366","364","<b>שאין ערך כלל לבע\"ג</b>: ראה גם לעיל פ' בשלח קעא, ב. וש\"נ."],["367","365","<b>בחי'</b>: גד: ליתא."],["368","366","<b>המאור הקטן לממשלת הלילה</b>: בראשית א, טז."],["369","367","<b>דאין מלך בלא עם</b>: בחיי וישב לח, ל. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["370","368","<b>מלכא תתאה</b>: זהר בראשית ל, א. מקץ קצט, ב."],["371","369","<b>מלך זוטא</b>: זהר ויחי רלט, א. זח\"ג (תוספת) ש, א."],["372","370","<b>וכמ\"ש</b>: גד: ומ\"ש."],["373","371","<b>המאור הגדול לממשלת היום</b>: בראשית א, טז."],["374","372","<b>מלכא עילאה</b>: זהר בהקדמה י, א. וירא צט, א. ח\"ש קלב, ב. וישלח קעב, ב. מקץ קצט, ב."],["375","373","<b>מלך יחיד</b>: נוסח ברכת ישתבח."],["376","374","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["377","375","<b>דסוכ\"ע. . ממכ\"ע. . כי שמש ומגן הוי' אלקי'</b>: תהלים פד, יב. ראה גם מאמרי אדה\"א שמות ח\"א ע' רסח. וש\"נ. נ\"ך ע' תסא."]]],[2300550565,"לעולם והוא כמו [ב]זמן מולד הלבנה שהשמש יאיר בלבנה שהוא בחי' דוד בחי' המל' כנ\"ל בפי' מחר חדש ונפקדת כו', ואמנם מפני שאין ישיבה למלך לעולם בלתי עוז דתורה כנ\"ל בפי' ה' מלך כו' לבש הוי' עוז כו', וזהו וישב המלך על הלחם שהוא לחמה דתורה כידוע בענין שולחן המלך<sup data-n=\"378\">*376</sup> כו', והיינו בהתחלת שפע דשם הוי' כדי להיות קבלת המל' במילואה התחיל להשפיע באור דתורה שנק' עוז כנ\"ל והוא מ\"ש על הלחם לאכול דלחם זה הוא מזונא דחכ[מתא]<sup data-n=\"379\">376</sup> כמ\"ש לכו לחמו בלחמי<sup data-n=\"380\">377</sup> תושב\"כ ושבע\"פ והן בחי' שתי הלחם דשבועות (שע\"כ יש בזה קרי וכתי' הקרי אל הלחם בבחי' התגלות אור דתורה שנק' לחם והוא התחלת גילוי אור השמש בלבנה כנקודה א' עכ\"פ (והוא מצות ת\"ת בדבור דוקא שבא בגילוי [כ]ענין לאמר שנק' קבלת התו' כו') והכתיב על הלחם בבחי' הסתימות וההעלם עדיין על הלחם דתו' כי עדיין לא נגלה אור דתו' שנק' לחם רק כנקודה א' שהיא רק הכנה בהעלם וכח לעיקר ההתגלות שבמ\"ת כו', וכנ\"ל בענין ביום הזה באו מדב\"ס שהוא בחי' הביטול במציאות שיוכל לקבל אור דתו' הנ\"ל<sup data-n=\"381\">378</sup> כו' וד\"ל (והוא מצות העיון והגיון דתו' שהוא ביטול העצמות בהעלם וסתימות, וזהו על הלחם למעלה מגילוי מקור<sup data-n=\"382\">379</sup> דתו' הבא[ה] בבחי' לחם ומזון, משא\"כ בשבועו' שמקריבין שתי הלחם ממש, ואמנם ישיבה זאת שיושב [המלך] על הלחם הוא הכנה למ\"ת כנ\"ל וד\"ל.",[["378","*376","<b>שולחן המלך</b>: ראה גם לקמן פ' ויקהל תכ, ד. וש\"נ."],["379","376","<b>מזונא דחכ[מתא]</b>: ראה זהר בשלח סב, א."],["380","377","<b>לכו לחמו בלחמי</b>: משלי ט, ה. ראה השמטות לזח\"א רס, א."],["381","378","<b>אור דתורה הנ\"ל</b>: גד: הכל."],["382","379","<b>מקור</b>: שם: (ה)אור."]]],[2300550042,"<b>תורת אדמו\"ר שדרש בק\"ק האמלע בחג השבועות </b>\nבשנת תקפ\"ג לפ\"ק\n<span data-k=\"pg\">752</span> ּ<b>משה</b> ידבר<sup data-n=\"383\">1</sup> והאלקים יעננו בקול<sup data-n=\"384\">2</sup>, וארז\"ל בקולו של משה<sup data-n=\"385\">3</sup>. ויש להבין בפסוק זה [מה זה] שא' משה ידבר ולא ביאר כלל מה הן הדברים שמשה ידבר והאלקים יעננו בקול, אם הכוונה על יו\"ד הדברות בכלל שמשה הי' מדבר דבר ה' לישראל והאלקים יעננו כו', הלא בפ' ואתחנן אמר בפירוש ותקרבון ותעמדון<sup data-n=\"386\">4</sup> תחת ההר וההר בוער באש כו' וידבר ה' אליכם מתוך האש קול דברים אתם שומעים ותמונה כו' זולתי קול<sup data-n=\"387\">5</sup> ויגד לכם את בריתו<sup data-n=\"388\">6</sup> כו' עשרת הדברים כו', א\"כ מזה משמע ששמעו בנ\"י דבר ה' דיו\"ד הדברות מפי הגבורה מתוך האש כל היו\"ד הדברות כי הרי אמר קול דברים אתם שומעים",[["383","1","<b>משה ידבר</b>: מיוסד על ד\"ה זה משנת תקס\"ו. הנחת כ\"ק אדה\"א נדפסה במאמרי אדה\"ז תקס\"ו ע' רד. והנחה אחרת ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370303\" data-slug=\"torah-or\" data-id=\"3901370303\">תו\"א יתרו סז, ד</a> וראה בהנסמן במ\"מ לשם. ראה עוד ע\"ד המאמר ותאריך אמירתו להלן ברשימות הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות לקמן בהמראי מקומות]."],["384","2","<b>משה ידבר והאלקים יעננו בקול</b>: יתרו יט, יט."],["385","3","<b>בקולו של משה</b>: ברכות מה, א."],["386","4","<b>ותקרבון ותעמדון</b>: ואתחנן ד, יא."],["387","5","<b>וידבר ה'. . זולתי קול</b>: ואתחנן שם, יב."],["388","6","<b>ויגד לכם את בריתו</b>: שם ד, יג."]]],[2300550074,"כו' ויגד [כו'] יו\"ד הדברים כו' ולא ע\"י משה, ובכאן אמר משה ידבר כו', ואם מפני שאמר שם (בפ' ואתחנן) פב\"פ דיבר ה' עמכם בהר מתוך האש<sup data-n=\"389\">7</sup> אנכי עומד בין הוי' וביניכם כו' להגיד לכם דבר ה' כי יראתם מפני האש<sup data-n=\"390\">8</sup> כו' דמשמע מזה דפב\"פ דיבר ה' בעצמו עמהם מתוך האש כמ\"ש למעלה וידבר ה' אליכם כו', וגם משה הי' מדבר דבר ה' לישראל כמ\"ש אנכי עומד כו' להגיד לכם [את] דבר ה' כו', הרי אמר אח\"כ את הדברים האלה (שהן כל יו\"ד הדברות האמורים למעלה) דיבר ה' אל כל קהלכם בהר מתוך האש הענן והערפל קול גדול ולא יסף<sup data-n=\"391\">9</sup> כו', הרי משמע דכל יו\"ד הדברות שמעו מפי ה' בעצמו ואח\"כ אמר ויהי [כ]שמעכם את הקול מתוך החשך כו' ותקרב[ון] אלי<sup data-n=\"392\">10</sup> כו' ותאמרו הן הראנו ה' את כבודו<sup data-n=\"393\">11</sup> ואת גדלו ואת קולו שמענו מתוך האש היום הזה ראינו כי ידבר אלקי' את האדם וחי ועתה למה נמות<sup data-n=\"394\">12</sup> כי תאכלנו האש כו' אם יוספים אנחנו לשמוע את קול ה' אלקינו כו' כי מי כל בשר<sup data-n=\"395\">13</sup> כו' קרב אתה ושמע כו' ואתה תדבר אלינו את כל אשר ידבר ה' אלקינו אליך ושמענו ועשינו<sup data-n=\"396\">14</sup> וישמע ה' את קול דבריכם<sup data-n=\"397\">15</sup> כו' ויאמר הטיבו את<sup data-n=\"398\">16</sup> אשר דברו כו' לך אמור להם שובו לכם לאהליכם<sup data-n=\"399\">17</sup> ואתה פה עמוד עמדי<sup data-n=\"400\">18</sup> כו', דהנה משמע מכ\"ז ששמעו כל יו\"ד הדברות מפי ה' בעצמו רק שבקשו על להבא אם יוסיפו עוד לשמוע שארי מצות ה' מפי עצמו מתוך האש שיריאים שלא ימותו ע\"כ א[מרו] קרב אתה כו', ובכאן משמע במה שאמר משה ידבר דקאי ביו\"ד הדברות דוקא. אך הנה רז\"ל עשו הכרעה בזה דב' דברות הראשונים אנכי ולא יהי' [לך] מפי הגבורה עצמו שמענו<sup data-n=\"401\">19</sup> ומפני שלא יכלו לקבל עוד מפני היראה הגדולה מן האש ע\"כ הי' משה ידבר דבר ה' בשאר הדברות לישראל, וז\"ש אנכי עומד [כו'] בעת ההיא להגיד לכם דבר ה' כי יראתם מפני האש כו', ומ\"ש את כל<sup data-n=\"402\">20</sup> הדברים האלה דיבר ה' כו' דמשמע [כל] יו\"ד הדברות לפי שגם בשאר הדברות דמשה הי' מדבר, אבל האלקי' יעננו בקול הרי שמעו קול ה' כשענה בקול וז\"ש כאן משה ידבר והאלקי' יעננו בקול, דקאי בשאר הדברות לבד ב' דברות הראשונו' ששמעו מפי ה' בעצמו ויתורצו כל המקראות הנ\"ל וד\"ל. ואמנם עדיין יש להבין במ\"ש <span data-k=\"pg\">שעו</span> ּ משה ידבר כו' שאם הוא על שאר הדברות כו' ה[רי] לא נז' בענין זה שמשה ידבר והאלקי' יעננו בקול כו', כי זה שאמר משה ידבר הי' קודם שירד ה' על ה\"ס והוא מ\"ש ויהי קול השופר<sup data-n=\"403\">21</sup> הולך וחזק מאד ואח\"כ אמר וירד ה'<sup data-n=\"404\">22</sup> כו'. וגם בפ' ואתחנן א' אנכי עומד להגיד לכם ולא נזכר שה' ענהו בקול. ואם",[["389","7","<b>פב\"פ. . האש</b>: שם ה, ד."],["390","8","<b>אנכי עומד. . מפני האש</b>: ואתחנן שם, ה [ושם: את דבר]."],["391","9","<b>את הדברים האלה. . ולא יסף</b>: שם ה, יט."],["392","10","<b>ויהי [כ]שמעכם. . אלי</b>: ואתחנן שם, כ."],["393","11","<b>ותאמרו הן הראנו ה' את כבודו</b>: ואתחנן ה, כא [ושם: ה\"א]."],["394","12","<b>ועתה למה נמות</b>: שם שם, כב."],["395","13","<b>כי מי כל בשר</b>: שם שם, כג."],["396","14","<b>קרב אתה ושמע. . ועשינו</b>: ואתחנן ה, כד [ושם: ואת]."],["397","15","<b>וישמע ה' את קול דבריכם</b>: שם ה, כה."],["398","16","<b>את</b>: בה: כל."],["399","17","<b>לך אמור להם. . לאהליכם</b>: ואתחנן שם, כז."],["400","18","<b>ואתה פה עמוד עמדי</b>: שם שם, כח."],["401","19","<b>אנכי ולא יהי' [לך]. . שמענו</b>: מכות כד, רע\"א. ראה מו\"נ ח\"ב פל\"ג. <a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא</a> פ\"כ. לעיל פ' וארא סט, א. וש\"נ."],["402","20","<b>כל</b>: בה: ליתא."],["403","21","<b>ויהי קול השופר</b>: יתרו יט, יט."],["404","22","<b>וירד ה'</b>: יתרו שם, כ."]]],[2300550106,"על ב' הדברות הראשונו' הרי מפי הגבורה בעצמו שמעו וא\"כ על איזה דבר הוא שאומר משה ידבר והאלקי' [י]ענהו כו'. ועוד דלשון ידבר והאלקי' יעננו הוא לשון עתיד וגם לשון הוה הוא דמשמע שמשה ידבר תמיד והאלקי' יעננו תמיד כו' והול\"ל משה דבר וה' ענהו כו'. וצ\"ל משום דמ\"ת הי' [גם] לדורות הבאים והתורה נצחית היא<sup data-n=\"405\">23</sup> בכל דור וזמן ע\"כ אמר משה ידבר הוא לשון עתיד ולשון הוה תמיד כו' וד\"ל.\n[ב] <b>ולהבין</b> זה הנה יש להבין עוד במה שמצינו בדרז\"ל דמ\"ת בחג השבועות יומא דקא גרים כמו שאמר רב יוסף אי לאו האי יומא<sup data-n=\"406\">24</sup> דקא גרים כמה יוסף איכא בשוקא. ולהבין מאי דקאמר האי יומא דוקא דקא גרים הלא מעלת מ\"ת הוא מצד עצמו דוקא ומה [לי] לתלות ביום הזה דוקא. ועוד דה[ל]א מ\"ת הי' לכל ישראל שעמדו בהר סיני וגם לבניהם אחריהם שבכל דור כו' א\"כ הכל שוין בזה, וא\"כ מהו שאמר אי לאו האי יומא כמה יוסף כו'<sup data-n=\"407\">25</sup> דמשמע שעיקר מ\"ת הוא לת\"ח כרב יוסף וכה\"ג כו' וד\"ל (ועוד שעיקר היום דחג זה נק' חג השבועות וכמ\"ש ועשית חג שבועות<sup data-n=\"408\">26</sup> כו' דז' שבועות תספר לך<sup data-n=\"409\">27</sup> כו'<sup data-n=\"410\">28</sup> מטעם ספי' דז' שבועות וכמ\"ש וספרתם לכם<sup data-n=\"411\">29</sup> כו' עד שמקריבין שתי הלחם<sup data-n=\"412\">30</sup> כו' ונק' עצרת<sup data-n=\"413\">31</sup> כו' וכמ\"ש וביום הבכורים<sup data-n=\"414\">32</sup> כו' ולא ע\"ש מ\"ת דוקא, וא\"כ למה אמר דיומא דקא גרים לענין מ\"ת לבד כו'). אך להבין כ\"ז יש להקדים תחלה בשרש ועיקר ענין מ\"ת שניתנה לנו ביום זה מה חידוש הי' בזה, הלא כבר קיים אאע\"ה כל התורה<sup data-n=\"415\">33</sup> כולה עד שלא ניתנה בה\"ס שהרי אמר עקב אשר שמע<sup data-n=\"416\">34</sup> [אברהם] בקולי וישמור משמרתי מצותי חקותי כו' וכתי' בי' כי ידעתיו<sup data-n=\"417\">35</sup> את<sup data-n=\"418\">36</sup> אשר יצוה את בניו ושמרו דרך הוי' לעשות צדקה ומשפט כו' ובודאי למד כל התורה ליצחק בנו ויצחק למד ליעקב בנו ויעקב לבניו<sup data-n=\"419\">37</sup>. וא\"כ מה חידוש הי' בנתינת התו' לישראל ע\"י משה אשר ע\"כ אמר [ל]משה וארא אל אברהם כו' ושמי הוי' לא נודעתי להם<sup data-n=\"420\">38</sup> מפני שלא קיבלו התורה. ואם מפני שהאבות לא קיימו התו\"מ בגשמיות בטלית ותפילין שלנו שאיך קיימו מצות ציצית ותפילין בד' פרשיות שהוא<sup data-n=\"421\">40</sup> פ' קדש והי' כו'<sup data-n=\"422\">41</sup> וכן תרומות ומעשרות<sup data-n=\"423\">42</sup> לכהן ולוי כו' וכה\"ג, אלא קיימו הכל בבחי' הרוחני'<sup data-n=\"424\">39</sup> דהיינו כמו שהמצות הן למעלה בבחי' האצי' שהן כל היחו\"ע שנעשי' למעלה באצי' ע\"י המצות שלנו וז\"ש מצותי",[["405","23","<b>והתורה נצחית היא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא</a> פי\"ז. לעיל פ' שמות א, א. וש\"נ."],["406","24","<b>אי לאו האי יומא</b>: פסחים סח, ב."],["407","25","<b>כו'</b>: בה: איכא בשוקא."],["408","26","<b>ועשית חג שבועות</b>: פ' ראה טז, י."],["409","27","<b>דז' </b>[בה: ז']<b> שבועות תספר לך</b>: שם שם, ט."],["410","28","<b>ועשית. . ז' שבועות תספר לך כו'</b>: בה: ז' שבועות תספר לך כו' ועשית חג שבועות כו'."],["411","29","<b>וספרתם לכם</b>: אמור כג, טו."],["412","30","<b>שמקריבין שתי הלחם</b>: שם שם, טז."],["413","31","<b>שבועות. . ונק' עצרת</b>: ראה שו\"ע אדה\"ז חאו\"ח רסתצ\"ד: חג השבועות הנק' עצרת בלשון חכמים. מאמרי אדה\"א דברים ח\"ד ע' א'שח."],["414","32","<b>וביום הבכורים</b>: פינחס כא, כו."],["415","33","<b>קיים אאע\"ה כל התורה</b>: ראה יומא כח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301670169\" data-slug=\"likkutei-sichot\" data-id=\"1301670169\">לקו\"ש תולדות (כרך לה) ע' 107</a> ואילך."],["416","34","<b>עקב אשר שמע</b>: תולדות כו, ה."],["417","35","<b>כי ידעתיו</b>: וירא יח, יט [בדילוג]."],["418","36","<b>את</b>: בה: למען. ראה לעיל רנא, א."],["419","37","<b>למד. . ליצחק. . ליעקב. . לבניו</b>: ראה תנחומא ויגש יא. שמו\"ר פ\"א, א. רמב\"ם הל' ע\"ז וחקותיהם ספ\"א."],["420","38","<b>וארא. . לא נודעתי להם</b>: וארא ו, ג. ראה לעיל רנא, א. וש\"נ."],["421","40","<b>שהוא</b>: בה: ליתא."],["422","41","<b>כו'</b>: שם: ויצי\"מ (!)."],["423","42","<b>תרומות ומעשרות</b>: ראה לקמן רנט, ג."],["424","39","<b>האבות. . התו\"מ בגשמיות. . הרוחני'</b>: ראה גם לעיל פ' וארא סג, ג. וש\"נ."]]],[2300550138,"חוקתי דוקא (כמשי\"ת), ולישראל ניתנו התו\"מ בגשמיות, זה עצמו יש להבין למה מטעם שלא קיימו בגשמיות א' ושמי הוי' לא נודעתי כו', אדרבה לכאו' המצות העליונות למעלה הרבה ממצות שלנו. ועוד דפשט הענין משמע שקיים אברהם כל התומ\"צ ממש וכמ\"ש אשר יצוה כו' ושמרו דרך הוי' לעשות צדקה ומשפט [ממש] כו'.\n<b>אך</b> הנה יש להקדים תחלה <span data-k=\"pg\">754</span> ּ בשרש ענין המצות העליונות שבבחי' האצי' שא' בזהר דרמ\"ח פקודין הן רמ\"ח אברים דמלכא<sup data-n=\"425\">43</sup> כידוע, ויש להבין מהו לשון אברים דה[ל]א אין לו גוף<sup data-n=\"426\">44</sup> ולא כו', אך יובן בהקדים תחלה שרש ענין ע\"ס דאצי' שנאצלו בכלים כמ\"ש אפיק י' תיקונין<sup data-n=\"427\">45</sup> וקרית לון י' ספירן כו' כמו חכ' מוחא חסד דרועא ימינא כו' כידוע, דהנה ידוע דבחי' ע\"ס דאצי' נאצלו מן המאציל ע\"י בחי' אותיות ושמות לבד והן ד' שמות<sup data-n=\"428\">46</sup> דע\"ב ס\"ג מ\"ה ב\"ן, דשם ע\"ב במילוי יודי\"ן הוא שרש לאור החכ' דאצי' ושם ס\"ג שרש לבינה דאצי' כו' וכללות האצי' נק' בזהר רזא דשמא קדישא<sup data-n=\"429\">47</sup> לבד שרשו<sup data-n=\"430\">48</sup> הן בחי' אותיות לבד (וכמשל הארת אור מעצמו' הנפש להיות מאיר אור השכל מן ההעלם לגילוי בכלי המוח דחכ' וכן אור הנפש להיות כח ההשגה והתפיסא בכלי מוח דבינה כו' דהארה זו אינה רק בחי' הגילוי מן ההעלם שבעצמות הנפש כידוע, וכל גילוי נק' בחי' אותיות לבד כידוע (וכן לפי המשל דס\"י כשלהבת הקשורה בגחלת<sup data-n=\"431\">49</sup> הרי הי' האור היוצא מן הגחלת כלול בהעלם תחילה בגוף הגחלת כו'), וכמו האותיות שבטלים ונכללי' בהעלם המח' והשכל כו' כך נכללים אורות דע\"ס במקורם ונק' ע\"ס בלי מ\"ה<sup data-n=\"432\">50</sup> כידוע. וזהו אפיק י' תקונין כו' שיצאו מן ההעלם לגילוי ע\"י אותיות ושמות דעצמות המאציל בלבד, אבל מצד עצמות המאציל הרי הוא אור פשוט בתכלית שלמעלה מבחי' ספי' ומדה כלל, וכמ\"ש אנת [הוא] חד<sup data-n=\"433\">51</sup> ולא בחושבן די\"ס אלא אחדות פשוט בתכלית. וגם מה שנק' חכים ולא בחכ' ידיעא<sup data-n=\"434\">52</sup> מבין ולא כו' וכמ\"ש בזהר דעבד מאנא רברבא<sup data-n=\"435\">53</sup> וקרא בי' גרמא חכים כו' שזהו ע\"י אותיות דשם ע\"ב כו', וזהו ולא בחכ' ידיעא דאינו עולה שם בשם מציאות חכ' כלל להיות נק' חכים רק כשבא מן ההעלם לגילוי אור ע\"י שם ע\"ב וכן מבין כו', וכך כל הספי' ומדות כמ\"ש ולאו דאית לך צדק ידיעא דאיהו דין כו' עד ולאו מכא\"מ כלל<sup data-n=\"436\">54</sup>. ולכך מה",[["425","43","<b>דרמ\"ח פקודין. . דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["426","44","<b>אין לו גוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם סנהדרין פ\"י היסוד הג'."],["427","45","<b>אפיק י' תיקונין</b>: ראה ת\"ז בהקדמה (יז, א)."],["428","46","<b>ד' שמות</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, רפ\"א. (שער דרושי אבי\"ע) שמ\"ב, רפ\"א. וראה גם הנסמן לעיל פד, ד."],["429","47","<b>רזא דשמא קדישא</b>: ראה זהר יתרו סז, ב ובמפרשים שם. מאמרי אדה\"א הנחות תקע\"ז ע' שנ. וש\"נ."],["430","48","<b>שרשו</b>: בה: שהשמות."],["431","49","<b>כשלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["432","50","<b>ע\"ס בלי מ\"ה</b>: ס\"י שם, מ\"ב."],["433","51","<b>אנת [הוא] חד</b>: ת\"ז בהקדמה (יז, א)."],["434","52","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז שם (יז, ב). ראה גם לקמן רסו, סע\"ד ואילך."],["435","53","<b>דעבד מאנא רברבא</b>: ראה זהר (רע\"מ) בא מב, ב."],["436","54","<b>ולאו דאית לך. . כלל</b>: ראה ת\"ז שם."]]],[2300550170,"שיוכל להיות<sup data-n=\"437\">55</sup> ע\"ס בלי מ\"ה גם בהיותם בגילוי אור משום דנכללים הם ומיוחדי' בעצמות המאציל בתכלית היחוד הפשוט וכמ\"ש דאיהו וחיוהי שהן האורות דע\"ס חד<sup data-n=\"438\">56</sup> ממש וכידוע וד\"ל.\n<b>וכ\"ז</b> מצד האורות כמו שהן באי' מן ההעלם דעצמות המאציל, אבל כאשר האורות מתלבשי' בכלים המגבילי' האור ונק' תקונין כמו חכ' מוחא חסד דרועא כמו משל של התלבשות השכל בכלי המוח כו' אז נק' ע\"ס במציאות דבר מ\"ה, והיינו מה שיוכל להיות מזה מקור להתהוות החכ' וחסד למטה בבי\"ע כמו עד\"מ מגילוי השכל אשר [מוגבל] במוח יומשך בכלי אותיות הדבור לזולתו שיקבל גם הוא השכל, משא\"כ קודם שמוגבל אור השכל בגילוי בכלי המוח לא יוכל לבא לידי השפעה ו[להיות] מקור למקבלים כלל וכה\"ג בשאר הספי' והמדות דאצי' וד\"ל. אך הנה א' דכמו דאיהו וחיוהי שהן האורות חד כך איהו וגרמוהי חד<sup data-n=\"439\">57</sup> שהן הכלים דאורות אע\"פ שמגבילים את האור כנ\"ל, וראי' לזה ממה שגם בחי' ה[כלים ד]אורות המדות דאצי' הן בחי' ז' שמות שאינן נמחקין<sup data-n=\"440\">58</sup> כמו שם אל בחי' כלי דאור החסד<sup data-n=\"441\">59</sup> דאצי' כמ\"ש כי חסד אל<sup data-n=\"442\">60</sup> כו'<sup data-n=\"443\">61</sup>, ושם אלקים בחי' <span data-k=\"pg\">שעז</span> ּ כלי לאור הגבורה<sup data-n=\"444\">62</sup>, ושם הוי' כלי לאור הת\"ת<sup data-n=\"445\">63</sup>, וכן הוי' צבאות בנו\"ה<sup data-n=\"446\">64</sup> ושם שדי ביסוד<sup data-n=\"447\">65</sup> כו'. ואע\"פ שהן שמות ואותיות שלמטה מן האורות דאצי' מאחר שהן מגבילים האור אחר בואו מן ההעלם לגילוי מן עצמו' המאציל (כמו כלי המוח שמגביל אור החכ' והחסד בלב וכה\"ג), עכ\"ז הרי הן שמות שאינן נמחקין לפי שהן בבחי' א\"ס ממש כמו האורות ממש דזהו שאמר איהו וגרמוהי חד [ו]כמ\"ש לך ה' הגדולה והגבו'<sup data-n=\"448\">66</sup> שהן הז' מדות דאצי' שמלובשים בכלי' דוקא עד לך ה' הממלכה שהוא בחי' מל' דאצי' כידוע וד\"ל.\n<b>אך</b> הנה שרש הענין הוא דכמו דאורות דע\"ס כלולים בעצמות כנ\"ל, כך בחי' הכלים שלהן שהן ז' שמות הנ\"ל כלולים בעצמות ממש, אך מה שנעשה [מ]בחי' הכלים המגבילים דוקא בחי' מקור להתהוות החכ' [והחס'] וכה\"ג בבי\"ע כנ\"ל זהו [ג\"כ] בא ע\"י צמצום הראשון שצמצם עצמותו באותיות ושמות כ\"א<sup data-n=\"449\">67</sup> להאציל הע\"ס להיות נק' ע\"ס בגילוי הי' עיקר הכוונה שיומשך ויוגבל גילוי האור בכלי דוקא כמו בשמות דאל ואלקים כנ\"ל כדי שיהי' מזה מקור לעולמות דוקא, וא\"ל לא הי' מאציל לע\"ס כלל מאחר שבאמת מצד עצמו לא[ו] מכא\"מ כלל וכלל<sup data-n=\"450\">68</sup>. א\"כ הרי",[["437","55","<b>מה שיוכל להיות</b>: בה: נק'."],["438","56","<b>דאיהו וחיוהי. . חד</b>: ת\"ז בהקדמה (ג, ב)."],["439","57","<b>איהו וגרמוהי חד</b>: ת\"ז שם."],["440","58","<b>ז' שמות שאינן נמחקין</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ו, ה\"ב. הנסמן לעיל קיב, א."],["441","59","<b>אל. . החסד</b>: ראה זהר אחרי סה, א. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 39."],["442","60","<b>כי חסד אל</b>: תהלים נב, ג [בהוספת תיבת כי — ראה לעיל פ' בא קיב, ד הערה 73]."],["443","61","<b>כו'</b>: בה: כל היום."],["444","62","<b>אלקים. . הגבורה</b>: ראה זהר יתרו פג, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 41."],["445","63","<b>הוי'. . הת\"ת</b>: ראה זהר ויקרא יא, א. סידור שער המועדים ריז, ג. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670419\" data-slug=\"torat-chaim\" data-id=\"2300670419\">תו\"ח בראשית מא, א</a> הערה 7."],["446","64","<b>הוי' צבאות בנו\"ה</b>: ראה הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח, סד, ג</a> הערה 43. לעיל קיב, א."],["447","65","<b>שדי ביסוד</b>: ראה זהר ויקרא יא, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 42."],["448","66","<b>לך ה' הגדולה והגבו'</b>: דהי\"א כט, יא."],["449","67","<b>כ\"א</b>: בה: כנ\"ל."],["450","68","<b>וכלל</b>: שם: כנ\"ל."]]],[2300550202,"כאשר האציל אור החכ' ע\"י שם ע\"ב כנ\"ל אינו אלא כדי שיהי' ממנו מקור ושרש לשרש עד שיהי' נמצא מציאות החכ' מאין ליש ממש בבי\"ע [ב]נשמות ומלאכים עד שיכול להיות התהוות החכ' למטה באדם שנק' שכל אנושי הגשמי, וכן כשהאציל אור החסד הי' בשביל שיהי' ממנו מקור ושרש לשרש לבחי' חסד בבי\"ע כו', וכה\"ג בכל הספי', וזהו שא' לאחזאה לאנהגא בהון עלמין<sup data-n=\"451\">69</sup> כו' לבד, אבל מצד עצמו לאו מכא\"מ כלל [כנ\"ל] וד\"ל. [ו]א\"כ הרי לפ\"ז יובן דגם האורות לא נאצלו רק כדי שיהי' מהם שרש ומקור לעולמות והוא דוקא כשמוגבלים בכלים ושמות שלהם כמו שם הוי' בניקוד פתח הוא כלי החכ'<sup data-n=\"452\">70</sup> דאצי' שיבא ויומשך מזה מקור לחכ' דנשמות דבריאה וכמו השפע'<sup data-n=\"453\">71</sup> דחכ' דשלמה כו', וכמו שאו' בשמו\"ע אתה חונן לאדם דעת כו', וכה\"ג בשם הוי' בניקוד צירי להיות מקור לשפע החסד<sup data-n=\"454\">72</sup> וכידוע בכוונת דח\"י ברכות דשם הוי' בש\"ע. וכן [מ]בחי' אותיות דמח' העליונה יומשך שרש למח' לנשמות ומלאכים אע\"פ שאין ערך כלל בין בע\"ג<sup data-n=\"455\">73</sup> לבלתי בע\"ג כלל וכמ\"ש כי לא מחשבותי מחשבותיכם<sup data-n=\"456\">74</sup> והכל ע\"י בחי' הכלים בשמות דאצי' כנ\"ל. וזהו שא' דכמו שאיהו וחיוהי חד כך איהו וגרמוהי חד ממש, דהנה כמו שנק' חכים ולא בחכ' ידיעא כו' וכנ\"ל משום שכלולים ומיוחדים בעצמות המאציל, ומה שנאצלו אינו רק שיהי' מקור [למקור] להתהוות העולמות כמו שיהי' מקור לחכ' ומדות<sup data-n=\"457\">75</sup> לחסד<sup data-n=\"458\">76</sup> וגבורה בנבראים כו' אבל הוא עצמו מובדל מערך חכ' ומדות שבאים בהשתלשלות דאבי\"ע כנ\"ל כו'. כך [בחי' הכלים דאורות דאצי' שנק' גרמוהי, וכמו ז' שמות הנ\"ל שאינם נמחקין ג\"כ מיוחדים וכלולים בעצמו' המאציל, הגם שמהם דוקא נעשה עיקר ומקור להתהוות בע\"ג לפי שהן המה המגבילים האור כנ\"ל, אבל גם זה הכח המגביל שלהם נמשך מכחו של עצמו' א\"ס ב\"ה שהוא כל יכול ויש בו גם] כח הצמצום להגביל האורות, והוא ע\"י צמצום הראשון בשמות וכלים [דע\"ב ס\"ג] שהאציל [ה]אורות כו'. ונמצא דבחי' שמות וכלים העליונים שלפני [ה]אורות דאצי' היינו ג\"כ בחי' כלים ושמות שמגבילים האורות והכל א' רק כדי שיהי' מקור ושרש להיות מציאות החכ' והחסד למטה בעולמות שלזה הי' הכוונה <span data-k=\"pg\">756</span> ּ ברצונו להאציל כו' כנ\"ל, מאחר דמצד עצמו לאו מכא\"מ כלל ולא האציל אורות בכלים רק לאחזאה לאנהגא בהון עלמין. וזהו שנק' תיקונין כשהאור בכלי דוקא כמו שא' אתקריאו בתקונא דא חסד דרועא כו' (ואדרבה שרש התהוות הכלים<sup data-n=\"459\">77</sup> המגבילים האורות למעלה משרש התהוות האורות, והיינו מבחי' אור המקיפים דקו\"ח כו' [מ]בחי'",[["451","69","<b>לאחזאה לאנהגא בהון עלמין</b>: ראה ת\"ז בהקדמה (יז, ב)."],["452","70","<b>הוי' בניקוד פתח. . החכ'</b>: ראה פרדס (שער הנקודות) שכ\"ח, פ\"ה. פע\"ח (שער העמידה) ש\"ט, פי\"ט. סידור האריז\"ל ומ\"ח שם. ובאוה\"ת ואתחנן ע' שעט מציין לזהר תולדות קמה, סע\"א."],["453","71","<b>השפע'</b>: ב: להיות השפע'. ה: שהי' השפע'."],["454","72","<b>הוי' בניקוד צירי. . החסד</b>: ראה פרדס שם, פ\"ד. מאמרי אדה\"א נ\"ך ע' ו. וש\"נ."],["455","73","<b>שאין ערך כלל בין בע\"ג</b>: ראה גם לעיל פ' בשלח קעב, ב. וש\"נ."],["456","74","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["457","75","<b>ומדות</b>: בה: ומח'."],["458","76","<b>לחסד</b>: שם: וחסד."],["459","77","<b>שרש התהוות הכלים</b>: ראה גם לעיל פ' שמות מו, א. וש\"נ."]]],[2300550234,"מטי ולא מטי<sup data-n=\"460\">78</sup> כמ\"ש בע\"ח, וע\"כ שם ע\"ב דמקור דחכ' הוא וכמו<sup data-n=\"461\">79</sup> שנעשה כלי החכ' להגביל האור והוא כמו שם הוי' בניקוד פתח כו' וד\"ל, וכה\"ג בכל הספי'), ולכן נק' ז' שמות שאינן נמחקין כי המה בבחי' עצמות אלקות דע\"ס<sup data-n=\"462\">80</sup> ממש וכמ\"ש כי הוי' הוא האלקי'<sup data-n=\"463\">81</sup> דהוי' הוא בחי' גילוי האורות דע\"ס<sup data-n=\"464\">82</sup> ובחי' אלקים הוא הצמצום דכלים המגבילים האורות כו' שהן ז' שמות דז' מדות דאצי' שם אל בחסד כו' כולא חד<sup data-n=\"465\">83</sup> [ש]שניהם כא' ממש כו' כנ\"ל וד\"ל [נמצאים מכחו של עצמו' המאציל].\n[ג] <b>וזהו</b> [מה] שא' לך ה' הגדולה כו' גם בז' שמות דמדות דאצי' משום דאיהו וגרמוהי שהן הכלים המגבילים האורות חד ממש מטעם הנ\"ל, וז\"ש כי עמך מקו\"ח<sup data-n=\"466\">84</sup> באורך נראה אור, פי' מקור חיים היינו בחי' ע\"ס דאצי' אורות בכלים כנ\"ל שנק' מקור כל החיים שנמשך למטה בעולמות דבי\"ע, וגם הם נאצלו ע\"י בחי' אותיות ושמות שנק' כלים כנ\"ל ע\"כ אמר כי עמך מקור חיים שגם בחי' המקור כל החיים של כל העולמות עמך טפל ובטל ונכלל[י'] בעצמות ממש כו'. אך עכ\"ז אמר באורך נראה אור, פי' באורך ממש העצמי נראה אור למטה כמו למעלה ממש בעצמותו, שזהו פי' הפשוט דנראה אור לשון עתיד שנראה אור עצמות[ו] שלמעלה ממקור [ה]חיים כו' והוא ע\"י המצות שנק' רמ\"ח אברים דמלכא שהן בחי' כלים עליונים הרבה יותר נעלה מבחי' האו\"כ דאצי' הנ\"ל עד שמחמתם דוקא נראה באורך ממש, והוא לעוה\"ב דכתי' ואמר ביום ההוא<sup data-n=\"467\">85</sup> הנה אלקינו זה לנוכח כו', וכן א' יחיינו מיומים<sup data-n=\"468\">86</sup> כו' יקימנו ונחי' לפניו ממש, וכמאמר המשנה כ\"י יש להם חלק לעוה\"ב<sup data-n=\"469\">87</sup> לפי שנק' צדיקים עולים<sup data-n=\"470\">88</sup> במעלת המצות בפו\"מ דוקא דשכר מצוה מצוה<sup data-n=\"471\">89</sup> עצמה כו' והוא במעלה ומדריגה ומעלה<sup data-n=\"472\">90</sup> יתירה גם על המצות שקיימו האבות [ברוחני'] כמשי\"ת.\n<b>אך</b> תחלה יש להבין פי' שני במ\"ש באורך נראה אור שנראה זה אינו רק בחי' הארה דהארה לבד, וקאי על בחי' ההשתל' דאו\"כ דאצי' מעצמו' המאציל ע\"י בחי' אותיות ושמות דע\"ב ס\"ג כו' לבד כנ\"ל, שע\"ז אמר ברישא כי עמך מקו\"ח כנ\"ל, וע\"כ מפרש בסיפא באורך נראה אור דהיינו מה שנראה ומושג לנו מציאות העולמות ונבראים במציאות חכ' וחסד וכה\"ג בבחי' גבול ה\"ז בא מהשפעת אורך באותיות ושמות הנ\"ל שהמשיך מלמעלה באורות דאצי' מן ההעלם לגילוי [להיות] נק' [חכים",[["460","78","<b>הכלים. . מטי ולא מטי</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ג. מאמרי אדה\"ז אתהלך לאזניא ע' רכב ואילך."],["461","79","<b>וכמו</b>: בה: עצמו."],["462","80","<b>דע\"ס</b>: ב: דא\"ס. ה: ליתא."],["463","81","<b>כי הוי' הוא האלקי'</b>: ואתחנן ד, לה. לט. בה: אלקי' — תהלים ק, ג."],["464","82","<b>דע\"ס</b>: ב: דא\"ס."],["465","83","<b>הוי' הוא האלקי'. . כולא חד</b>: ראה זהר בהקדמה יב, א. תרומה קסא, ב. לעיל פ' וארא ס, א. וש\"נ."],["466","84","<b>כי עמך מקו\"ח</b>: תהלים לו, י."],["467","85","<b>ואמר ביום ההוא</b>: ישעי' כה, ט."],["468","86","<b>יחיינו מיומים</b>: הושע ו, ב."],["469","87","<b>כ\"י יש להם חלק לעוה\"ב</b>: סנהדרין ר\"פ חלק (צ, א)."],["470","88","<b>עולים</b>: בה: כולם."],["471","89","<b>דשכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב."],["472","90","<b>ומעלה</b>: בה: ליתא."]]],[2300550265,"ו]מבין וחסדן בכלים המגבילים כו' [ב]ז' שמות הנ\"ל, ע\"כ יכול להיות התהוות מציאות החכ' וחסד בעולמות בבחי' גבול שנמצא שזה האור האלקי הנמצא בעולמות בע\"ג אינו רק מבחי' אור הנולד מתוך האור שנק' רק בחי' הארה דהארה כידוע, והוא מפני שנתצמצם עצם <span data-k=\"pg\">שעח</span> ּ האור בשמות וכלים דאצי' וע\"י בחי' הכלים יוצא ובוקע האור (וגם זה ע\"י הבדלת המסך שבין אצי' לבריאה<sup data-n=\"473\">91</sup> [ו]כידוע שלמ\"ד כלים דנה\"י דז\"א<sup data-n=\"474\">92</sup> הוא שנעשי' מקור לנר\"נ בבי\"ע אחר הבדלת המסך כו' וד\"ל). וע\"ד דוגמא כמו אור החסד שבאצי' שמוגבל בכלי מאיר למטה בנשמת אברהם שהי' בבחי' חסד דבריאה<sup data-n=\"475\">93</sup> בפנימיות ו[ב]מיכאל שר של חסד<sup data-n=\"476\">94</sup> דבריאה בחיצוני' כו', ומשם נמשך למטה עוד עד חסד דעשי' בפו\"מ להיות זן את העולם בחסד גשמי' כו' [ה\"ז] ירידת ההשתל' דכלי חסד דאצי' ברבוי רבבות מדרגות עד למטה בחסד דעשי'. וז\"ש נוצר חסד לאלפים<sup data-n=\"477\">95</sup> או ועושה חסד [לאלפי'<sup data-n=\"478\">96</sup>, פי' שחסדו העליון נמשך לאלפי' ורבבות מדרי' עד שנתהווה חסד גשמי בעוה\"ז הגשמי כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"479\">97</sup> שנצרך אור החסד] לבוא לבחי' בנין העולמות שז\"ש עולם חסד יבנה, בחסד זה ודאי צריך להיות ע\"י ריבוי ב' אלפים<sup data-n=\"480\">98</sup> מדרגות והכל מטעם הנ\"ל דמצד עצמות המאציל לאו מכא\"מ כלל ולא האציל רק כדי שיהי' שרש לחסד וחכ' למטה כנ\"ל. וע\"כ יש בחי' שמות וכלים לכל מדה וספירה במדריגה מיוחדת בפ\"ע וא\"כ יש לחסד ג\"כ שם מיוחד אליו שיבא ויומשך למטה מעצמות המאציל באבי\"ע שהן ודאי ע\"י ירידות המדריגות לאלפים ורבבות עד שמתהווה חסד דעשי' בפו\"מ, וכמו שם אל, דחסד [אל כל היום משתלשל ממקור החסד דאצי' עד שחסד אל כל היום ממש לזון כל הברואים ונותן לחם לכל בשר<sup data-n=\"481\">99</sup> כי לעולם חסדו ממש וכה\"ג בכל המדות כשם אלקי' בגבורה כו' ושם הוי' בת\"ת כו'] והוא כללות<sup data-n=\"482\">100</sup> ענין ח\"י ברכות דשמו\"ע שמבקשי' המשכות עליונ[ות] שע\"י ז' שמות עליונים דאצי' שיבאו למטה בגשמיות שיש לכל א' כוונה בשם מיוחד דוקא וכמ\"ש מפני מה ישראל צועקין<sup data-n=\"483\">101</sup> ואינן נענים מפני שאינם מכוונים בשם כו' [ו]כמשל המבקש מן הממונה של המלך דבר שלא ניתן בידו כו' (וכמ\"ש בסידור<sup data-n=\"484\">102</sup> עמ\"ש בספרי [ע\"פ] מי כה'<sup data-n=\"485\">103</sup> כו' אליו כו' וד\"ל).\n<b>אך</b> הנה מבואר למעלה שגם בחי' הכלים דאורות העליונים איהו וגרמוהי חד ממש כמו באורות, דהנה הגם שמדותיו ית' שהן אורות דאצי' באים בצמצום דשמות וכלים שזהו כמשל",[["473","91","<b>המסך שבין אצי' לבריאה</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["474","92","<b>שלמ\"ד כלים דנה\"י דז\"א</b>: ראה ד\"ה להבין מ\"ש בפע\"ח (קו\"א לתניא קנו, רע\"ב). הנסמן במאמרי אדה\"א נ\"ך ע' קפא. לעיל פ' שמות כד, ב. וש\"נ. לקמן פ' תצוה שכ, ד הערה 84."],["475","93","<b>בנשמת אברהם. . חסד דבריאה</b>: ראה אגה\"ק סט\"ו. לעיל פ' וארא סב, א. וש\"נ."],["476","94","<b>ו[ב]מיכאל שר של חסד</b>: ראה ת\"ז ת\"ע (קכו, א. קכז, א). שו\"ע אדה\"ז הל' תפלה סק\"כ, ס\"ב."],["477","95","<b>נוצר חסד לאלפים</b>: תשא לד, ז."],["478","96","<b>ועושה חסד [לאלפי'</b>: יתרו כ, ו. ואתחנן ה, י."],["479","97","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["480","98","<b>ב' אלפים</b>: בה: צמצומים באלפים."],["481","99","<b>ונותן לחם לכל בשר</b>: תהלים קלו, כה."],["482","100","<b>כללות</b>: בה: ליתא."],["483","101","<b>מפני מה ישראל צועקין</b>: ראה מדרש תהלים ספצ\"א. וש\"נ (בהערות באבער). בהערה הבאה."],["484","102","<b>בסידור</b>: שער הק\"ש פה, ג. אמ\"ב פתח השער פי\"ז ואילך. דרך מצותיך ע' קיז."],["485","103","<b>בספרי [ע\"פ] מי כה'</b>: ראה הנסמן לעיל פ' וארא עז, א."]]],[2300550295,"שם האדם שאינו רק כדי שיהי' [נק'] לזולתו ולא צריך שם זה לעצמו, כך ש[מות] דאל ואלקים וכה\"ג כנ\"ל אינו רק שיהא הוא ית' נק' ונמשך למטה בעולמות על ידם כידוע. ועכ\"ז הרי מתייחד עצמות אור א\"ס בהם בתכלית היחוד מאחר שאמר דאיהו וגרמוהי חד ממש, ופי' איהו היינו עצמות א\"ס וחיוהי וגרמוהי הן האו\"כ דאצי' כנ\"ל חד ממש כמו עד\"מ הידוע באדם התחתון שהוא נעשה בצלם אדם העליון דאצי' שאור וחיות נפשו המתלבש באברי גופו מתאחד הוא עם האברים והכל נחשב כא' ממש. וכך למעלה אע\"פ שאין לו כו' גם בחי' אור המתפשט מעצמות א\"ס בנאצלים ע\"י בחי' שמות וכלים הנ\"ל מתאחד בהם בתכלית וכולם מיוחדים בו בתכלית היחוד (וכמ\"ש אנת ממלא כל שמהן<sup data-n=\"486\">104</sup> כו' ואי אנת תסתלק מנייהו אשתארו כגופא בלא נשמתא כו' וכידוע[) וכמ\"ש לך ה' הגדולה והגבורה כו' וכידוע] שזהו כל עיקר הכוונה [ה]כלל[י]ת ביחו\"ע דפסוק ראשון דק\"ש באמרו שמע ישראל דהוי' אלקינו שהן כללות הע\"ס דאצי' הוא הוי' אחד ממש שכלולים באחדות פשוט ממש משום דאיהו וחיוהי וגרמוהי חד ממש כנ\"ל וד\"ל. וזהו שנק' האו\"כ דאצי' בשם בחי' אברים דמלכא כמו עד\"מ האבר באדם למטה שאור וחיות הנפש המלובש בו הרי מתאחד בו בתכלית והיו לאחדים ממש כאלו <span data-k=\"pg\">758</span> ּ הוא מהות א' [ממש] כו', כך הוא<sup data-n=\"487\">105</sup> בחי' האורות והשמות דעצמות המאציל שמתלבש בחכ' וחסד דאצי' מתאחדים בהם בתכלית ע\"י התלבשות זו בתכלית היחוד וד\"ל.\n[ד] <b>ומעתה</b> י\"ל מהו שהמצות נק' רמ\"ח אברים דמלכא כנ\"ל אחר שכבר נאצלו האו\"כ שנמשלו לבחי' האברים כנ\"ל שזהו הי' כבר קודם שניתנו התומ\"צ במ\"ת כו', ואמנם הנה תחלה יש להבין בהפרש שבין מצות הרוחני' שקיימו האבות כנ\"ל ובין מצות שלנו שנית[נו] לנו בדברים גשמיי' דוקא כנ\"ל. דהנה תחלה יש להבין בענין המצות שקיימו האבות ברוחני' שהן למעלה הרבה מבחי' או\"כ דאצי' עד שהן מוסיפי' אור עצמות המאציל באו\"כ. ויובן זה בעובדות דאבות כמו אברהם איש החסד<sup data-n=\"488\">106</sup> הרי ידוע דהאבות הן המרכבה<sup data-n=\"489\">107</sup> העליונה ממש שהי' אברהם מרכבה לאור [ה]חסד דאצי' ממש וע\"כ בעובדא שלו הי' מייחד יחו\"ע להוסיף אור בכלי החסד דאצי' ובכל קו הימין דחח\"נ<sup data-n=\"490\">108</sup> כו', והיינו לפי שהי' עבודתו בנפשו האלקי' במס\"נ אמיתי' באהבה ותשוקה ודביקות אמיתי' כל היום ולא הי' נפרד",[["486","104","<b>אנת ממלא כל שמהן</b>: ראה ת\"ז בהקדמה (יז, ב)."],["487","105","<b>הוא</b>: בה: ליתא."],["488","106","<b>אברהם איש החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["489","107","<b>דהאבות הן המרכבה</b>: נסמן לעיל רנא, ג."],["490","108","<b>קו הימין דחח\"נ</b>: נסמן לקמן רסט, ג."]]],[2300550322,"מיחו\"ע כלל אפי' רגע ממש, והי' הולך ועולה בכל יום [ויום] בעילוי אחר עילוי בתוס' אור האהבה ממדריגה למדריגה כמ\"ש לו התהלך לפני<sup data-n=\"491\">109</sup> כו', וכל הילוך הוא העלי' שעולה [והולך] מדרגא לדרגא וכמ\"ש בזהר עמ\"ש הלוך ונסוע<sup data-n=\"492\">110</sup> מדרגא לדרגא הנגבה בדרום דוקא שהוא האהבה<sup data-n=\"493\">111</sup> והדביקות כידוע, עד שמחמת עומק נקודת ההתקשרות נשמתו באמיתי' ועצמו' א\"ס ב\"ה העלה והביא וקישר כל העולמות גם עוה\"ז החומרי מבחי' הפירוד לגמרי<sup data-n=\"494\">112</sup> דהיינו בכל רכושו אשר עבד הכל הי' במס\"נ להעלות[ם] למעלה ביחוד העליון האלקי עד שלא הי' גם הגשמיו' נבדל כלל משרשו העליון בבחי' הרוחני' דבחי' אצי'. וז\"ש ואברהם כבד מאד במקנה בכסף ובזהב<sup data-n=\"495\">113</sup> ועבודה רבה<sup data-n=\"496\">114</sup> כו' דהכל העלה למעלה, וכמו ענין הנפש אשר עשו בחרן<sup data-n=\"497\">115</sup> כמ\"ש בזהר, וע\"כ הי' ממילא ממשיך תוס' גילוי אור א\"ס באצי' [מלמעלה למטה], עד גם בעוה\"ז השפל משום דכל העליות גורם המשכות<sup data-n=\"498\">116</sup> כידוע, וכמ\"ש בו ויקרא אברהם בשם ה' אל עולם<sup data-n=\"499\">117</sup> שקרא והמשיך בשם הוי' בתוס' אור באבי\"ע עד שהמשיך גילוי אור אלקי גם למטה להיות נק' אל עולם ממש בלי שום פירוד כלל מיחודו ית', והעיקר הי' ע\"י ב' דברים שהן בבחי' החסד, א' האהבה האמיתי' בדביקות נפלאה כנ\"ל, והב' בחסד וטוב גשמי' שהי' עושה למטה עם כל הבריות מצד בחי' שפלות וביטול כל עצמותו עד שהי' בעיניו כמותר ושיריים בעולם<sup data-n=\"500\">118</sup>, וכמ\"ש על עצמו ואנכי עפר ואפר<sup data-n=\"501\">119</sup> ממש, ובאתעדל\"ת כזאת בעובדות שלו הי' מעורר למעלה אתעדל\"ע<sup data-n=\"502\">120</sup> בעצמות אור א\"ס שימשיך ממקור החסדי' העליונים ג\"כ בבחי' חסד העליון<sup data-n=\"503\">121</sup> כמאמר במקום גדולתו שם אתה מוצא ענוותנותו<sup data-n=\"504\">122</sup> להיות מצמצם א\"ע להוסיף אור מן ההעלם שבעצמות לגילוי בכל הע\"ס דאו\"כ דאצי' ובפרט בבחי' אור החסד והחכ' דקו הימין כו'. ואע\"פ שכבר נאצלו הע\"ס באו\"כ [ע\"י] בחי' השמות ואותיות הנ\"ל, אבל זהו ע\"י צמצום [מאמר] קו המדה שהוא הנק' <span data-k=\"pg\">שעט</span> ּ קו\"ח בכלל, ואמנם ע\"י עבודתו של אברהם איש החסד באהבה ודביקות וקבלת מ\"ש<sup data-n=\"505\">123</sup> שלו במס\"נ הי' מוסיף אור הרבה בכפלי כפליים מבחי' עצמות דא\"ס שלמעלה הרבה מצמצום דקו המד[ה] בשמות ואותיות דע\"ב ס\"ג כו' וד\"ל.\n[ה] <b>וזהו</b> שא' דאברהם קיים כל המצות אפי' ע\"ת<sup data-n=\"506\">124</sup> כו' כמ\"ש וישמור משמרתי מצותי חקותי<sup data-n=\"507\">125</sup> כו', ולכאורה יפלא",[["491","109","<b>התהלך לפני</b>: לך יז, א."],["492","110","<b>הלוך ונסוע</b>: לך יב, ט. ראה זהר לך פ, א. פד, א."],["493","111","<b>בדרום. . האהבה</b>: זהר ויצא קנג, רע\"א."],["494","112","<b>לגמרי</b>: בה: לבחי' היחוד העליון."],["495","113","<b>ואברהם </b>[ה: ואברם]<b> כבד מאד במקנה בכסף ובזהב</b>: לך יג, ב."],["496","114","<b>ועבודה רבה</b>: תולדות כו, יד (אצל יצחק). וראה גם מאמרי אדה\"ז תקס\"ו כאן (ע' רו)."],["497","115","<b>הנפש אשר עשו בחרן</b>: לך יב, ה. ראה זהר שלח קסח, א. מאמרי אדה\"א דברים ח\"ג ע' א'קיט. וש\"נ."],["498","116","<b>העליות גורם המשכות</b>: ראה לעיל פ' בשלח ריט, א. וש\"נ."],["499","117","<b>ויקרא אברהם </b>[ה: אברם]<b> בשם ה' אל עולם</b>: חיבור שני כתובים. לך יג, ד. וירא כא, לג. ראה גם לקמן רסא, א. פ' תצוה שכט, ד [הוגה מגוכי\"ק]. מאמרי אדה\"ז תקס\"ו כאן (ע' רז). מאמרי אדה\"א דברים ח\"ג ע' א'נח. שמות ח\"ב ע' שנ ובהנסמן בהנ\"ל."],["500","118","<b>בעיניו כמותר ושיריים בעולם</b>: ראה גם לעיל פ' בשלח קע, ב. וש\"נ."],["501","119","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["502","120","<b>ובאתעדל\"ת. . מעורר למעלה אתעדל\"ע</b>: ראה זהר לך פח, א. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. לעיל פ' שמות מא, א. וש\"נ."],["503","121","<b>חסד העליון</b>: בה: ענוה גדולה."],["504","122","<b>במקום גדולתו. . ענוותנותו</b>: ראה מגילה לא, א. סה\"מ תרנ\"א ע' עא. הש\"ת ע' 40 בהערה. ס' מ\"מ הגהות והע\"ק לסש\"ב פ\"ד (ע' נ). מאמרי אדה\"א דברים ח\"א ס\"ע קצט ואילך. לקמן פ' תצוה שכג, א. ויקהל שפח, א."],["505","123","<b>וקבלת מ\"ש</b>: בה: וגמ\"ח."],["506","124","<b>אפי' ע\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670362\" data-slug=\"torat-chaim\" data-id=\"2300670362\">תו\"ח לך פה, ד</a> הערה 29."],["507","125","<b>וישמור משמרתי מצותי חקותי</b>: תולדות כו, ה."]]],[2300550347,"איך קיים מצות תרומות ומעשרות לכהן<sup data-n=\"508\">126</sup> (וגם שנתן מעשר מכל למלכי צדק<sup data-n=\"509\">127</sup> שהי' כהן לאל עליון זה הי' [שלא] כד\"ת של תורה בדיני תרומות ומעשרות כו'), וכן שאר מצות שא\"א שיתקיימו בלי סיב[ה] ידועה השייך להם כמצות תפילין בד' פרשיות קדש והי' [כו'] ומצות סוכה לפי שבסוכות ישבו וכן מצות פסח ומצה וכה\"ג. אך הענין הוא כידוע שיש תורה ומצות למעלה בבחי' הרוחני' (וכמו שלומדי' בג\"ע<sup data-n=\"510\">128</sup> כל דיני התו\"מ בסודות ברוחני' שלהם כידוע), וזהו שנק' מצותי דוקא דהיינו שקיים אברהם כל התומ\"צ שלמעלה והוא מה שנמשך תוס' אורות בכלים באמצעות עובדות שלו כנ\"ל בקו הימין חח\"ן כו' שבזה כלולים כל המצות עליונות הרוחני' [שנק' מצותי] ממש. וביאור זה הנה ידוע מה שא' הקב\"ה מניח תפילין<sup data-n=\"511\">129</sup> ומתעטף בציצית<sup data-n=\"512\">130</sup> ומבקר חולים<sup data-n=\"513\">131</sup> ומתעסק בתורה<sup data-n=\"514\">132</sup> וגמ\"ח<sup data-n=\"515\">133</sup> (וכמ\"ש הדבק במדותיו<sup data-n=\"516\">134</sup> כו'), וזהו שאמר וישמור משמרתי מצותי שהן המצות עליונות שה' עושה בעצמו כמו שהוא למעלה בבחי' האצי' באדה\"ע שעל הכסא שהוא בחי' ז\"א שנק' הקב\"ה<sup data-n=\"517\">135</sup> כידוע, וכמש\"א ג' שעות יושב הקב\"ה ועוסק בתורה<sup data-n=\"518\">136</sup> וכן א' מנין שהקב\"ה מתפלל<sup data-n=\"519\">137</sup> כו' ומתעטף בטלית כו' שנא' עוטה אור כשלמה<sup data-n=\"520\">138</sup> כו' וכתי' לבושי'<sup data-n=\"521\">139</sup> כו' ומניח תפילין כמו כחתן יכהן [פאר<sup data-n=\"522\">140</sup> שהן התפילין שנק'] פאר, וא' תפילין דמארי עלמא<sup data-n=\"523\">141</sup> מאי כתיב בהו ומי כעמך כישראל<sup data-n=\"524\">142</sup> [גוי אחד] כו' וכה\"ג בכל המצות העליונות שהקב\"ה עושה בעצמו נק' מצותי ממש וכן אנו אומרים אשר קדשנו במצותיו<sup data-n=\"525\">143</sup> כו', וע\"ז א' ג\"כ אלה המצות אשר יעשה [אותם] האדם העליון וחי בהם<sup data-n=\"526\">144</sup> מחיי החיים<sup data-n=\"527\">145</sup> דהיינו עצמות אוא\"ס שמאיר מבחי' אור א\"ס<sup data-n=\"528\">146</sup> בשם הוי' דז\"א כו', וכמו ע\"י תפילין דמארי עלמא שהן בבחי' בליטה ע\"ג הראש נמשך מקיפים דד' מוחין דז\"א כמ\"ש בתפילין שבראש האדם למטה כי שם הוי' נקרא עליך<sup data-n=\"529\">147</sup> כו' בבחי' מקיף וכה\"ג בטלית העליון. וכן במצות חסד דאדם העליון שח\"ס דלי\"ת<sup data-n=\"530\">148</sup> מל' שנק' דל<sup data-n=\"531\">149</sup> כו', זהו מוסיף אור מעצמות המאציל באורות וכלים דחסד דרועא ימינא<sup data-n=\"532\">150</sup> כו'. ובכללות הכולל כל המצות שהוא מצות ת\"ת למטה כך הוא למעלה כשהקב\"ה יושב ועוסק בתורה שנק' תורת האדם למעלה שנמשך עי\"ז מחכ'",[["508","126","<b>לכהן</b>: ראה לעיל רנז, ג."],["509","127","<b>שנתן מעשר מכל למלכי צדק</b>: לך יד, יח-כ. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051080\" data-slug=\"likkutei-sichot\" data-id=\"1300051080\">לקו\"ש לך כרך ה ע' 68</a> ואילך. תולדות כרך כה ע' 120 ואילך."],["510","128","<b>שלומדי' בג\"ע</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשסח וע' תשסט. שה\"א פח, ב ובהנסמן לשם."],["511","129","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. מאמרי אדה\"א שבהערה הבאה."],["512","130","<b>ומתעטף בציצית</b>: ר\"ה יז, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תסז. וש\"נ."],["513","131","<b>ומבקר חולים</b>: סוטה יד, א."],["514","132","<b>ומתעסק </b>[בה: ועוסק]<b> בתורה</b>: ע\"ז ג, ב."],["515","133","<b>וגמ\"ח</b>: סוטה יד, א."],["516","134","<b>הדבק במדותיו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380642\" data-slug=\"likkutei-torah\" data-id=\"4001380642\">לקו\"ת פינחס פ, ג</a>. שע\"ת לב, א. שבת קלג, ב. ספרי עקב יא, כב."],["517","135","<b>ז\"א שנק' הקב\"ה</b>: ראה סידור שער התפילין ז, ג. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670350\" data-slug=\"torat-chaim\" data-id=\"2300670350\">תו\"ח נח סט, א</a> הערה 1."],["518","136","<b>ג' שעות. . בתורה</b>: ראה ע\"ז ג, ב."],["519","137","<b>מנין שהקב\"ה מתפלל</b>: ברכות ז, א."],["520","138","<b>עוטה אור כשלמה</b>: תהלים קד, ב. ראה גם ש\"א נ, א ובהערה 12."],["521","139","<b>לבושי'</b>: דניאל ז, ט."],["522","140","<b>כחתן יכהן [פאר</b>: ישעי' סא, י. ראה גם סידור שער התפילין יד, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670419\" data-slug=\"torat-chaim\" data-id=\"2300670419\">תו\"ח בראשית מא, א</a> ספכ\"ט. שו\"ע אדה\"ז הל' תפילין סכ\"ה, ס\"ט."],["523","141","<b>תפילין דמארי עלמא</b>: ברכות ו, א."],["524","142","<b>ומי כעמך כישראל</b>: שמו\"ב ז, כג. ראה לקמן על יד הערה 164 ובהנסמן לשם."],["525","143","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצוות. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' לא."],["526","144","<b>אלה המצות. . וחי בהם</b>: חיבור ב' כתובים בחוקותי כז, לד. אחרי יח, ה. ראה גם הנסמן לעיל פ' בשלח קעה, ד."],["527","145","<b>מחיי החיים</b>: ראה יומא עא, א."],["528","146","<b>מבחי' אור א\"ס</b>: בה: בבחי' תוס' אור."],["529","147","<b>כי שם הוי' נקרא עליך</b>: תבוא כח, י. ראה גם לקמן פ' ויקהל תלב, ג."],["530","148","<b>חסד. . שח\"ס דלי\"ת</b>: ראה ת\"ז תכ\"ב [סז, רע\"ב]. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תרמג."],["531","149","<b>מל' שנק' דל</b>: ראה פע\"ח (שער הלולב) שכ\"ט, פ\"ג (לר\"י מערבי ד\"ה וזהו פירוש). מאמרי אדה\"א בראשית ע' תכו. וש\"נ. לקמן רס, ד."],["532","150","<b>דחסד דרועא ימינא</b>: ת\"ז בהקדמה (יז, א)."]]],[2300550370,"שבא\"ס עצמו בתורה זו כו', שהוא למעלה הרבה מעצם החכ' ומוחין דאדם העליון כמו שא' בזהר דאסתכל באורייתא וברא עלמין<sup data-n=\"533\">151</sup> וכן האציל באורייתא דתורה הקדומה כו' שנק' משל הקדמוני<sup data-n=\"534\">152</sup> כו'. וכן במצות שבת העליון כמ\"ש כי בו שבת<sup data-n=\"535\">153</sup> בג' מדרגות דנר\"נ דאדם דאצי' ה\"ז כמו מצות שבת שלמטה באדם התחתון כו' בכל פרטי דיני שבת באיסור [ל\"ט] מלאכות<sup data-n=\"536\">154</sup> כו' כמו אל יצא איש ממקומו<sup data-n=\"537\">155</sup> כו' וכן במצות סוכה במקיפי' דאימא וכן בכל המצות וגם בתפלה וכמו שא' מאי מצלי יה\"ר <span data-k=\"pg\">760</span> ּ מלפני<sup data-n=\"538\">156</sup> כו' וד\"ל. ולפ\"ז הרי יובן עכ\"פ דבחי' תוס' אורות העליונים שנמשך ע\"י מצות העליונות שה' עושה בעצמו ודאי הוא למעלה הרבה מאור המצומצם שבע\"ס דאצי' באורות וכלים, ומה שא' דרמ\"ח פקודין רמ\"ח אברים דמלכא היינו [ע\"י] רמ\"ח פקודין שלמטה שמוסיפים אור ברמ\"ח אברים דמלכא למעלה מעצמות המאציל (וכמ\"ש ועשיתם כאלו עשאוני<sup data-n=\"539\">157</sup> וכמשי\"ת). ואע\"ג דא' דאיהו וחיוהי וגרמוהי חד בתכלית היחוד מ\"מ אין זה רק ע\"י אור המצמצם שבשמות וכלים הנ\"ל כמו בחי' חכים דחכ' דאצי' ע\"י שם ע\"ב כו', הרי אין לזה ערך כלל לגבי [אור] החכ' שבתורה העליונה דאצי' שנק' תורת האדם למעלה שעל זה יושב ועוסק בתורה כו', וכה\"ג ברמ\"ח מ\"ע [העליונות שמחבר ומקשר לעצמו' אא\"ס ממש באדם דאצי' כנ\"ל, וזה הי' הכל ע\"י העובדות דאבות שעבדו למטה ב]אתעדל\"ת והעלאת מ\"ן שלהם כל בחי' מצות העליונו' שנק' מצותי וז\"ש וישמור מצותי וחוקותי כו' וד\"ל.\n[ו] <b>אך</b> הנה עדיין יש להבין איך יתכן שיקיים ה' את המצות מאחר שאין עוד זולתו ואין אלקים מבלעדו ואיך יתכן שיפול עליו חיוב ועול קיום המצות שהוא לקיים רצון העליון ממנו כו', וגם איך יתכן שיקיים מצות גמ\"ח וכמו ביקור חולים שבין איש לרעהו אחר שהוא יחיד לבדו כו'. אמנם הענין הוא דבאמת מ\"ש מצותי היינו כפשוטו מה שצוויתי שישמרו לעשות רצוני במצות הללו שזהו בחי' פנימיות רצונו הפשוט שלמעלה מכל רצון ותענוג שנמשך לבנין העולמות וע\"כ אמר על [כל] המצות רחבה מצותך מאד<sup data-n=\"540\">158</sup> שרצה\"ע שבמצות למעלה הרי הוא",[["533","151","<b>דאסתכל באורייתא וברא עלמין</b>: [בה: עלמא]: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט."],["534","152","<b>משל הקדמוני</b>: שמו\"א כד, יג וברש\"י שם. ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג."],["535","153","<b>כי בו שבת</b>: בראשית ב, ג."],["536","154","<b>[ל\"ט] מלאכות</b>: ראה שבת עג, א."],["537","155","<b>אל יצא איש ממקומו</b>: בשלח טז, כט."],["538","156","<b>מאי מצלי יה\"ר מלפני</b>: ראה ברכות ז, א."],["539","157","<b>ועשיתם כאלו עשאוני</b>: בחוקותי כו, ג. ראה זהר שם קיג, סע\"א. ויק\"ר פל\"ה, ז. מאמרי אדה\"א הנחות תקע\"ז ע' רלה. וש\"נ."],["540","158","<b>רחבה מצותך מאד</b>: תהלים קיט, צו."]]],[2300550389,"בבחי' א\"ס ממש, ולזאת יתכן לומר שאותו אור הרצה\"ע שבמצות שלמטה ממש שנגלה באצי' למעלה נעשה בבחי' או\"מ ולבוש לכל הע\"ס דאדם דאצי' שנאצל במדה דוקא<sup data-n=\"541\">159</sup> בלבד, וכמו מצות תפילין בראש שנק' פאר כו' ויש בזה רצה\"ע וחכמה שבעצמות א\"ס וכאשר נגלה זה האור בבחי' תפילין דמארי עלמא כשמניח תפילין בראשו [כבי'] זהו אור הרצון והחכ' שבא\"ס ממש שנעשה בבחי' מקיפים על המוחין דחו\"ב שבראש דז\"א (וכה\"ג גם בא\"א וע\"י וא\"ק שנק' אדם הגדול, הרי שרש המצות למעלה מהם והוא בפנימיות ועצמיות א\"ס ממש וכמ\"ש ואהי' אצלו אמון<sup data-n=\"542\">160</sup> כו' אצלו ממש כו'). אך עכ\"ז לא יתכן [ל'] קיום רצה\"ע במצות תפילין שלו כי ודאי הרי איהו וחיוהי וגרמוהי חד כנ\"ל רק כמו<sup data-n=\"543\">161</sup> שמקיים בעצמו כל המצות שציוה ה' לישראל לעשותם, ואמנם אין זה כמו מצות בבחי' חיוב ועול כי הרי אינו בבחי' פירוד כלל וכלל רק כמו שמקיים המלך בעצמו כל מה שמצוה לעשות לעמו כו'.\n<b>ואמנם</b> במצות הללו שמקיים בעצמו בכולן יש טעם [ושרש] ומקור למצות שיצוה לישראל דוקא לפי שישראל עלו במח'<sup data-n=\"544\">162</sup> דוקא, וכמאמר ג' קשרים<sup data-n=\"545\">163</sup> הן ישראל מתקשראן באוריי' ואורייתא בקוב\"ה כו' (וע\"כ לא ניתנה התו\"מ לכל אומה רק לישראל לבדם), וכמו מצות תפילין שאמר מאי כתיב בהו ומי כעמך ישראל<sup data-n=\"546\">164</sup> גוי א[חד] בארץ וכה\"ג לפי ששרש נש\"י עלו במח' וחכ' [ש]בראש דהיינו בחכ' העצמי' שבעצמות א\"ס ממש וכמו שישראל מייחדים <span data-k=\"pg\">שפ</span> ּ שם הוי' [באחדות הפשוטה] בפ' שמע ואומרים ה' אלקינו ה' אחד ממש, כך נגד פ' שמע שבתפילין דישראל יש בתפילין דמארי עלמא פסוק זה ומי כעמך ישראל גוי אחד בארץ שזהו למהוי אחד באחד<sup data-n=\"547\">165</sup> לפי שעלו במח' דאח\"פ ממש, וע\"כ נק' תפילין למעלה לשון התחברות<sup data-n=\"548\">*166</sup> כמו נפתולי אלקי'<sup data-n=\"549\">166</sup> כו' שע\"י התפילין שבראש למעלה מתחבר [מעצמו'] חכ' שבא\"ס עצמו שיהי' שורה בחכ' שבראש למעלה לפי שישראל נק' ראשית<sup data-n=\"550\">167</sup> כו'. וזהו שבתפילין העליונים נאמר ומי כעמך ישראל כו' והוא מ\"ש ישראל אשר בך אתפאר<sup data-n=\"551\">168</sup>, פי' אתפאר בפאר דתפילין שבראש (והיינו במצות תפילין דישראל בגשמיות דוקא ולא בעובדא דמקלות דיעקב הגם שהיו ג\"כ בענין התפילין<sup data-n=\"552\">169</sup> שלנו מטעם ש[י]תבאר בסמוך). וכמו\"כ כל המצות",[["541","159","<b>דוקא</b>: בה: דקו\"ח."],["542","160","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["543","161","<b>כמו</b>: בה: ליתא."],["544","162","<b>שישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב."],["545","163","<b>ג' קשרים הן</b>: ראה זהר אחרי עג, א. לעיל פ' שמות ב, ד. וש\"נ."],["546","164","<b>תפילין. . ומי כעמך ישראל</b>: דהי\"א יז, כא. ראה גם לעיל פ' וארא נו, ד. וש\"נ. לעיל על יד הערה 142."],["547","165","<b>למהוי אחד באחד</b>: ראה זהר תרומה קלג, סע\"ב ואילך. קלה, סע\"א."],["548","*166","<b>תפילין. . לשון התחברות</b>: ראה גם ערכי הכנויים לבעל סדר הדורות מערכת תפילין. מאמרי אדה\"ז תקס\"ו כאן ע' רז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370294\" data-slug=\"torah-or\" data-id=\"3901370294\">תו\"א כאן סו, א</a>. מקץ לה, ב. אוה\"ת תצוה ע' א'תשכט. ואתחנן ע' שלא."],["549","166","<b>נפתולי אלקי'</b>: ויצא ל, ח. ראה רש\"י שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151347\" data-slug=\"likkutei-sichot\" data-id=\"1300151347\">לקו\"ש וישב (כרך טו) ע' 334</a> הערה 28."],["550","167","<b>שישראל נק' ראשית</b>: ראה רש\"י בראשית א, א."],["551","168","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["552","169","<b>מקלות דיעקב. . התפילין</b>: זהר (סתרי תורה) ויצא קסב, א. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' יב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670576\" data-slug=\"torat-chaim\" data-id=\"2300670576\">תו\"ח בראשית מה, ד</a> הערה 45."]]],[2300550406,"העליונים שה' [עושה] בעצמו הכל עד\"ז במה שמתחבר עם ישראל למטה (ועם האבות הי' כזה ממש, אבל הכל למעלה ברוחני' לבד כמשי\"ת), וכמו במצות ציצית שהן ל\"ב חוטין דל\"ב נ\"ח<sup data-n=\"553\">170</sup> דמקיף דח\"ע שיהי' מזה זכרון על כל המצות כו', ולמעלה היינו המשכות ל\"ב נ\"ח ממקיף דלבוש דטלית העליון שנא' לבושי' כתלג כו' שמאיר מלמעלה למטה לבחי' הנ\"ל<sup data-n=\"554\">171</sup> (וכמ\"ש ופרשת כנפיך<sup data-n=\"555\">172</sup> כו' כמ\"ש בר\"מ). וכמ\"כ מה שאמר שה' מבקר חולים דזהו לכאו' פלא גדול איך שייך למעלה ביקור חולים (ומשמעות פשוטו שה' מבקר חולים שלמטה כמו שביקר לאברהם<sup data-n=\"556\">173</sup> וגם רופא חולים בעצמו, וכמו גם בכל חולה שנא' יסעדנו על ערש דוי<sup data-n=\"557\">174</sup>, וארז\"ל שהשכינה למעלה מראשותיו של חולה<sup data-n=\"558\">175</sup> להחיות אור נשמתו בגופו כו'). אך הענין יובן שיש ביקור חולים בבחי' הרוחני' כמו שידוע שיש ענין רופא חולים ברוחניות כמו הסולח כו' הרופא<sup data-n=\"559\">176</sup> לכל תחלואיכי דקאי ברפואת הנה\"א כאשר נק' חול[ה] ברוחני' ע\"י הפג[מי]ם של העון והחטא שיקולקל א' מאברים הפנימי' או החיצוני', כמו שפגמתי באות<sup data-n=\"560\">177</sup> יו\"ד זהו חולי הראש והפגם בה' או בוי\"ו הוא כמו חולי הלב כו' עד שנק' חולה בכל הנפש שיגיע לשערי מות ברוחניות כמ\"ש כל אוכל תתעב נפשם ויגיעו<sup data-n=\"561\">178</sup> כו' (וכמו שיוכלו להכיר בדופק הגשמי בחול[י] הגוף כך<sup data-n=\"562\">179</sup> הפגם בנפשו ונשמתו<sup data-n=\"563\">180</sup> ברוחניות שזהו א' דאדם [ביו\"ד] דפיק[ין] שלנגד ע\"ס כו' אם בכתר הוא<sup data-n=\"564\">181</sup> בדפק דקמ\"[ץ] כו' וכמ\"ש במ\"א בענין הנגעים<sup data-n=\"565\">182</sup> כו'), וצריכה הנשמה לרפואה אלקי' כמ\"ש רפאני ה' וארפא<sup data-n=\"566\">183</sup> וכן הרופא לכל כו' ורפואה [זו] בסם חיים דתורה כמא' חש בראשו יעסוק בתו'<sup data-n=\"567\">184</sup> כו' כמ\"ש רפאות תהי<sup data-n=\"568\">185</sup> כו' עד ולכל בשרו מרפא<sup data-n=\"569\">186</sup>. וכן התשובה מביאה רפואה לנפש<sup data-n=\"570\">187</sup> כו' כמו רפואת הגוף ממש, והיינו ע\"י סליחת העון כמ\"ש הסולח כו' הרופא כו' שזהו ע\"י תשובה דוקא, וזהו סדר כל<sup data-n=\"571\">188</sup> הברכות בשמו\"ע השיבנו וסלח לנו ורפאנו כו' דהא בהא תליא כידוע.\n<b>וכך</b> יובן ענין ביקור חולים ברוחניות בנשמות שנק' חולים ברוחני' שיבקר ה' אותם לפקח בפיקוח [כל] נפש ורוח ונשמה וכמו ה' יסעדנו כו' שזהו [פי'] הפשוט דה' מבקר חולים ברוחני' וגשמיות וע\"כ הדבק במדותיו כו'. ויש עוד ביקור חולים ברוחניות גם למעלה מעלה והוא החולי שבנפש שאינו מחמת",[["553","170","<b>ל\"ב חוטין דל\"ב נ\"ח</b>: ראה זח\"ג (תוספת) שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["554","171","<b>הנ\"ל</b>: בה: המל'."],["555","172","<b>ופרשת כנפיך</b>: רות ג, ט."],["556","173","<b>כמו שביקר לאברהם</b>: וירא יח, א. וברש\"י שם מב\"מ פו, ב."],["557","174","<b>יסעדנו על ערש דוי</b>: תהלים מא, ד."],["558","175","<b>שהשכינה למעלה מראשותיו של חולה</b>: שבת יב, ב."],["559","176","<b>הסולח כו' הרופא</b>: תהלים קג, ג."],["560","177","<b>שפגמתי באות</b>: ראה סידור אדה\"ז סדר ק\"ש שעהמ\"ט. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'פא."],["561","178","<b>כל אוכל תתעב נפשם ויגיעו</b>: תהלים קז, יח."],["562","179","<b>כך</b>: ב: ליתא. ה: ניתוסף: יש בחי' שנק' דופק ברוחני' שבו מרגיש."],["563","180","<b>ונשמתו</b>: ב: ורוחו. ה: ליתא."],["564","181","<b>בכתר הוא</b>: ב: בבחי' הי'."],["565","182","<b>בענין הנגעים</b>: ראה טעמי המצות להאריז\"ל פ' וירא. ביאוה\"ז עג, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תנב."],["566","183","<b>רפאני ה' וארפא</b>: ירמי' יז, יד."],["567","184","<b>חש בראשו יעסוק בתו'</b>: ערובין נד, א."],["568","185","<b>רפאות תהי</b>: משלי ג, ח."],["569","186","<b>ולכל בשרו מרפא</b>: משלי ד, כב."],["570","187","<b>התשובה מביאה רפואה לנפש</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תתעט."],["571","188","<b>כל</b>: בה: ליתא."]]],[2300550423,"פגם וקלקול אדרבה מחמת רוב האהבה והתשוקה האלקי' שנק' חולת אהבה<sup data-n=\"572\">189</sup> כידוע שבאה בנשמה מחמת העדר [הגילוי] וריחוק שלה מאלקות, כאשר תכסוף הנפש ביותר לעלות <span data-k=\"pg\">762</span> ּ ולידבק [באלקות כמו נכספה וגם כלתה נפשי<sup data-n=\"573\">190</sup> כו' וכן צמאה לך נפשי<sup data-n=\"574\">191</sup> וכה\"ג ואמנם לא תוכל לעלות ולידבק] כראוי מקוצר ההשגה או מצד הריחוק העצום כמו בטרדת הפרנסה בדוחק ולחץ וכה\"ג שאז נק' חולת אהבה, שמחמת זה תחלה הנפש בחולי הרוחני' ממש כמו שיש חולת אהבה בגוף כשיחשוק לדבק זה בתאוה גשמיי' ולא יוכל להשיגו כו' (וכמו מעשה בא' שהעלה בלבו<sup data-n=\"575\">192</sup> כו'), ואז נק' חולי ממש בבחי' חולת אהבה וצריכה לרפואות לרפאה<sup data-n=\"576\">193</sup> מחולי זה ואין רפואה לחולי כזו שנק' חולת אהבה רק להשיב את הנפש בדבר תענוג וטעם וריח טוב שמשיב את הנפש כו'. וכן יובן גם למעלה ביותר כמו בנשמה פרטית כך הוא גם בכללות נש\"י בשרשם שהוא בחי' מל' דאצי' שמתרחקת מן בעלה בגלותא בבי\"ע<sup data-n=\"577\">194</sup> שז\"ש ובפשעכם שולחה אמכם<sup data-n=\"578\">195</sup> כו' וכמו שא' דאתתא אתרחקת מן בעלה<sup data-n=\"579\">196</sup> וכמאמר דגלו לאדום שכינה עמהם<sup data-n=\"580\">197</sup> כו', שמחמת העדר הקירוב למעלה להתייחד בבעלה שהוא שם הוי'<sup data-n=\"581\">198</sup> דז\"א שנק' יחוד קוב\"ה ושכינתי' אז א[ו]מר[ת] סמכוני באשישות רפדוני בתפוחים<sup data-n=\"582\">199</sup> כי חולת אהבה אני בגלותא דוקא, וכמו הנשמה פרטי' שתחלה חולת אהבה מחמת הריחוק שלא תוכל לעלות ולידבק במקור חוצבה באלקים חיים כו'. וענין הרפואה לחולי זה שהוא חולת אהבה הוא מ\"ש סמכוני באשישות ובתפוחים כו' שהוא בחי' טעם ותענוג הרוחני האלקי שבאורות העליונים דאצי' שיש ביכולתם להשיב ולרפאות את החולי דחולת אהבה זאת בכללות נש\"י כמו שהן בשרשם בבחי' הרוחני<sup data-n=\"583\">200</sup>, והוא הנק' אשישא דעייל חמרא<sup data-n=\"584\">201</sup> דאורייתא שהן סודות וטעמי תורה שנק' יינה של תו'<sup data-n=\"585\">202</sup> שמגלה בחי' הסוד ה' שבתומ\"צ כמו נכנס יין יצא סוד<sup data-n=\"586\">203</sup> כו' (וכמו שרואים בנשמה פרטית כמו<sup data-n=\"587\">204</sup> שהיא מרת נפש בסיבת ריחוקה מאלקות ביותר עד שתחלה חולת אהבה תשיב נפשה ורוחה כו' ע\"י יינה של תורה בעסקו בפנימי' סודות התורה שנק' אשישות כמ\"ש סמכוני באשישות כו'), וכן רפדוני בתפוחים כו' שהוא הריח המתוק<sup data-n=\"588\">205</sup> וחזק שבתפוח שמכוון רעותא<sup data-n=\"589\">206</sup> כו'. וכן הוא התענוג שברצון",[["572","189","<b>חולת אהבה</b>: שה\"ש ב, ה. ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' ערב ואילך. מאמרי אדה\"א בראשית ע' תקג. ויקרא ח\"ב ע' תקס. דברים ח\"ב ע' עתר ובהנסמן בהנ\"ל."],["573","190","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["574","191","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["575","192","<b>מעשה בא' שהעלה בלבו</b>: סנהדרין עה, א."],["576","193","<b>לרפואות לרפאה</b>: בה: לרפאות(ו)."],["577","194","<b>בבי\"ע</b>: בה: בכנ\"י."],["578","195","<b>ובפשעכם שולחה אמכם</b>: ישעי' נ, א."],["579","196","<b>דאתתא אתרחקת </b>[בה: אתתרכת]<b> מן בעלה</b>: ראה זהר ויגש רי, א. ויקהל רטז, ב."],["580","197","<b>דגלו לאדום שכינה עמהם</b>: ספרי מסעי לה, לד. ראה הנסמן לעיל פ' שמות א, ג הערה 53."],["581","198","<b>הוי'</b>: ב: מ\"ה."],["582","199","<b>סמכוני באשישות רפדוני בתפוחים</b>: שה\"ש ב, ה."],["583","200","<b>הרוחני</b>: בה: המל'."],["584","201","<b>אשישא דעייל חמרא</b>: זהר שמיני מ, א."],["585","202","<b>סודות. . יינה של תו'</b>: ע\"ז לה, א. ראה גם לעיל פ' בא צו, א. וש\"נ."],["586","203","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680053\" data-slug=\"torat-chaim\" data-id=\"2300680053\">תו\"ח ויחי רלו, ב</a>."],["587","204","<b>כמו</b>: בה: דגם."],["588","205","<b>המתוק</b>: שם: הטוב."],["589","206","<b>שבתפוח שמכוון רעותא</b>: זהר שמיני מ, א. ראה גם ביאוה\"ז שם סט, סע\"א ואילך. מאמרי אדה\"ז כתובים ח\"ב ע' קד."]]],[2300550439,"הפנימי [שמלובש במצוה דוקא ש]למעלה נק' רעדכ\"ר<sup data-n=\"590\">207</sup> כו' עד שתתרפא לגמרי מבחי' חולת אהבה זאת, וזהו הנק' ביקור חולים [בכלל למע' שא' הקב\"ה מבקר חולים והוא במה שיסמוך לכנ\"י למע' בחי' מל' באשישות ותפוחי' כנ\"ל וכמ\"ש בזהר משום דבגלותא מתרחקת ביותר ותגדל בה חולת האה' כו' וד\"ל]. ועד\"ז ה' מבקר כו'<sup data-n=\"591\">208</sup> לכל נש\"י בפרטן כנ\"ל, ועד\"ז גומל דלים ועושה צדקה<sup data-n=\"592\">209</sup> כמ\"ש כי צדיק ה' צדקות אהב<sup data-n=\"593\">210</sup> כו' והוא ח\"ס דלי\"ת לבחי' המל' שנק' דל דלית לה מגרמה כלום<sup data-n=\"594\">211</sup> וכמ\"ש [בזהר ע\"פ] אשרי משכיל אל דל<sup data-n=\"595\">212</sup> כו', וכן ענין הצדקה העליונה הוא צדק ה\"א<sup data-n=\"596\">213</sup> [להחיות רוח שפלי'<sup data-n=\"597\">214</sup> ] שהוא ג\"כ להשפיע לבחי' המל' שהוא בחי' ה' תתאה וזהו צדקה צדק ה\"א כידוע. וכן גם התפלה עליונה שה' מתפלל מאי מצלי יהי רצון מלפני שיגולו רחמי על בני כו' דוקא וכמ\"ש במ\"א וד\"ל.\n<b>(וכך</b> יובן עד\"ז ממש בכל המצות העליונות שבבחי' האצי' כמו מצות הקרבנות למעלה שיש מזבח העליון דאצי' בה\"ר<sup data-n=\"598\">215</sup> דאצי' מקריב (נשמות]<sup data-n=\"599\">216</sup> ע\"ג המזבח כו', וכן הוא מקריב מלאכים עליונים שנק' בשם פרים וכבשים כמו בחי' פני שור כו' ועולה לריח ניחוח להוי' ממש כו' (ונשמות<sup data-n=\"600\">217</sup> הוי'<sup data-n=\"601\">218</sup> כמו הקטורת שהוא הריח דבשמים במזבח הפנימי שזהו [ענין] העלא[ה] וקישורא דנשמת[א], וכמו אכלתי יערי עם דבשי<sup data-n=\"602\">219</sup> שהן מלאכים<sup data-n=\"603\">220</sup> שנק' בשם<sup data-n=\"604\">221</sup> יער כמו אז ירננו עצי היער<sup data-n=\"605\">222</sup> ודבשי הן הנשמות<sup data-n=\"606\">223</sup> וכמו אריתי מורי עם בשמי<sup data-n=\"607\">224</sup> כו', כי הרי גם בחי' האצי' <span data-k=\"pg\">שפא</span> ּ נק' עולם האצי' שכלול מד' מדרגות דצח\"מ<sup data-n=\"608\">225</sup> כמו דצח\"מ דבריאה ויצי' ועשי' עד דצח\"מ שבעוה\"ז כו' וא\"כ יש שם ג\"כ כל עניני המצות כמו שנעשים למטה בדצ\"ח שאדם התחתון מקיים כו' וד\"ל. וכמו שיש מצות סוכה וטלית ותפילין [למטה] בסכך גשמי וצמר גשמי וקלף גשמי כך יש ברוחניות דסומ\"ק<sup data-n=\"609\">226</sup> בגוף דלבושי'<sup data-n=\"610\">227</sup> ויצי' [ו]בריאה עד גם בבחי' האצי' באדם העליון דאצי', [ו]יש שם בחי' סכך דסוכה וצמר דטלית כמו לבושי' כו' וגם בחי' הדומם כמו לי הכסף ולי הזהב<sup data-n=\"611\">228</sup> כו', אף<sup data-n=\"612\">229</sup> כל המצות שנעשים בצומח ודומם וחי למטה כתרומות ומעשרות לכהן וקרבנות לכל פרטי דיני[הם] (וגם הלכות טומאה וטהרה כמו [דיני] נגעים",[["590","207","<b>רעדכ\"ר</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a> הערה 23."],["591","208","<b>כו'</b>: בה: חולי."],["592","209","<b>ועושה צדקה</b>: ראה ב\"ר פל\"ג, א. ויק\"ר פכ\"ז, א. סוטה יד, א."],["593","210","<b>כי צדיק ה' צדקות אהב</b>: תהלים יא, ז."],["594","211","<b>המל'. . דלית לה מגרמה כלום</b>: ראה זהר תולדות קלה, סע\"ב. לעיל פ' וארא נה, ג הערה 11."],["595","212","<b>אשרי משכיל אל דל</b>: תהלים מא, ב. ראה גם לעיל הערה 149."],["596","213","<b>הצדקה. . צדק ה\"א</b>: ראה זהר אחרי עב, א. מאמרי אדה\"א שמות ח\"ב ע' שכה. וש\"נ."],["597","214","<b>להחיות רוח שפלי'</b>: ישעי' נז, טו."],["598","215","<b>בה\"ר</b>: בה: שמיכאל כה\"ר. ראה זהר (ס\"ת) לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["599","216","<b>שמיכאל. . מקריב </b>[נשמות]: ראה גם לעיל פ' שמות ה, א. וש\"נ."],["600","217","<b>ונשמות. . הקטורת</b>: ראה גם לעיל פ' שמות ו, ד."],["601","218","<b>הוי'</b>: בה: הוא."],["602","219","<b>אכלתי יערי עם דבשי</b>: שה\"ש ו, ד."],["603","220","<b>מלאכים. . יער</b>: ראה זהר פינחס רכו, סע\"א ואילך. מאמרי אדה\"א ויקרא ח\"א ע' קלח. וש\"נ. הנחות תקע\"ז ע' שלז. וש\"נ."],["604","221","<b>בשם</b>: בה: ליתא."],["605","222","<b>אז ירננו עצי היער</b>: דהי\"א טז, לג. ראה מאמרי אדה\"א דברים ח\"ג ע' א'קיד. שה\"א פה, ב ובהערה 17."],["606","223","<b>ודבשי הן הנשמות</b>: ראה בהדרושים שבהערה 220."],["607","224","<b>אריתי מורי עם בשמי</b>: שה\"ש ה, א."],["608","225","<b>האצי'. . דצח\"מ</b>: ראה ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"י. הנסמן לעיל פ' בשלח קסג, ב."],["609","226","<b>דסומ\"ק</b>: בה: דסכך וצמר וקלף."],["610","227","<b>בגוף דלבושי'</b>: ב: דעשי'. ה: בג\"ע דעשי'."],["611","228","<b>לי הכסף ולי הזהב</b>: חגי ב, ח."],["612","229","<b>אף</b>: ב: וכן. ה: א\"כ יש שם."]]],[2300550454,"ואהלות ואו\"ה במאכלים כו' רק שאין שם בחי' רע כלל והוא בחי' נוגה דאצי' כו'), וכל פרטי דינים המצות דמ\"ע ול\"ת כמו בעולם דבריאה ויצי' כו' עד עולם שלנו. וכמו שלומדי' בג\"ע כל פרטי הדיני' כמו אם קדמ[ה] שער לבן<sup data-n=\"613\">230</sup> [כו'] קוב\"ה אומר טהור כו' עד שהי' אדה\"ר מקיים כל המצות בג\"ע קודם חטא עה\"ד דכתי' לעבדה ולשמרה<sup data-n=\"614\">231</sup> כו' וכמו\"כ הי' עובדא דאבות שקיימו כל המצות ברוחניות כמשי\"ת וד\"ל.\n<b>והנה</b> עד\"ז הן שאר כל המצות העליונות למעלה שנק' מצות[י] דוקא שכולם נעשו למעלה באצי' כדי שעי\"ז נמשך [תו]ס' אורות בכלים מעצמות אור המאציל בבחי' מקיף העליון ביותר עד שכמו שא' באדם התחתון אלה המצות אשר יעשה אותם האדם וחי בהם כך הוא באדם העליון שעל הכסא כו' שחי בהם בחיים האדם העליון מבחי' חיי החיים שהוא מהו\"ע א\"ס ב\"ה בתוס' אור גדול (ועד\"ז נק' חוקות[י] למעלה שהן מצות הנק' חוקים שלמעלה מן הטעם כמו מצות פרה אדומה למעלה הוא בחי' פרה סוררת מל' דנוגה<sup data-n=\"615\">232</sup> שנק' [פרה] פר ה'<sup data-n=\"616\">233</sup> וכל מעשה פרה שחיטתה ושריפתה והזאה כו' ומים חיים בכלי כו' לטהר טמאים הכל בבחי' נוגה דאצי' כו', וכן כלאים ושעטנז כו', וכה\"ג מ\"ש תורתי תורה ש\"מ שבאצי' כמא' ג' שעות יושב ועוסק בתורה כמ\"ש כן דברי אשר יצא מפי<sup data-n=\"617\">234</sup> כו' מפי דוקא [כמא'] יושב ושונה וקורא כנגדו<sup data-n=\"618\">235</sup> כו' ויושב ודן ע\"פ התורה דאצי' כמ\"ש מלך במשפט<sup data-n=\"619\">236</sup> כו' וגם בריאת העולמות אמר בזהר דאסתכל באורייתא וברא עלמא כו' והוא ע\"י קול דתורה שנק' גשם למעלה כמ\"ש קול ה' על המים<sup data-n=\"620\">237</sup> דתורה והוא כמ\"ש כאשר ירד הגשם<sup data-n=\"621\">238</sup> כן דברי כו' ומקיים מצות עסק התורה כמו שמקיים מצות טלית ותפילין כו'). וז\"ש באברהם וישמור משמרתי מצותי כו', דהנה כל אלה המצות שנעשו למעלה באצי' כנ\"ל קיים אברהם ג\"כ, דהיינו שע\"י העובדות שלו למטה במס\"נ עשה כל המצות העליונות ברוחני' כמו שה' עושה בעצמו מאחר שהי' בחי' מרכבה ממש לאדם דאצי', כמו במצות החסד וצדקה שהי' עושה למטה הי' ממשיך בחי' תוס' אור בחסד העליון להיות ח\"ס דלי\"ת לבחי' המל' שנק' דל דלית לה מגרמה כלום וכן צדקה צדק ה\"א כמו מצות חסד וצדקה שה' עושה כנ\"ל. וכן במצות ביקור חולים הנ\"ל כמו לרפאות לבחי' חולת אהבה דכנס\"י בגלותא <span data-k=\"pg\">764</span> ּ כמ\"ש סמכוני באשישות כו' הי' נעשה ג\"כ ע\"י אברהם שהי' ממשיך במל' דאצי' שמסתתר[ת] בנוגה דעשי' בע' שרים<sup data-n=\"622\">239</sup> ואז נק' חולת אהבה כנ\"ל, וע\"י תוס' אורות העליונות מעצמות המאציל באצי' ע\"י אהבה ודביקות ויחו\"ע דאברהם כמ\"ש ויקרא אברם בשם הוי' אל עולם שקרא והמשיך תוס' אור בשם הוי'",[["613","230","<b>אם קדמ[ה] שער לבן</b>: ראה נגעים פ\"ד, מי\"א. הנסמן לעיל פ' שמות ה, א הערה 237."],["614","231","<b>לעבדה ולשמרה</b>: נסמן לקמן רסו, ג."],["615","232","<b>פרה סוררת מל' דנוגה</b>: ע\"פ הושע ד, טז. ראה טעמי המצות — להאריז\"ל — פ' חוקת מצות פרה אדומה."],["616","233","<b>[פרה] פר ה'</b>: ראה גם טעמי המצות שם. מאמרי אדה\"א קונטרסים ע' שצה. וש\"נ."],["617","234","<b>כן דברי אשר יוצא מפי</b>: ישעי' נה, יא [בדילוג]."],["618","235","<b>יושב ושונה וקורא כנגדו</b>: ראה תדא\"ר רפי\"ח. לקמן רסג, ב. לעיל פ' וארא נח, ג הערה 18."],["619","236","<b>מלך במשפט</b>: משלי כט, ד."],["620","237","<b>קול ה' על המים</b>: תהלים כט, ג."],["621","238","<b>כאשר ירד הגשם</b>: ישעי' נה, י [בדילוג]."],["622","239","<b>בע' שרים</b>: נסמן לעיל רנד, ב."]]],[2300550469,"דאצי' ומאצי' לבי\"ע כנ\"ל עי\"ז נמשך רפואה דאשישות ותפוחים לבחי' המל' לסמכה באשישות דפנימי' בינה כו'. וכה\"ג בשאר העובדות דאברהם כמו בחפירת בארות<sup data-n=\"623\">240</sup> הכל הי' גורם עי\"ז לעשות לבחי' המצות העליונות למעלה שנק' בשם מצותי דוקא להיות חי בהם מבחי' חיי החיים כנ\"ל וד\"ל.\n[ז] <b>והנה</b> לפי כל הנ\"ל אע\"פ שאברהם קיים כל התומ\"צ למעלה עד שלא ניתנה לישראל וכן יצחק ויעקב שזהו כללות ענין ס' בראשית שנק' ספר הישר<sup data-n=\"624\">241</sup> שכתב משה בסיפורי מעשה האבות וקורותיהם עד יוסף והשבטי' שכל ספר הזה הוא מקור הכולל לכל המצות שבספרים האחרים וכמ\"ש במ\"א (בפ' לך לך<sup data-n=\"625\">242</sup> ), וע\"כ אמר גבי עובדא של אליעזר יפה שיחתן של עבדי אבות<sup data-n=\"626\">243</sup> יותר מתורתן של בנים (לפי שזהו כל המצות העליונות שביחו\"ע בג' הקוין דאצי' עד יסוד ומל' שהוא יוסף וכל השבטים), עכ\"ז הרי אמר למ[ש]ה וארא אל אברהם כו' ושמי הוי' לא נודעתי להם לפי שלא קיימו המצות בגשמיות ממש כמצות שלנו רק ברוחניות למעלה שנק' מצותי ממש כנ\"ל. והטעם הוא לפי שזה שירד ה' על הר סיני ונתן התומ\"צ לישראל למטה בזה העולם הגשמי לבא במעשה גשמי' זהו חידוש גדול ונפלא ביותר, וזהו כלל גדול דכל שהירידה וההמשכה באה בהתלבשות למטה מטה בהגשמה יותר בהכרח שבא האור הזה ממקום ומדרגה העליונה ביותר שכל הגבוה יותר<sup data-n=\"627\">244</sup> יותר יוכל להשפיל א\"ע (וכמ\"ש במ\"א בענין משלי שלמה<sup data-n=\"628\">245</sup> כו', וע\"כ נק' התורה משל הקדמוני כו'). משא\"כ המצות העליונו' הרוחני' דאבות כנ\"ל שהוא רק להוסיף המשכת האור מעצמות המאציל בכלים דע\"ס דאיהו וחיוהי חד כו' שהן מיוחדים בעצמות בתכלית, א\"כ אין זה חידוש ורבותא כ\"כ להמשיך תוס' אור ואין זה בא ממקום ומדריגה גבוה כ\"כ, הגם שנק' מצותי שיעשה אותם האדם דלעילא וחי בהם כמו הקב\"ה מניח תפילין כו' כנ\"ל הרי נק' רמ\"ח אברים דמלכא ומתאחדים הכלים ג\"כ בעצמות דא\"ס כמ\"ש דאיהו וגרמוהי חד כו' ואין זה חידוש מה שיומשך תוס' אור כמו מקיף דתפילין וציצית למעלה כו'. אבל ירידת האור בהתלבשות גשמיות בהאי עלמא עולם הפירוד ממש ונתלבש בדברים גשמיי' [בטו\"ת שלנו וכה\"ג] ובגופים חומרי' ששרש[ן] בק\"נ דעשי' שאין לה ערך ודמיון כלל למעלת נשמת אברהם בגופו שהי' בחי' מרכבה ממש לחסד דאצי' בתמידות כנ\"ל, א\"כ זהו פלא וחידוש גדול מאד מה שיוכל עצמות אוא\"ס ב\"ה ממש להתצמצם ולירד מטה מטה כ\"כ להיות שם הוי' עצמו ממש מלובש במעשה המצות בדבר גשמי שעושים ישראל למטה שזה ודאי [בא] מעצמות [אא\"ס] שלפני הקו\"ח כו', שלמעלה",[["623","240","<b>דאברהם. . בחפירת בארות</b>: ראה גם לעיל פ' בא קיט, ג ובהערה 228."],["624","241","<b>ס' בראשית שנק' ספר הישר</b>: יהושע י, יג. ע\"ז כה, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' סח. וש\"נ. שמות ח\"ב ע' שנד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670104\" data-slug=\"torat-chaim\" data-id=\"2300670104\">תו\"ח בראשית ח, ב</a> הערה 23."],["625","242","<b>בפ' לך לך</b>: תו\"ח שם פד, סע\"ג ואילך. וראה גם לעיל פ' בשלח קעה, ב."],["626","243","<b>יפה שיחתן של עבדי אבות</b>: ראה ב\"ר פ\"ס, ח."],["627","244","<b>שכל הגבוה יותר</b>: ראה לעיל פ' שמות כא, ב הערה 863."],["628","245","<b>משלי שלמה</b>: ראה לעיל פ' וארא פג, ב ובהערה 733."]]],[2300550484,"ממקור הע\"ס דאצי' ע\"כ לא יוכל לבוא רק למטה בעשי' גשמי' דוקא מה שא\"א שיתלבש למעלה ברוחני' דאצי' מטעם הנ\"ל דכל הגבוה מאד נעלה לא יתלבש כ\"א למטה ביותר (וכמו אור שכל עמוק שלא <span data-k=\"pg\">שפב</span> ּ יוכל לבוא בהרגשה<sup data-n=\"629\">246</sup> כלל כ\"א במשלים כמשלי שלמה וכה\"ג). וכמו ע\"ד דוגמא במעשה [ה]מצות דצדקה וג\"ח גשמיי' בכסף דומם גשמי שנותן לעני להחיותו בגשמיות בזה דוקא מתלבש מבחי' החסד דעצמות א\"ס ב\"ה ממש בחיצוני' הכלים דמל' דעשי' שורש לכסף הדומם כו', אשר לא יוכל לבא בהתלבשות גם באור חסד דאצי' גם לא בחסד דאברהם למעלה שהי' הממשיך תוס' אור בכלי החסד שנק' דרועא ימינא שנק' מצות צדקה למעלה שלא הי' רק בבחי' האצי' ולא מעצמו' א\"ס ממש וז\"ש ושמי הוי' ממש לא נודעתי להם במצות שלהם וד\"ל. וכמו שא' יהי חסדך ה' עלינו<sup data-n=\"630\">247</sup> כו' ע\"י חסד וצדקה שלנו כאשר יחלנו לך בהעלאות מ\"ן דעי\"ז דוקא נמשך חסדך ממש. וכך הוא בשאר המצות כמצות תפילין שלנו בקלף גשמי דוקא מאיר ומתלבש מח\"ע דעצמות א\"ס ממש בפ' קדש כו' להיות בחי' מקיף על המוחין שבאותו ניצוץ קטן [מישראל] המניח תפילין בראש שנא' בו כי שם הוי' נק' עליך ממש כו', ונא' בזה ישראל אשר בך אתפאר בפאר דתפילין העליונים דמארי עלמא דכתיב בהן ומי כעמך ישראל גוי אחד כו' שע\"י התפילין שלנו דוקא מניח תפילין בראשו, וכמו שאו' עוטר ישראל בתפארה<sup data-n=\"631\">248</sup> כו'. וכן בטלית שלנו דוקא עוטה אור כשלמה למעלה כו' וכן כל המצות הרי אנו אומרים אשר קדשנו במצותיו דוקא, ואע\"פ שגם באברהם אמר ששמר משמרתי מצותי חוקותי ותורותי, זהו רק בחי' מצות הרוחני' דאו\"פ<sup data-n=\"632\">249</sup> באצי' לבד ולא למעלה מזה כלל אע\"פ שנמשך תוס' אורות בכלים הכל הוא מבחי' הקו\"ח ע\"פ מאמר קו המדה לבד (כמ\"ש בפ' לך לך<sup data-n=\"633\">250</sup> ). משא\"כ במצות שלנו שאנו אומרים אשר קדשנו במצותיו ג\"כ, אבל הן מצות שבעצמות א\"ס שלמעלה מצמצום דקו\"ח כמ\"ש רחבה מצותך מאד ממש, וכמו מצות ציצית דלבושי' כתלג חיור כו' שמקיף דלבוש זה הוא מעצמות א\"ס ממש וכן בחי' התפילין דמארי עלמא וכה\"ג, לפי שנעשו ממצות שלנו מבירורי' דרפ\"ח כו' שמזה יהי' העוה\"ב דוקא שהוא בחי' גילוי אור העצמות דא\"ס ממש, וכמאמר כל ישראל יש להם כו' שנא' ועמך כולם צדיקי'<sup data-n=\"634\">251</sup> במצות כו', א\"כ הרי ראי' ברורה מזה עכ\"פ ששרש המצות הגשמיות שלנו בעצמות הא\"ס ממש שאין למצות הרוחני' דאבות מגיע לשם כלל, וז\"ש ושמי הוי' לא נודעתי להם. וזהו עיקר ענין קבלת התו' שאמר וירד הוי' על ה\"ס שהי' ירידה גדולה ועצומה וירידה זו לצורך עלי' הוא שאין למעלה",[["629","246","<b>בהרגשה</b>: בה: בהשגה."],["630","247","<b>יהי חסדך ה' עלינו</b>: תהלים לג, כב."],["631","248","<b>עוטר ישראל בתפארה</b>: ראה גם לעיל עד, ג. וש\"נ."],["632","249","<b>דאו\"פ</b>: בה: דאו\"כ."],["633","250","<b>בפ' לך לך</b>: תו\"ח שם פג, ד ואילך."],["634","251","<b>ועמך כולם צדיקי'</b>: ישעי' ס, כא."]]],[2300550499,"ממנו שהוא העוה\"ב כמ\"ש אשר אהי' אנא זמין לאתגלאה<sup data-n=\"635\">252</sup> בעוה\"ב שהוא שכר המצות הגשמיות דוקא שנק' עדן דעין לא ראתה<sup data-n=\"636\">253</sup> כו' כידוע וד\"ל.\n[ח] <b>וזהו</b> שאמר רב יוסף דהאי יומא דקא גרים שהי' עת וזמן דבחי' הירידה הגדולה שירד ה' למטה להתלבש בתו\"מ שלנו שהי' דבר חידוש גדול ונפלא ביותר שיוכלו נשמות בגופי' לקבל אור עצמות א\"ס ב\"ה כמו שהוא ממש בהיותו מתלבש בתו\"מ שבאו בדברים גשמיי' כו' (ואמנם יש בזה הפרש בין התורה למצות שמ\"ת הי' עיקר לת\"ח<sup data-n=\"637\">254</sup> דוקא שמקבלים מח\"ע, וא\"כ אי לאו האי יומא כמה יוסף איכא בשוקא כו', אבל המצות הכל שוין בהם כמו בעוה\"ב דכל ישראל יש להם כו' להיותו למעלה מן החכ' וטעם לרצון כו'). אך הנה זה גופא י\"ל איך אפשר שיהי' דילוג כזה בשעת מ\"ת (וכנ\"ל דהיינו כמו לעוה\"ב ) שהרי א' ביום חתונתו זה מ\"ת<sup data-n=\"638\">256</sup> וביום שמחת לבו זה בנין בהמ\"ק דלע\"ל<sup data-n=\"639\">255</sup>. אמנם יש <span data-k=\"pg\">766</span> ּ להקדים ענין א' הידוע והוא במ\"ש כי אל דעות ה'<sup data-n=\"640\">257</sup> ולו ולא קרי וכתיב<sup data-n=\"641\">258</sup> נתכנו עלילות שיש ב' דעות דעת עליון ודעת תחתון, בחי' דעת עליון הוא מלמעלה למטה שנק' יחו\"ע בכלל שזהו מיש לאין שהארת אור בהשתלשלות בא<sup data-n=\"642\">259</sup> וכאין חשוב לגבי עצמות המאור ולכך נק' מיש לאין שזהו מיש האמיתי לאין ובחי' אין זה היינו דכלא וכאין חשיב (וא\"כ למעלה הוא בחי' יש ולמטה הוא בחי' אין ובעוה\"ב אמר להנחיל אוהבי יש<sup data-n=\"643\">260</sup> היינו בחי' יש האמיתי שהוא ענין גילוי אור העצמות ממש וכמ\"ש הנה אלקינו זה<sup data-n=\"644\">261</sup> כו'). ודיעה הב' כמו שהוא מלמטה למעלה (כמו בחי' יחו\"ת) שזהו אור השפע האלקי' שבורא מאין ליש שהארת אור האלקי נק' אין בבחי' אין והעלם והתהוות הבריאה נק' יש גמור כו'<sup data-n=\"645\">262</sup> שהולך ונמצא<sup data-n=\"646\">263</sup> למטה מטה יותר נעשה בבחי' יש מוגבל יותר, ונמצא נהפוך הוא מד\"ע הנ\"ל דלמטה הוא בחי' יש ולמעלה הוא בחי' אין (ודרך כלל ג' מדרגות הן שהן ד'<sup data-n=\"647\">264</sup> מיש האמיתי לאין בחי' ד\"ע הנ\"ל, ואח\"כ מאין ליש ע\"י צמצום דשם אלקים שהוא בחי' יחו\"ת<sup data-n=\"648\">265</sup> כידוע). וכ\"ז מצד ההשתלשלו' עכ\"פ דכמו שקמי' כלא חשיב זהו מיש לאין, וכמו שנמשך בעולמות נק' מאין ליש שהן ב' דעות הפכים ממש כנ\"ל, אבל בעצמות א\"ס ממש כמו שהוא למעלה גם מבחי' מקור למקור להשתל' ב' דעות הללו שוין לפניו ממש. והיינו שאמר כי אל דעות שם אל סובל ב' דעות דד\"ע וד\"ת כא' משום דלגבי העצמות ממש שוין מלמעלה למטה עם מלמטה למעלה מאחר שנבדל לגמרי מבחי' אור ושפע עד שנמצא בשוה למטה כמו למעלה ממש (וכמו שהי' הוא ושמו בלבד<sup data-n=\"649\">266</sup> קודם הצמצום",[["635","252","<b>אשר אהי' אנא זמין לאתגלאה</b>: שמות ג, יד. ראה זהר ויקרא יא, א. אחרי סה, ב."],["636","253","<b>עדן דעין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["637","254","<b>שמ\"ת הי' עיקר לת\"ח</b>: ראה גם לקמן רסג, א. מאמרי אדה\"ז תקס\"ו כאן (ע' רט)."],["638","256","<b>ביום חתונתו זה מ\"ת</b>: שה\"ש ג, יא. ראה תענית כו, ב (במשנה). מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["639","255","<b>לעוה\"ב). . דלע\"ל</b>: ב: לעוה\"ב. . דלע\"ל)."],["640","257","<b>כי אל דעות ה'</b>: שמו\"א ב, ג. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a> ובהערה 11."],["641","258","<b>ולו ולא קרי וכתיב</b>: ראה זהר (אד\"ז) האזינו רצב, סע\"ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670476\" data-slug=\"torat-chaim\" data-id=\"2300670476\">תו\"ח לך פח, ד</a> ובהערה 25. לעיל פ' בשלח קפט, ג. וש\"נ."],["642","259","<b>בא</b>: בה: כלא."],["643","260","<b>להנחיל אוהבי יש</b>: משלי ח, כא. ראה גם לעיל קלח, ד. וש\"נ."],["644","261","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["645","262","<b>כו'</b>: בה: וכל."],["646","263","<b>ונמצא</b>: שם: ונמשך."],["647","264","<b>ג' מדרגות הן שהן ד'</b>: ראה לעיל קפו, ד."],["648","265","<b>אלקים. . יחו\"ת</b>: ראה גם ביאוה\"ז קדושים קלט, ד. מאמרי אדה\"ז תקס\"ה ח\"א ע' תעב. תקס\"ח ח\"א ע' קלז. ש\"א לו, א. אמ\"ב שער הק\"ש כז, ב."],["649","266","<b>שהי' הוא ושמו בלבד</b>: ראה פדר\"א פ\"ג. לעיל פ' וארא נג, ב. וש\"נ."]]],[2300550513,"הראשון כמ\"ש בע\"ח שהי' ממלא כל החלל<sup data-n=\"650\">267</sup> כו'), וכמו שיהי' בעוה\"ב שנא' בו להנחיל אוהבי יש [דהיינו יש] האמיתי כמו שהוא במהו\"ע יהי' גם למטה כו' כנ\"ל, וא\"כ כמו דקמי' כלא חשיב ממש כך גם באור הנמשך בעולמות מאין ליש ג\"כ כלא ממש חשיבי ואינו נק' בבחי' יש כלל (ולכך אמר אתה הוא<sup data-n=\"651\">268</sup> כו') וזהו ביום ההוא יהי'<sup data-n=\"652\">269</sup> ה' אחד ושמו אחד יחו\"ע ויחו\"ת שניהם שוים ממש למהוי אחד באחד מטעם הנ\"ל. וז\"ש ולא נתכנו ולו קרי וכתיב דלא באל\"ף היינו מצד העדר תפיסת מקום לגמרי כמו שהוא לגמרי<sup data-n=\"653\">270</sup> בבחי' ד\"ע דקמי' כלא כו', ולו בוי\"ו היינו כמו שנמשך מאין ליש שנק' יש והם בביטול היש לאין או בפירוד כו', ואמנם שניהם שוים ממש כמ\"ש אם צדקת<sup data-n=\"654\">271</sup> כו' דגם בבחי' יחו\"ת כל\"ח כמו מלמעלה למטה א\"כ לא ולו שוין, וכמאמר איהו תפיס בכולהו עלמין<sup data-n=\"655\">272</sup> ולית מח' דתפיס בי'<sup data-n=\"656\">273</sup> כלל א\"כ זהו דבר והיפוכו דגם בשעה שנתפס בכ\"ע למחת\"ב<sup data-n=\"657\">274</sup> כו', וכן אמר הוא מקומו של עולם<sup data-n=\"658\">275</sup> ואין העולם מקומו שניהם כא' ממש משום שסובל ב' הדיעות יחד מטעם הנ\"ל לפי שנמצא למטה כמו למעלה ממש כו' וכמ\"ש המגביהי לשבת כמו דקמי' כלא ממש ואז דוקא ישפיל לראות<sup data-n=\"659\">276</sup> כנ\"ל<sup data-n=\"660\">277</sup> וד\"ל.\n[ט] <b>וזהו</b> ענין ולא ולו דשניהם אמת, והיינו ענין ד' אותיות דשם הוי' י\"ה בשס\"ה ל\"ת שזהו ולא באלף ו\"ה ברמ\"ח מ\"ע שהוא ולו בוי\"ו היינו יחו\"ע ויחו\"ת בכלל כמ\"ש שמי עם י\"ה<sup data-n=\"661\">278</sup> כו' ולגבי עצמותו שניהם שוים ממש מטעם הנ\"ל וד\"ל (וכמ\"ש במ\"א עמ\"ש כי הוא עשנו<sup data-n=\"662\">279</sup> ולו אנחנו ולא אנחנו קרי וכתיב<sup data-n=\"663\">280</sup> דשניהם שוין ממש באמת<sup data-n=\"664\">281</sup> מטעם הנ\"ל), והיינו ג\"כ ענין התו\"מ בל\"ת ומ\"ע שמקיימי' כנס\"י דשניהם ניתנו<sup data-n=\"665\">282</sup> יחד לפי שסובל ב' הדיעות כא', והוא בעוה\"ב שיתגלו ב' הדעות כאחד ממש משום <span data-k=\"pg\">שפג</span> ּ שיתגלה אור העצמות דוקא שז\"ש להנחיל אוהבי יש האמיתי (כמשי\"ת). ואמנם הנה זה גופא מה שיסבול ב' הדעות דיחו\"ע ויחו\"ת כא' כנ\"ל הוא ע\"י תו' וקיום<sup data-n=\"666\">283</sup> המצות דוקא לפי שע\"י התומ\"צ נק' כנס\"י בשם אדם אדמה לעליון<sup data-n=\"667\">284</sup> ממש והוא מ\"ש אדם אתם קרוים אדם<sup data-n=\"668\">285</sup> בצלם אלקי' ממש",[["650","267","<b>שהי' ממלא כל החלל</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב. לקמן פ' משפטים חצר, ב. תצוה שסז, ד. ויקהל שפח, ד. סידור שער בהמ\"ז קט, ב. שעה\"י קיד, א הערה 17. ש\"א עט, ב."],["651","268","<b>אתה הוא</b>: תפלת השחר."],["652","269","<b>ביום ההוא יהי'</b>: זכרי' יד, ט. ראה מאמרי אדה\"א בראשית ע' תקלז. וש\"נ. נ\"ך ע' קנב. וש\"נ. לקמן רסד, ג ואילך. פ' תצוה שנא, ג."],["653","270","<b>לגמרי</b>: בה: ליתא."],["654","271","<b>אם צדקת</b>: איוב לה, ז."],["655","272","<b>איהו תפיס בכולהו עלמין</b>: ראה זהר (רע\"מ) פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670220\" data-slug=\"torat-chaim\" data-id=\"2300670220\">תו\"ח נח סו, ג</a> בהערה 30."],["656","273","<b>ולית מח' דתפיס בי'</b>: ראה ת\"ז בהקדמה (יז, א). ב: ולמת\"ב. ה: ולית מאן דתפיס בי'. וראה הערה הבאה."],["657","274","<b>למחת\"ב</b>: ב: למת\"ב. ה: לית מאן דתפיס בי'. ראה הערה שלפנ\"ז."],["658","275","<b>הוא מקומו של עולם</b>: ראה ב\"ר פס\"ח, ט. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a> הערה 2."],["659","276","<b>המגביהי לשבת. . ישפיל </b>[בה: (ה)משפילי]<b> לראות</b>: תהלים קיג, ה. ו."],["660","277","<b>כנ\"ל</b>: ב: כו'. ה: ליתא."],["661","278","<b>י\"ה בשס\"ה ל\"ת. . ו\"ה ברמ\"ח מ\"ע. . שמי עם י\"ה</b>: נסמן לעיל רנב, א."],["662","279","<b>כי הוא עשנו</b>: תהלים ק, ג [בדילוג]."],["663","280","<b>ולו אנחנו. . קרי וכתיב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670467\" data-slug=\"torat-chaim\" data-id=\"2300670467\">תו\"ח לך פח, ג</a> ואילך."],["664","281","<b>שוין ממש באמת</b>: בה: אמת."],["665","282","<b>ניתנו</b>: ב: נתכנו. ה: ליתא."],["666","283","<b>תו' וקיום</b>: שם: קיום."],["667","284","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבודת הקדש ח\"א פי\"ז ואילך. הנסמן במאמרי אדה\"א בראשית ע' תקסב. דברים ח\"א ע' קכב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a>."],["668","285","<b>אדם אתם </b>[ה ניתוסף: אתם]<b> קרוים אדם</b>: יחזקאל לד, לא. יבמות סא, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670578\" data-slug=\"torat-chaim\" data-id=\"2300670578\">תו\"ח נח עה, ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תרנג. דברים ח\"ד ע' א'רז. הנחות תקע\"ז ע' שז. לקמן פ' תרומה שיד, ב."]]],[2300550527,"כמ\"ש נעשה אדם בצלמנו כדמותנו<sup data-n=\"669\">286</sup> כו', ואין נק' אדם בצלם האלקי' ודמותו ממש רק ע\"י התו\"מ שהוא עיקר פנימי' אדם וכמ\"ש וזאת תורת האדם<sup data-n=\"670\">287</sup>, וכן אלה המצות אשר יעשה [אותם] האדם דוקא דמה שנק' אדם ברמ\"ח אברים כו' זהו רק בחי' אדם חיצוני, אבל ע\"י התו\"מ נמשך מפנימי' אדם שזהו אדמה לעליון ממש שהוא עצמות א\"ס כמו<sup data-n=\"671\">288</sup> שיתגלה בעוה\"ב. והוא מטעם שע\"י קיום התו\"מ למטה הקב\"ה מקיים כל המצות למעלה כמו שהן בעצמות א\"ס ממש כנ\"ל, ולזה ע\"י קיום התו\"מ למטה נק' אדם בצלמו ודמותו ממש ([ו]כמ\"ש במ\"א ע\"פ הראיני את מראיך<sup data-n=\"672\">289</sup> כו' דמראה ודמות הזה הוא בחי' מקיפים דמעשה המצות כו').\n<b>אך</b> הנה מש\"א בצלמנו כדמותנו דוקא ב' מדרגות צלם ודמות כו', הענין הוא שיהי' גם אצלינו למטה גילוי עצמות א\"ס ממש שהוא ענין ב' הדיעות הנ\"ל יהיו שוין אצלינו למטה ממש כמו שהן בהשוואה אחת למעלה ממש, דהיינו<sup data-n=\"673\">290</sup> מ\"ש לעתיד ומלאה הארץ דעה<sup data-n=\"674\">291</sup> את הוי' זהו רק בחי' ד\"ע שהוא מיש האמיתי לאין שיתגלה ג\"כ<sup data-n=\"675\">292</sup> בבחי' ד\"ת שהוא מאין ליש, וע\"כ כולם ידעו אותי בשוה מקטנם כו' ולא ילמדו<sup data-n=\"676\">293</sup> כו' דענין הלימוד הוא בגילוי שם הוי' לבד כמ\"ש וכל בנייך לימודי הוי'<sup data-n=\"677\">294</sup> כו' בחי' סוכ\"ע<sup data-n=\"678\">295</sup> יחו\"ע כמו\"כ<sup data-n=\"679\">296</sup> יחו\"ת למהוי אחד באחד ממש, ובימוהמ\"ש נאמר ונגלה כבוד הוי'<sup data-n=\"680\">297</sup> וראו כל בשר כו' וכמ\"ש והי' אור הלבנה כאור החמה<sup data-n=\"681\">298</sup> כו'. אבל בעוה\"ב הוא למעלה גם מזה והוא שיתגלה אור העצמיות ממש דיחו\"ע ויחו\"ת שוין ממש וכמ\"ש ולא יהי' לך השמש<sup data-n=\"682\">299</sup> כו' ה' עצמו יהי' לך לאור עולם וכמ\"ש יקימנו ונחי' לפניו<sup data-n=\"683\">300</sup> ממש וכמו שבמהו\"ע הוא יחיד לבד[ו] ממש כך יהי' למטה ממש אין עוד מלבדו<sup data-n=\"684\">301</sup>, ע\"כ ב' הדעות שוין ממש. וז\"ש להנחיל אוהבי יש האמיתי (שזהו מיש ליש האמיתי לאור<sup data-n=\"685\">302</sup> בכנ\"י בבחי' יש כמו שהוא במהו\"ע ולא מיש לאין, וזהו ענין ת' עלמין דכסופין<sup data-n=\"686\">303</sup> כו' מעצמות השעשועים ממש שעונג הנעלם בעצמותו ממש יבא במורגש<sup data-n=\"687\">304</sup> בנשמות הצדיקים כמ\"ש במ\"א וזהו שנק' ארץ חפץ<sup data-n=\"688\">305</sup> כו', וז\"ש",[["669","286","<b>נעשה אדם בצלמנו כדמותנו</b>: בראשית א, כו."],["670","287","<b>וזאת תורת האדם</b>: שמו\"ב ז, יט."],["671","288","<b>כמו</b>: בה: ליתא."],["672","289","<b>הראיני את מראיך</b>: שה\"ש ב, יד. ראה מאמרי אדה\"ז תקס\"ט ע' קט."],["673","290","<b>דהיינו</b>: בה: דהנה."],["674","291","<b>ומלאה הארץ דעה</b>: ישעי' יא, ט [ושם: כי מלאה — נסמן לעיל פ' בשלח קס, ד]."],["675","292","<b>ג\"כ</b>: בה: גם."],["676","293","<b>כולם ידעו אותי. . מקטנם. . ולא ילמדו</b>: ירמי' לא, לג [בהיפך הסדר. ושם למקטנם — ראה הנסמן לעיל פ' שמות לח, ג]."],["677","294","<b>וכל בנייך לימודי הוי'</b>: ישעי' נד, יג."],["678","295","<b>הוי'. . סוכ\"ע</b>: ראה גם לעיל פ' וארא עג, ב. וש\"נ."],["679","296","<b>כמו\"כ</b>: ב: במכ\"ע."],["680","297","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["681","298","<b>והי' אור הלבנה כאור החמה</b>: ישעי' ל, כו."],["682","299","<b>ולא יהי' לך השמש</b>: ישעי' ס, יט [ושם לא (וכ\"ה בבה). בדילוג — ראה לקמן פ' ויקהל תג, ב. תו\"ח ויצא קסח, א ובהערה 2. ש\"א לג, ב]."],["683","300","<b>יקימנו ונחי' לפניו</b>: הושע ו, ב."],["684","301","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["685","302","<b>לאור</b>: בה: יאיר."],["686","303","<b>ת' עלמין דכסופין</b>: ראה גם לעיל פ' שמות כה, ד. וש\"נ."],["687","304","<b>שעונג הנעלם. . יבא במורגש</b>: ראה גם אמ\"ב שער הק\"ש יז, ד."],["688","305","<b>ארץ חפץ</b>: מלאכי ג, יב."]]],[2300550540,"איהו אמת ואיהי אמונה<sup data-n=\"689\">306</sup> שיוכלו לקבל האור העצמי' כמו שהוא באמיתתו ממש כמ\"ש ורעה אמונה<sup data-n=\"690\">307</sup> כמ\"ש במ\"א. וזהו רק ע\"י המצות מעשיות בפו\"מ דוקא עכשיו שנמשך עי\"ז מעצמות א\"ס ממש בעוה\"ב להיות נמצא למטה כמו למעלה ממש כנ\"ל, וע\"ז הוא שאמר נעשה אדם בצלמינו כו' אדם אדמה לעליון ממש והוא המשכ' האורו' דעצמו' ממש להיותו בכלים למטה כמו למעלה. וזהו שנק' דמות כידוע בענין מראה ודמות כבוד ה'<sup data-n=\"691\">308</sup> שהתואר בעצם נק' צלם והציור בכלים נק' דמות והן מעשה המצות בכלל שכמו שהן בעצמו' ממש הן בבחי' א\"ס ממש נק' צלם וכשבאים בכלים ברמ\"ח אברים נק' דמות, ע\"ד דוגמא כאשר עושי' מצות צדקה ביד נק' דמות ואור רצה\"ע שבמצות צדקה למעלה כמו שהוא בעצמות ממש שהוא חסד וצדקה דא\"ס עצמו ממש, וכן במצות טו\"ת נק' דמות וציור לטו\"ת שלמעלה להיות עי\"ז למטה כמו למעלה ממש דהיינו שאין העולמות תופסים מקום כלל וכלל לגבי העצמיות ממש, וע\"כ הוא למטה כמו שהוא למעלה כך יהי' עי\"ז<sup data-n=\"692\">309</sup> המצות. וכמו במצות ת\"ת <span data-k=\"pg\">768</span> ּ שמדבר דבר ה' ממש כמו שהוא באמיתית א\"ס עצמו שאין כל ההשתל' דאבי\"ע תופסים מקום כלל לפניו, כך יהי' בדבר ה' זה שאדם לומד שלא יהי' כל ההשתל' תופסים מקום כלל ויהי' לימוד זה בדוגמא לדבר ה' כמו שהוא בתורה הקדומה שבעצמות ממש שאין תופס מקום לנגדו ונמצא למטה כמו למעלה ממש [מטעם] שב' דיעות שוין ממש כנ\"ל, אז בלימוד כזה או במעשה המצות ע[ד]\"ז נק' אדם אדמה לעליון ממש. והוא עיקר ענין העוה\"ב שהוא שכר המצות דעכשיו ושכר מצוה מצוה<sup data-n=\"693\">310</sup> עצמה דוקא רק שעכשיו אור העצמו' ממש הוא בהעלם בתו\"מ שלנו וד\"ל, ומעין העוה\"ב הי' גילוי כזה במ\"ת בי' הדברות (כמשי\"ת).\n<b>והנה</b> ידוע שהתו\"מ שלמטה נק' התורה מזון לנשמות והמצות נק' לבושי'<sup data-n=\"694\">311</sup> שהוא בחי' מקיפי' כו' וע\"י אמצעות שניהם יהי' ג\"כ לע\"ל בהגלות נגלות אור העצמות דא\"ס ממש בתו\"מ שלנו כנ\"ל למטה כמו למעלה ממש יהי' נמשך ע\"י התו' מבחי' או\"פ שבעצמות ממש והוא בחי' התענוג הנעלם שבעצמות שיבא במורגש בגילוי סודות התורה למזון לנשמות כו', וע\"י המצות שיתגלו לע\"ל יהי' המשכת בחי' המקיפים שבעצמות א\"ס ממש להיות בבחי' לבוש מבהיק לנשמות כמ\"ש והלך לפניך צדקיך<sup data-n=\"695\">312</sup> כו' וכתיב אז יבקע כשחר אורך<sup data-n=\"696\">313</sup> כו' והשביע בצחצחות נפשך<sup data-n=\"697\">314</sup> באור תורה הקדומה ועצמותיך יחליץ במקיפי' דמצות כמו",[["689","306","<b>איהו אמת ואיהי אמונה</b>: ראה זהר בלק קצח, ב. מאמרי אדה\"א ויקרא ח\"א ס\"ע צג ואילך. לעיל פ' שמות יז, ב."],["690","307","<b>ורעה אמונה</b>: תהלים לז, ג. ראה גם לעיל פ' בא צב, א. וש\"נ."],["691","308","<b>מראה ודמות </b>[בה: דמות]<b> כבוד ה'</b>: יחזקאל א, כח."],["692","309","<b>עי\"ז</b>: בה: ע\"י."],["693","310","<b>ושכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא</a> רפל\"ט. הנסמן לעיל פ' שמות ז, ב."],["694","311","<b>התורה מזון. . והמצות נק' לבושי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>."],["695","312","<b>והלך לפניך צדקיך</b>: ישעי' נח, ח."],["696","313","<b>אז יבקע כשחר אורך</b>: התחלת הכתוב והלך לפניך."],["697","314","<b>והשביע בצחצחות נפשך</b>: ישעי' שם, יא."]]],[2300550553,"שידוע דאו\"פ מזכך חצי הכלי מבפנים<sup data-n=\"698\">315</sup> ואו\"מ מזכך חצי הכלי מבחוץ, וכך יהי' לע\"ל שיזדככו הנשמות מבפנים ובחוץ מאו\"פ ומקיף דתו\"מ העליונים ממש וד\"ל. ודוגמא לזה הוא מ\"ש כי הוי' אלקיך אש אוכלה הוא<sup data-n=\"699\">316</sup> כו', פי' הוי' אלקיך הוא היינו תו\"מ דמצות הן בחי' כלים כמ\"ש נר מצוה ותו\"א<sup data-n=\"700\">317</sup>. וידוע דהתו' ניתנה באש כמ\"ש מימינו אש<sup data-n=\"701\">318</sup> כו' אש שחורה ע\"ג אש לבנה<sup data-n=\"702\">319</sup> וכמו עד\"מ אש הניתן בכלי לצרפו ולזככו מבפנים וגם אש מבחוץ החופף עליה לצרפה מבחוץ, כך אור דתורה מזכך הגוף לצרפו וללבנו מחומריות וגסות ונשרף וכלה כל אש הזר שבו והמצות<sup data-n=\"703\">320</sup> שנק' נר מזכך ומצרף מבחוץ שהן לבוש מקיף מבחוץ עד שיהי' גם הגוף כלי טהור להכיל אור האלקי כמו הנשמה ולא תסת[י]ר כלל (וכמ\"ש ועצמותיך יחליץ כו'), וזהו לפי שה' אלקיך שבתו\"מ אש אוכלה הוא לברר ולשרוף לכל אש זר דק\"נ כו' (וע\"כ אמרו דת\"ח אין אור של גיהנם שהוא אש זר דק\"נ שולט בהם<sup data-n=\"704\">321</sup> כלל מפני אור ואש דתו\"מ שבירר לגופם בחייהם כו'). וכך הי' במ\"ת שעל כל דבור<sup data-n=\"705\">322</sup> כו' שזהו בחי' אש דתורה כמ\"ש קול ה' חוצב להבות<sup data-n=\"706\">323</sup> כו' שיזכך לנשמתם מבפנים ומבחוץ עד שפסקה מהן זוהמא של נחה\"ק<sup data-n=\"707\">324</sup> לגמרי כידוע וד\"ל.\n[יו\"ד] <b>והנה</b> אחר הקדמה זו יובן כללות ענין מ\"ת בטעם שרש ענין הירידה הגדולה שהי' בנתינת התורה למטה כמ\"ש וירד ה' על ה\"ס כו' דהיינו שנתגלה מבחי' אור העצמו' דא\"ס ממש דקמי' ממש שוין ב' הדיעות כנ\"ל, ויכול אור א\"ס לבא בהתגלות למטה כמו שהוא למעלה בעצמות[ו] ממש, וזה הי' כל עיקר בחי' ירידה זו במ\"ת שזהו שניתנה התו\"מ למטה גם בעולם הפירוד הזה כמו שהוא למעלה [ממש] בלי שינוי כלל מטעם הנ\"ל. וזהו הנק' מתנה שניתנה התורה לישראל כמו שנותן המשפיע לידי המקבל שאין שינוי כלל בעצם הדבר הניתן רק שירד לרשות המקבל, ואע\"פ שהופרדה יד<sup data-n=\"708\">325</sup> הנותן אין זה פירוד בעצם הדבר שהוא התו\"מ שישראל עושי' למטה כמו שהוא ממש התו\"מ שבעצמות ממש, וראי' לזה ממה שאו' אשר קדשנו במצותיו ממש כנ\"ל, ובלי גבול ומדה כלל כמו שהוא למעלה &lt;שפד&gt; ּ ממש כמ\"ש רחבה מצותך מאד, ועל התורה הקדומה אמר ארוכה מארץ מדה<sup data-n=\"709\">326</sup> כו' אע\"פ שנתלבשה למטה בגבולים ושיעורים (וכמ\"ש במ\"א בענין יהונתן ודוד<sup data-n=\"710\">327</sup> כו'). וראי' עוד שאין שינוי כלל בתו' שניתנה במתנה ממה שאנו מוצאים דגם שמשה קיבל תורה מסיני<sup data-n=\"711\">328</sup> ומסרה ליהושע ויהושע לזקנים וזקנים לנביאים כו' עד דורות התנאים ואמוראים כו' עד שגם",[["698","315","<b>דאו\"פ מזכך חצי הכלי מבפנים</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב. (שער השתלשלות הי\"ס) ש\"ב, ענף ג. לקמן פ' פקודי תמט, ד."],["699","316","<b>כי הוי' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד."],["700","317","<b>נר מצוה ותו\"א</b>: משלי ו, כג."],["701","318","<b>מימינו אש</b>: ברכה לג, ב."],["702","319","<b>אש שחורה ע\"ג אש לבנה</b>: ראה רש\"י שה\"ש ה, טז [ד\"ה שחורות]. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["703","320","<b>שבו והמצות</b>: תוקן ע\"פ בה. ובתו\"ח כאן: שהן המצות."],["704","321","<b>דת\"ח אין אור של גיהנם. . שולט בהם</b>: נסמן לעיל רנד, א."],["705","322","<b>שעל כל דבור</b>: שבת פח, ב."],["706","323","<b>קול ה' חוצב להבות</b>: תהלים כט, ז."],["707","324","<b>שפסקה מהן זוהמא של נחה\"ק</b>: ראה שבת קמו, רע\"א."],["708","325","<b>יד</b>: ב: מיד. ה: מכח."],["709","326","<b>ארוכה מארץ מדה</b>: איוב יא, ט. ראה גם לעיל פ' בשלח קעג, ב. וש\"נ."],["710","327","<b>בענין יהונתן ודוד</b>: ראה מאמרי אדה\"א במדבר ח\"א ע' קמח ואילך."],["711","328","<b>שמשה קיבל תורה מסיני</b>: אבות רפ\"א."]]],[2300550566,"תלמיד ותיק שעתיד לחדש<sup data-n=\"712\">329</sup> הכל ניתן למשה כענין משה שפיר קאמרת<sup data-n=\"713\">330</sup> כי<sup data-n=\"714\">331</sup> הרי דבר ה' שבהלכה זו שחידש התלמיד הוא שקיבל משה מפי ה' ממש בלי שינוי כלל בכל ריבוי השתלשלו' כזה והוא מטעם הנ\"ל. וזהו עיקר ענין מ\"ת שניתנה לישראל דוקא ולא לאומות העולם שיהא בהם כח זה דשרש התו\"מ ע\"י עסק שלהם בתו\"מ כל הימים ולכך אומרים בשבועות זמן מתן תורתינו (ומה שמברכים בכל יום נותן התורה<sup data-n=\"715\">332</sup> שבכל יום מתחדש מ\"ת, והעיקר הוא בשבועות מפני שאז הי' הירידה הגדולה הנ\"ל שמטעם זה נית[נה] התורה למטה כמו למעלה ממש כנ\"ל<sup data-n=\"716\">333</sup>. וזהו שא' רב יוסף אי לאו האי יומא דקא גרים שביום זה דוקא הי' ירידת ה' על הר סיני כנ\"ל שניתנה התורה במתנה לכאו\"א מישראל שיוכל להמשיך גילוי עצמות א\"ס בתו\"מ שלו למטה כמו שהוא למעלה ממש כנ\"ל<sup data-n=\"717\">334</sup> מטעם הנ\"ל, כמה יוסף איכא בשוקא (משום דבמ\"ת עצמה יש הבדל בין ת\"ח לשאר אנשים הפשוטים מטעם הנ\"ל במש\"א דמשה קיבל תורה מסיני כו' עד שגם תלמיד כו' הכל נית[נה] למשה שבקבלה זו אין שינוי כלל בין תלמיד האחרון שחידש דבר הלכה שהוא דבר ה' שקיבל משה ממש, ע\"כ אי לאו האי יומא כמה יוסף איכא בשוקא כו' משום דבהאי יומא נתקבל התורה לכל ת\"ח שבדורות הבאים שבזה מובדלים משאר אנשים אע\"פ שאו' זמן מתן תורתינו לכל ישראל זהו שמקבלים ע\"י ת\"ח ומטעם הנ\"ל וד\"ל).\n[יא] <b>וזהו</b> משה ידבר והאלקים יעננו בקול, פי' משה ידבר וימשיך בתמידות אור עצמות א\"ס ממש [שבתו\"מ] גם למטה בעולם הפירוד כמו שהוא למעלה ממש כמ\"ש למעלה בענין ב' דעות הנ\"ל, שגם מלמטה למעלה אין העולמות תופסים מקום כלל לגבי גילוי אור פנימי' העצמו' שבתו\"מ העליוני' כמו שהוא מלמעלה למטה ממש. וזהו ע\"י בחי' מדריגת משה דוקא שלא הי' יכול להיות גם ע\"י האבות כי גם שאברהם קיים כל התו\"מ כמו שהוא למעלה בבחי' הרוחניות דאצי', אבל לא הוריד והמשיך אותם למטה גם בעולם הנפרד שיתלבשו בדברים גשמיי' וע\"כ א' ושמי הוי' לא נודעתי להם, לפי שמעלת ומדריגת נשמת משה הי' מלמעלה יותר ממדרגת נשמת אברהם וכמ\"ש בו כי טוב הוא בטי\"ת רבתי<sup data-n=\"718\">335</sup> שהוא מבחי' עה\"ח ממש שז\"ש בו מן המים משיתיהו מבחי' מ\"ע<sup data-n=\"719\">336</sup> שלפני ההשתל' דאבי\"ע (והוא הים הקדמוני שנק' מים שמעל השמים<sup data-n=\"720\">337</sup> העליונים מבחי'<sup data-n=\"721\">338</sup> מקיף הכללי דאבי\"ע). וזהו הכלל בכל מקום דכל הגבוה גבוה יותר יותר יוכל להשפיל ולהוריד א\"ע, וע\"כ הי'",[["712","329","<b>תלמיד ותיק שעתיד לחדש</b>: נסמן לעיל רנג, ד."],["713","330","<b>משה שפיר קאמרת</b>: ראה גם לעיל י, ב. וש\"נ."],["714","331","<b>כי</b>: בה: כו'."],["715","332","<b>שמברכים בכל יום נותן התורה</b>: נסמן לעיל רנד, א."],["716","333","<b>כנ\"ל</b>: כנצ\"ל: כנ\"ל)."],["717","334","<b>ממש כנ\"ל</b>: ב: ליתא. ה: ממש."],["718","335","<b>כי טוב הוא בטי\"ת רבתי</b>: שמות ב, ב ובמנחת שי שם. ראה לעיל פ' שמות מג, ד. וש\"נ."],["719","336","<b>מן המים משיתיהו מבחי' מ\"ע</b>: שמות ב, י. ראה לעיל מג, א. וש\"נ."],["720","337","<b>ים הקדמוני שנק' מים שמעל השמים</b>: ראה גם לעיל מד, א. וש\"נ."],["721","338","<b>מבחי'</b>: בה: בחי'."]]],[2300550578,"יכול להוריד גילוי אור עצמות א\"ס במקום נמוך יותר דהיינו בחכ' שבתו\"מ הנגלות לנו להיות שרשו מבחי' מ\"ע<sup data-n=\"722\">339</sup> דח\"ע הקדומה שבעצמות א\"ס ממש כמ\"ש מה שמו מה שם בנו<sup data-n=\"723\">340</sup> אותיות משה<sup data-n=\"724\">341</sup> כו'. וע\"כ נק' שושבינא דמלכא<sup data-n=\"725\">342</sup> להיות בחי' [ממוצע] להביא ולהמשיך תמיד מח\"ע דעצמות א\"ס שבתורה הקדומה למטה ממש בכנס\"י כמו שהוא למעלה שהוא להלביש בלבושי' גשמיי' במעשה גשמי', לפי שהח\"ע דתורה מאין תמצא מבחי' אין האמיתי דבחי' העצמות ממש וכמ\"ש ואהי' אצלו אמון אצלו <span data-k=\"pg\">770</span> ּ ממש. וע\"כ ע\"י נשמת משה שהי' שרשו מבחי' אין ומ\"ה העצמי נמשך מאין ומ\"ה דח\"ע העצמי' גם למטה בעולם הנפרד כמו שהוא למעלה ממש בלי שינוי כלל כנ\"ל, וזאת המעלה המיוחדת הוא למשה דוקא. והוא מ\"ש משה ידבר משה דוקא, וידבר זה לשון הוה בתמידות שתמיד ידבר לפי שבחי' משה יש בכל דור ודור<sup data-n=\"726\">343</sup> שמתפשט בכ\"א<sup data-n=\"727\">344</sup> להיות בו בחי' מ\"ה דמשה, כי הי' משה עניו בתכלית מכל האדם<sup data-n=\"728\">345</sup> והוא בחי' השפלות והעדר הרגשת עצמו מכל וכל בתכלית הביטול במציאות. ויש בחי' זו בכאו\"א מישראל בביטול הרצון לגמרי לנגד רצון ה' בקיום התו\"מ שזהו קבלת התו\"מ שנקבע לדורות כידוע, והוא מ\"ש בזהר דאתפשטותא דמשה בכל דרא<sup data-n=\"729\">346</sup> כו' שהוא הענוה ושפלות בתכלית כו' וע\"י בחי' זו נמשך תמיד גילוי אוא\"ס בחכ' שבתו\"מ<sup data-n=\"730\">347</sup> להיות נמצא גם למטה מטה כמו למעלה ממש גם בכאו\"א בעסקו בתו\"מ. וז\"ש משה ידבר שתמיד בחי' משה ידבר וימשיך וינהיג התפשטות גילוי אוא\"ס בעצמו בתו\"מ (וגם לע\"ל משה ידבר כו' וכמארז\"ל יבא טוב ויקבל טוב יבא טוב זה משה<sup data-n=\"731\">348</sup> כו' וד\"ל).\n[יב] <b>והאלקים</b> יעננו בקול, וארז\"ל בקולו של משה דוקא, דהנה ארז\"ל כל היושב ושונה וקורא הקב\"ה יושב ושונה וקורא<sup data-n=\"732\">349</sup> כנגדו שנא' ה' צלך<sup data-n=\"733\">350</sup> כו', ובאמת משמע פשוטו שכל מי שקורא יהי' מי שיהי' גם פחות הערך בקטנות המדרגה כע\"ה וקטן שקורא דבר ה' כמו בתורה<sup data-n=\"734\">351</sup> ושונה ה' יושב ושונה כנגדו ממש לפי מה שהוא באותו מדריגה בשרש נשמתו משם ימשיך הקריאה אליו שיהי' ה' יושב וקורא כנגדו, ואיך יתכן שיומשך גילוי אלקות בירידת המדריגה כ\"כ למטה מטה שגם בהיות הקורא ושונה פחות הערך מאד (ומכוער במעשיו רק שלא עבר עמ\"ש בתו' כמו בע\"ק שמותר בד\"ת<sup data-n=\"735\">352</sup> ) וקרא כנגדו. אך הענין הוא דהכל מטעם א' כנ\"ל דכבר ניתן כח ירידה זאת במתנה לישראל במ\"ת שיאיר אור ה' בד\"ת שניתנה למטה כמו",[["722","339","<b>מבחי' מ\"ע</b>: בה: בבחי' מ\"ה."],["723","340","<b>מה שמו מה שם בנו</b>: משלי ל, ד [ושם: ומה וכ\"ה בב — נסמן לעיל פ' שמות א, סע\"ב ואילך]."],["724","341","<b>מה שמו. . אותיות משה</b>: ראה גם לעיל מג, ד. וש\"נ."],["725","342","<b>משה. . שושבינא דמלכא</b>: ראה זהר (רע\"מ) ויקרא כ, א. מצורע נג, ב. (רע\"מ) שופטים ערה, ב. לעיל יא, ג. וש\"נ."],["726","343","<b>משה יש בכל דור ודור</b>: נסמן בסמוך הערה 346."],["727","344","<b>משה. . שמתפשט בכ\"א</b>: ראה גם לעיל פ' בשלח קנו, ד. וש\"נ."],["728","345","<b>משה עניו. . מכל האדם</b>: בהעלותך יב, ג."],["729","346","<b>דאתפשטותא דמשה בכל דרא</b>: ראה ת\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א-ס\"א). הנסמן לעיל פ' וארא פ, ג."],["730","347","<b>שבתו\"מ</b>: ב: שבתו'."],["731","348","<b>יבא טוב. . משה</b>: ראה מנחות נג, ב. הנסמן לעיל מג, ד."],["732","349","<b>וקורא</b>: בה: ליתא."],["733","350","<b>ה' צלך</b>: תהלים קכא, ה. ראה גם לעיל סה, ד הערה 283."],["734","351","<b>בתורה</b>: ב: הניח מקום פנוי. ה: בתנ\"ך."],["735","352","<b>בע\"ק שמותר בד\"ת</b>: ברכות כב, א. ראה גם לקמן פ' תצוה שע, ג."]]],[2300550589,"שהיא למעלה ממש, והוא ע\"י משה דוקא כמ\"ש משה ידבר כו' וכמו שא' דהאי יומא דקא גרים כו' ודוקא ע\"י משה דאתפשטותי' בכל דרא להביא ולהמשיך גילוי אוא\"ס בתו\"מ שלמטה לכל עוסק בהם שלא יהי' העולם תופס מקום כלל למטה כמו למעלה ממש. והטעם שע\"י משה דוקא מבואר למעלה לפי ששרשו בפנימי' דשם מ\"ה דח\"ע כו', וע\"כ גם בירידתו למטה מטה אין הצמצום והסתר דשם אלקים מסתיר לפניו כלל ולכך ע\"י בחי' משה יכול להמשיך שיהי' ה' קורא ושונה כנגד כל איש ואיש הקורא ושונה [גם] לפי מדרגתו התחתונה ביותר. וכידוע בזהר דמשה נק' איש האלקי'<sup data-n=\"736\">353</sup> בעלה דמטרוניתא<sup data-n=\"737\">354</sup>, פי'<sup data-n=\"738\">355</sup> האלקים הוא בחי' הצמצום כידוע בפי' שמש ומגן הוי' אלקים<sup data-n=\"739\">356</sup> והוא כח הפועל האלקי' ב[נפעלים ו]נבראים אחר הצמצום והסתר על שם הוי' כו', ויש בשם אלקי' ק\"ך צירופי'<sup data-n=\"740\">357</sup> בכללו' דג' עולמות בי\"ע כו' עד שגם במדרגות התחתונות דסוף עולם העשי' יש ג\"כ צירופי' דשם אלקי' ממ\"ח צרופי' האחרונים<sup data-n=\"741\">358</sup> שמזה נעשה שרש להתהוות בחי' נוגה דמרכבה דעשי' כפני שור שבעשי' שנמשך בריבוי השתל' להיות שורש לנפשות הבהמות<sup data-n=\"742\">359</sup> ומשם שרש נה\"ב דאדם<sup data-n=\"743\">360</sup>. וע\"כ גם מי שקורא ושונה בהבל פיו הגשמיי' ש[מ]גופ[ו] שנלקח מנוגה דעשי' קול זה יעורר בשרשו בצרופי' דאלקי' דעשי' <span data-k=\"pg\">שפה</span> ּ שרש ומקור אותו המרכבה דפני ארי' ושור ומשם יעננו האלקים זה בקול להיות יושב וקורא כנגד[ו] לפי מה שהוא ממש. וזהו והאלקים דוקא יעננו לפי שזהו נמשך ע\"י משה שנק' איש האלקי' בעלה דמטרוניתא שהוא בחי' יחו\"ת דשם האלקי' נק' איש האלקי' להמשיך גילוי אלקות לכל מי שיש לו שרש בשם אלקי' שהאלקי' יעננו בקול זה שקורא ושונה כמו שהי' במ\"ת שמשה ידבר והאלקים יעננו בקול וכנ\"ל, וגם לפחות הערך כקטנים וע\"ה בקריאתם בתו' הרי לכולם יש שרש לנשמתם בבחי' אלקי' ולפי בחי' מדריגתו יעננו אלקי' לקרות כנגדו כשקורא ושונה (ולזה הכל מברכי' נותן התורה וד\"ל). וזהו שארז\"ל בקולו של משה דוקא לפי שהוא הגורם הירידה הזאת [ש]ל אוא\"ס למטה בתו\"מ שיהי' כמו למעלה מטעם הנ\"ל, ע\"כ כאשר האלקי' יעננו לקורא בתו' [לקרות] ולשנות כנגדו אינו עונה רק אחר קולו של משה דוקא להיותו מבחי' שם הוי' דפנימי' ח\"ע הקדומה כנ\"ל שלמעלה משם אלקים זה, וע\"כ נק' איש האלקי' כנ\"ל ע\"כ האלקי' יעננו בקולו של משה דוקא לפי שמשה ידבר דוקא שהוא נק' שוש[בינא] דמלכא להוריד<sup data-n=\"744\">361</sup> החתן לגבי הכלה להיות למטה כמו שהוא למעלה בעצמות ממש כו'. ולזה הטעם גם<sup data-n=\"745\">362</sup> מי שיש בו קצת הארה ממדריגת משה איש האלקי' שהוא הענוה והשפלות העצמי' בתכלית כנ\"ל וקורא בתו' בכל דור ובכל זמן",[["736","353","<b>דמשה נק' איש האלקי'</b>: ברכה לג, א. תהלים צ, א."],["737","354","<b>דמשה. . בעלה דמטרוניתא</b>: ראה זהר ויחי רלו, ב. תרומה קלז, ב. מאמרי אדה\"א ויקרא ח\"א ע' קנא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680302\" data-slug=\"torat-chaim\" data-id=\"2300680302\">תו\"ח וישב רט, ב</a> הערה 23."],["738","355","<b>פי'</b>: ה: כי."],["739","356","<b>האלקים. . הצמצום. . שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שער היחוד והאמונה רפ\"ו. הנסמן לעיל פ' שמות לד, ד."],["740","357","<b>בשם אלקי' ק\"ך צירופי'</b>: ראה ע\"ח (שער הזיווגים) שט\"ו, פ\"ו. (שער השמות) שמ\"ד, פ\"ה. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז."],["741","358","<b>ממ\"ח צירופי' האחרונים</b>: נסמן לעיל רנד, ב."],["742","359","<b>כפני שור. . לנפשות הבהמות</b>: ראה יחזקאל א, י. ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ח. לקמן פ' ויקהל תכח, סע\"ג ואילך. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ."],["743","360","<b>כפני שור. . נה\"ב דאדם</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תקצט. וש\"נ. ש\"א יז, א הערה 11."],["744","361","<b>להוריד</b>: ב: להעמיד."],["745","362","<b>גם</b>: בה: כל."]]],[2300550600,"נק' זה קולו של משה דאתפשטותא דמשה בכל דרא בקול תורה דוקא שז\"ש משה ידבר בתמידות כנ\"ל שמדבר וממשיך גילוי אוא\"ס למטה שיהי' יושב ושונה כנגד כל הקורא ושונה כנגדו ממש לפי מה שהוא גם למטה מטה ביותר וד\"ל.\n[יג] <b>ובכל</b> הנ\"ל יתורצו כל הקושיות הנ\"ל במ\"ש משה ידבר ויעננו לשון הוה, שהרי ע\"י בחי' משה שהוא בחי' מ\"ה שהוא בחי' הביטול והשפלות כנ\"ל תמיד ידבר דבר העתיד<sup data-n=\"746\">363</sup> יעננו האלקי' בקולו של משה דוקא בכל דור ובכל זמן (וגם לעתיד בקבלת פנימי' התורה<sup data-n=\"747\">364</sup>, וגם הקושי' הראשונה יתורץ משה ידבר על מה הוא אומר זה הרי ב' דברות דאנכי כו' מפי הגבו' עצמו שמעו ועל שאר הדברות לא נז' שהאלקי' יעננו בקול. ואמנם האמת הוא דמשה ידבר זה קאי על כל המשכות גילוי אלקות שבתורה לעתיד בכל דורות הבאים שכח המשכה זאת מלמעלה למטה בעולם הפירוד שיהי' ה' יושב וקורא ושונה כנגדו כל מי שיקרא וישנה למטה כנ\"ל יהי' מי שיהי' (אפי' בע\"ק וקטן וע\"ה) הרי נעשה ונמשך כח זה ע\"י משה דוקא לפי שהי' הוא המדבר והאלקים יעננו בקול במ\"ת וד\"ל. וזהו משה ידבר לעתיד להמשיך ולהוריד גילוי אוא\"ס והאלקי' יעננו בקולו של משה למטה הרי יש כאן ב' דברים, הא' כח ההמשכה מלמעלמ\"ט שז\"ש משה ידבר לפי שנק' שוש[בינא] דמלכא מטעם הנ\"ל. והב' מה שהאלקים יעננו בקול למטה דוקא ש[י]הי' למטה אותו גילוי אור העליון כמו שהוא למעלה כנ\"ל. וזהו כמשל ב' בנ\"א שמדברים זע\"ז איך לגמור איזה דבר מה שיתקיים לעולם כמו שיתקיים החיתון דחתן וכלה שזה מביא ומוריד את החתן למטה וזה מביא לכלה שתתייחד עם החתן ויהי' ביניהם חיבור ויחוד וקשר לעולם כו' (והיינו יחוד מ\"ה וב\"ן דמשה <span data-k=\"pg\">772</span> ּ הוא בבחי' שם מ\"ה<sup data-n=\"748\">365</sup> כמ\"ש מה שמו כו', והאלקי' הוא בחי' שם ב\"ן<sup data-n=\"749\">366</sup> ) שיעננו בקולו של משה דוקא בתמידות. וזהו שא' רב יוסף דאי לאו האי יומא דקא גרים כמה יוסף כו' משום דהאי יומא דחג השבועות הוא שמשה ידבר על העתיד כנ\"ל, והאי יומא דקא גרים בכל חג השבועות אחר שנשלמו ימי הספי' דוקא שאז הוכשרו בנ\"י למתנה זאת שיותן להם התורה במתנה ע\"י משה, והוא יום החמישים שנק' שער החמישים דבינה אחר שנשלם מ\"ט<sup data-n=\"750\">367</sup> שע\"ב דמ\"ט ימי הספי'<sup data-n=\"751\">368</sup> שאז זכו לשער החמישים דבינה שנק' כתר תורה<sup data-n=\"752\">369</sup> כידוע, והוא שאנו אומרים זמן מתן תורתינו שתלוי בזמן זה דוקא וד\"ל.",[["746","363","<b>דבר העתיד</b>: בה: ה' ותמיד."],["747","364","<b>התורה</b>: אוצ\"ל: התורה)."],["748","365","<b>דמשה. . מ\"ה</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["749","366","<b>והאלקי'. . ב\"ן</b>: ראה גם לעיל פ' שמות יט, ג הערה 814."],["750","367","<b>מ\"ט שע\"ב</b>: ראה ר\"ה כא, ב."],["751","368","<b>מ\"ט שע\"ב דמ\"ט ימי הספי'</b>: ראה גם לעיל פ' בא קיא, ד. וש\"נ."],["752","369","<b>כתר תורה</b>: ראה גם לעיל שם. וש\"נ."]]],[2300550043,"<b>פ' יתרו תקפווא\"ו</b>\n<b>זכור</b> את יום השבת<sup data-n=\"753\">1</sup> לקדשו<sup data-n=\"754\">2</sup> כו', וידוע שבדברות האחרונות (בפ' ואתחנן) א' שמור את יום השבת<sup data-n=\"755\">3</sup> כו', וארז\"ל דזכור ושמור בדבור א' נאמרו<sup data-n=\"756\">4</sup> כו' וזהו פלא איך יוכל להיות זכור ושמור בדבור אחד שהרי א' משה ידבר<sup data-n=\"757\">5</sup> כו' ומ\"ש זכור זה הי' מפי ה' למשה בדברות הראשונות ומ\"ש שמור זהו שאמר משה מפי עצמו<sup data-n=\"758\">6</sup> כשחזר להם את יו\"ד הדברות לאחר זמן [רב] כו' (ומה שארז\"ל דאנכי ולא יהי' כו' שמפי הגבורה<sup data-n=\"759\">7</sup> [שמעו ו]נאמרו בדיבור אחד<sup data-n=\"760\">8</sup>, זה יתכן להיות דמפי הגבורה שאני ובזמן אחד הי' הדבור, אבל זכור ושמור מפי משה נאמרו וב[שני] זמנים רחוקים כו') (ועוד יש להבין מ\"ש כאן בטעם דזכור את כו' כי וי\"ו ימים עשה ה' כו' וינח ביום הז' ע\"כ בירך ה' את יום השבת ויקדשהו<sup data-n=\"761\">9</sup> ובדברות האחרונות אמר הטעם לשמור את כו' וזכרת כי עבד היית באמ\"צ ויוציאך כו' ע\"כ צוך ה' אלקיך לעשות את יום השבת<sup data-n=\"762\">10</sup>, וזהו פלא מה שייכות יצ\"מ לענין המנוחה דשבת שאמר ע\"כ צוך לעשות כו' ומה ענין לעשות ולא אמר לקדש כמ\"ש בתחילה כו'). והנה באמת יש להבין בגוף הענין מ\"ש זכור את יום כו' דמשמע שזהו ענין ציווי ואזהרה לישראל דוקא שהם יזכרו לקדש את יום השבת, ולפ\"ז מובן דקדושת השבת בישראל תליא דוקא וע\"כ ציוה שהם דוקא יקדשו את השבת, ובאמת הלא ארז\"ל דשבת מיקדשא וקיימא<sup data-n=\"763\">11</sup> מששת ימ\"ב והוא [ב]שבת הראשון שנק' שבת בראשית שנא' ויברך אלקים את כו' ויקדש אותו<sup data-n=\"764\">12</sup> כו' (וכן כאן ביו\"ד הדברות אמר ע\"כ ברך ה' את יום השבת ויקדשהו כבר בו' ימ\"ב). וכל שבת נק' שבת בראשית<sup data-n=\"765\">13</sup> מאחר שמחדש מע\"ב בטובו בכל יום כידוע, וא\"כ כל שבת מיקדשא וקיימא מקדושת ה' שקידשו מכבר וא\"צ כלל שישראל יקדשו אותו ואין קדושת שבת תלוי בישראל כלל ואין ביכולתם לקדש את השבת, רק לשמור לקדושת השבת שכבר [ח]לה ביום השבת שנק' קדש וכמ\"ש ושמרתם את השבת<sup data-n=\"766\">14</sup> כי קדש היא לכם שאין הציווי רק שישמרו את הקדושה דשבת שכבר קודש, וכן",[["753","1","<b>זכור את יום השבת</b>: מיוסד על ד\"ה זה שנדפס במאמרי אדה\"ז תקס\"ט ע' לב [הנחת כ\"ק אדה\"א, והנחה אחרת ב]<a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א יתרו סט, ג</a>. וראה בהנסמן במ\"מ בהנ\"ל. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם מפורט ג\"כ סימני האותיות הבאים להלן בהמראי מקומות]."],["754","2","<b>זכור את יום השבת לקדשו</b>: יתרו כ, ח."],["755","3","<b>שמור את יום השבת</b>: ואתחנן ה, יב."],["756","4","<b>דזכור ושמור בדבור א' נאמרו</b>: ר\"ה כז, א. מכילתא יתרו כ, ח."],["757","5","<b>משה ידבר</b>: יתרו יט, יט."],["758","6","<b>שמור. . משה מפי עצמו</b>: ראה מגילה לא, ב. מאמרי אדה\"א שמות ח\"ב ע' שלא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730111\" data-slug=\"likkutei-sichot\" data-id=\"1301730111\">לקו\"ש</a> ר\"ח שבט (כרך לו) ע' 42."],["759","7","<b>דאנכי ולא יהי'. . שמפי הגבורה</b>: יתרו כ, ב. ג. מכות כד, א. ראה מו\"נ ח\"ב פל\"ג. תניא פ\"כ."],["760","8","<b>דאנכי ולא יהי'. . בדיבור אחד</b>: ראה שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670576\" data-slug=\"torat-chaim\" data-id=\"2300670576\">תו\"ח בראשית מה, ד</a> ובהערה 36."],["761","9","<b>כי וי\"ו ימים. . ע\"כ בירך ה'. . ויקדשהו</b>: יתרו כ, יא."],["762","10","<b>וזכרת כי עבד היית. . יום השבת</b>: ואתחנן ה, טו."],["763","11","<b>דשבת מיקדשא וקיימא</b>: ביצה יז, א."],["764","12","<b>ויברך. . ויקדש אותו</b>: בראשית ב, ג."],["765","13","<b>וכל שבת נק' שבת בראשית</b>: ראה ב\"ב קכא, א וברשב\"ם שם. יומא פא, א. מוע\"ק ד, א. נדרים עח, א-ב. מנחות סה, ב. סו, א. מכילתא ורש\"י משפטים כג, יב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' חצר. תקס\"ח ח\"א ע' תקלב. שע\"ת יג, א. קטו, ד. מאמרי אדה\"א שמות ח\"א ע' רי. לקמן רסו, ד. פ' ויקהל תכא, ד. לעיל פ' בשלח רי, א. ריז, ג. ריח, ד. ריט, א."],["766","14","<b>ושמרתם את השבת</b>: תשא לא, יד."]]],[2300550075,"ושמרו בנ\"י את השבת<sup data-n=\"767\">15</sup> כו' (וכן <span data-k=\"pg\">שפו</span> ּ שמור את יום כו' וכמשי\"ת). וא\"כ מהו זה שמצוה ומזהיר כאן זכור את יום השבת לקדשו מאחר דלאו [ב]דידהו תליא קדוש[תו] משום דכבר מיקדשא מעצמות אוא\"ס ב\"ה כמ\"ש ויקדש אותו כו'. והטעם הוא כי שרש השבת למעלה ממדרגת ישראל<sup data-n=\"768\">16</sup> (רק אות היא ביני<sup data-n=\"769\">17</sup> כו' וניתנה במתנה לישראל<sup data-n=\"770\">18</sup> כמ\"ש ראו כי ה' נתן לכם את השבת<sup data-n=\"771\">19</sup> כו' כמ\"ש במ\"א), כידוע בענין קידוש<sup data-n=\"772\">20</sup> דשבת שזהו קדש דחכ' עילאה כמו שהחכ' בבחי' אין כמ\"ש והחכ' מאין תמצא<sup data-n=\"773\">21</sup> שזהו שנק' קדש מלה בגרמ[י']<sup data-n=\"774\">22</sup> כו' בבחי' קדושה והבדלה בערך מכל ההשתל' דמע\"ב שהוא בחכ' כמ\"ש בראשית בחוכמתא<sup data-n=\"775\">23</sup> כו' שזהו בחי' החכ' שיורד מאין ליש דוקא להיות כל העולמות וז\"ש<sup data-n=\"776\">24</sup> כולם בחכ' עשית<sup data-n=\"777\">25</sup> וכן ה' בחכ' יסד ארץ<sup data-n=\"778\">26</sup> וכה\"ג, אבל שבת הוא בחי' השביתה מירידה זאת דחכמה כמ\"ש כי בו שבת<sup data-n=\"779\">27</sup> כו' (כמשי\"ת) ע\"כ נק' שבת קדש העליון שלמעלה ממדרגות דישראל כו' (דגם שישראל נק' קדש כמ\"ש קדש ישראל לה'<sup data-n=\"780\">28</sup> ראשית תבואתו והוא בחי' ראשית דחכ' שנק' ראשית חכ'<sup data-n=\"781\">29</sup> כידוע וזהו בבחי' חכמה שנמשך [מ]אין דהעלם ואין דכתר למציאות [חכ'] להיות מקור למע\"ב, ומטעם זה אמר דישראל הוא דקדשינהו לזמנים<sup data-n=\"782\">30</sup> דמועדים וזמנים הן בבחי' מוחין דאימא שנק' מקרא קדש<sup data-n=\"783\">31</sup> כידוע, ולכך [א'] אלה מועדי הוי'<sup data-n=\"784\">32</sup> אשר תקראו אותם אפי' שוגגין<sup data-n=\"785\">33</sup> כו' וכמו שאמר מקדש ישראל והזמנים<sup data-n=\"786\">34</sup> משום דישראל מקדשי לזמנים משום דבינה מקבל מחכמה שנק' ראשית, אבל קדושת השבת למעלה מקדושת ישראל ולכך אמר ברוך אתה ה' מקדש השבת<sup data-n=\"787\">35</sup> דשבת מיקדשא וקיימא מוימ\"ב כמ\"ש ויקדש אותו, וא\"כ יש להבין דאם קדושת שבת תלוי בישראל למה א' ברוך אתה ה' מקדש השבת דמשמע דקדושת שבת מלמעלה באה (אך בקדושת דזמנים אמר מקדש ישראל תחלה ואח\"כ והזמנים מטעם הנ\"ל דישראל קדשינהו לזמנים כו'). (אמנם מה שאמר בדברות האחרונות שמור את יום השבת לקדשו זה יתכן לפי הנ\"ל דוקא דשבת מיקדשא וקיימא כו' משום דשמירה זו אינו אלא לשמור לקדושת השבת שכבר",[["767","15","<b>ושמרו בנ\"י את השבת</b>: תשא לא, טז."],["768","16","<b>שרש השבת למעלה ממדרגת ישראל</b>: ראה תו\"א כאן שמציין לזהר ורמ\"ז."],["769","17","<b>אות היא ביני</b>: תשא לא, יג."],["770","18","<b>וניתנה במתנה לישראל</b>: ראה שבת י, ב. מאמרי אדה\"א שמות ח\"א ע' רכו וע' רלג."],["771","19","<b>ראו. . את השבת</b>: בשלח טז, כט [בהוספת תיבת ”את\" — ראה ירושלמי נדרים פ\"ג, ה\"ט. מס' סופרים ספי\"ג. שמו\"ר פכ\"ה, יא. יל\"ש עה\"פ (רמז רסא). בה\"ג ריש הל' ערובין. הנסמן במאמרי אדה\"א שמות ח\"א ע' רה]."],["772","20","<b>קידוש</b>: בד: קודש."],["773","21","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["774","22","<b>קדש מלה בגרמ[י']</b>: זהר אמור צד, ב."],["775","23","<b>בראשית בחוכמתא</b>: ראה תרגום ירושלמי בראשית א, א."],["776","24","<b>וז\"ש</b>: ב: נרשם כאן פרק ב."],["777","25","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["778","26","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["779","27","<b>כי בו שבת</b>: בראשית ב, ג."],["780","28","<b>קדש ישראל לה'</b>: ירמי' ב, ג."],["781","29","<b>שנק' ראשית חכ'</b>: ראה תהלים קיא, א. מאמרי אדה\"א בראשית ע' א. וש\"נ. ש\"א מ, א. שה\"א סא, א ובהערה 9. לקמן רסז, סע\"ב. פ' פקודי תמג, ב."],["782","30","<b>דישראל הוא דקדשינהו לזמנים</b>: ראה ברכות מט, א."],["783","31","<b>מוחין דאימא שנק' מקרא קדש</b>: ראה פע\"ח (שער מקרא קדש) ש\"כ, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד. שמות ח\"א ע' נז."],["784","32","<b>אלה מועדי הוי'</b>: אמור כג, ד."],["785","33","<b>אפי' שוגגין</b>: ר\"ה כה, א."],["786","34","<b>מקדש ישראל והזמנים</b>: נוסח ברכת היום דיו\"ט. ברכות מט, א."],["787","35","<b>ברוך. . מקדש השבת</b>: נוסח ברכת היום דשבת."]]],[2300550107,"חלה וכמ\"ש ושמרתם את השבת כי קדש היא כו' (ומ\"ש שמור את כו' לקדשו משמע דע\"י שמירה זו מתקדש יום השבת כו' ובאמת כבר קדוש הוא כנ\"ל, הענין הוא כידוע דכל השמר פן ואל הוא בחי' ל\"ת<sup data-n=\"788\">36</sup> וגם כאן שמור דשבת היינו שלא לחלל קדושת[ו] שמכבר קדוש, והוא רק בשמירה מכל מלאכה ואמנם בזה נמשך קדוש' דשבת מלמעלה כמ\"ש לקדשו בקדושה העליונה ממילא כמשי\"ת. אבל מ\"ש זכור כו' שזהו מ\"ע<sup data-n=\"789\">37</sup> לקדש ליום השבת דהיינו שישראל יעשו את הקדושה דשבת ע\"י אתעדל\"ת שלהם דוקא וזה אינו דלא[ו] בדידהו תליא כדלעיל).\n<b>והנה</b><sup data-n=\"790\">38</sup> יש להבין עוד מ\"ש זכור כו' כאן במ\"ע ובדברות האחרונו' א' שמור במל\"ת דכל השמר כו' דמשמע שיש בשבת מ\"ע ומצות ל\"ת והלא מצוה אחד<sup data-n=\"791\">39</sup> הוא לשמור את יום השבת כמ\"ש ושמרו בנ\"י את כו'. וגם א\"כ האיך ארז\"ל דזכור ושמור בדבור א' נאמרו האיך <span data-k=\"pg\">774</span> ּ יכולים להתכלל יחד מ\"ע דזכור ומל\"ת דשמור בדבור אחד (דמ\"ע הוא בבחי' החסדי' ול\"ת הוא בבחי' הגבור[ות]<sup data-n=\"792\">40</sup> כידוע שהן ב' הפכים, ומ\"ש דאנכי ולא כו' בדבור א' נאמרו שהן ג\"כ בבחי' חו\"ג דמ\"ע ול\"ת בכלל זהו בבחי' חו\"ג דכתר<sup data-n=\"793\">41</sup> שמפי הגבורה שמעו כנ\"ל), וכידוע בדברי רז\"ל דזכרי עם ו\"ה גימט' רמ\"ח ושמי עם י\"ה<sup data-n=\"794\">42</sup> גימט' שס\"ה שהן רמ\"ח מ\"ע בו\"ה דשם הוי' ושס\"ה ל\"ת בשמי עם י\"ה כו', וא\"כ גם כאן בענין מ\"ע דזכור כו' זהו בבחי' זכרי עם ו\"ה דרמ\"ח מ\"ע ושמור כו' שהוא בל\"ת כנ\"ל שהוא בבחי' שמי עם י\"ה דשס\"ה ל\"ת ואיך יכול להיות שזכור ושמור דמ\"ע ומצות ל\"ת יהיו כלולים בדבור א' שזה בו\"ה וזה בי\"ה (ולפ\"ז שמור קודם לזכור די\"ה קודם לו\"ה ובזהר אמר דזכור לדכורא ושמור לנוק'<sup data-n=\"795\">43</sup> כידוע. אך הנה גם זכור עם י\"ה עולה גימט' רמ\"ח<sup data-n=\"796\">44</sup> כמו שזכרי עם ו\"ה עולה גימט' רמ\"ח, ולפ\"ז לפעמים שרש השבת בו\"ה, דזכרי עם ו\"ה שרש הרמ\"ח מ\"ע להיות השבת כללות מ\"ע, ולפעמים שרש השבת בי\"ה עם זכור כנ\"ל די\"ה שרש השס\"ה ל\"ת שזהו ענין שמור דשבת שהוא ל\"ת וי\"ה למעלה מו\"ה ושניהם מתאחדים בשבת שזהו שאמר שמור וזכור בדבור א' נאמרו, כי זכור לדכורא הוא לפעמים בי\"ה בגימט' דזכור עם י\"ה וגם שמור דנוק' הוא בו\"ה<sup data-n=\"797\">45</sup> עם שמי שרש ל\"ת. וזה ביום ההוא יהי' ה' אחד יחו\"ע ושמו אחד יחו\"ת<sup data-n=\"798\">46</sup> ויהי' ב' פעמים<sup data-n=\"799\">47</sup> י\"ה<sup data-n=\"800\">48</sup>",[["788","36","<b>השמר פן ואל. . ל\"ת</b>: ערובין צו, א."],["789","37","<b>זכור. . שזהו מ\"ע</b>: ראה ספר המצות להרמב\"ם מ\"ע קנה. שו\"ע אדה\"ז הל' שבת סרע\"א בתחלתו ובהנסמן עה\"ג שם."],["790","38","<b>והנה</b>: ב: נרשם כאן פ\"ג. וראה לעיל הערה 24."],["791","39","<b>אחד</b>: בה: א'."],["792","40","<b>דמ\"ע. . החסדי' ול\"ת. . הגבור[ות]</b>: ראה זח\"ב (תוספות) רעו, א. ת\"ז בהקדמה (ה, א). ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ד."],["793","41","<b>דאנכי ולא. . חו\"ג דכתר</b>: ראה גם מאמרי אדה\"א בראשית ע' ריד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670540\" data-slug=\"torat-chaim\" data-id=\"2300670540\">תו\"ח וירא קיט, ב</a>."],["794","42","<b>דזכרי עם ו\"ה. . ושמי עם י\"ה</b>: נסמן לעיל רנב, א."],["795","43","<b>דזכור לדכורא ושמור לנוק'</b>: זהר בראשית מח, ב. (רע\"מ) יתרו צב, א."],["796","44","<b>זכור עם י\"ה. . רמ\"ח</b>: ראה בחיי כאן (יתרו כ, ח). באוה\"ת כאן מציין: קונטרס [נפתולי אלקים לר' נפתלי בר' אליעזר טריווש] שבסו\"ס הבחיי [קראקא שנב-ג] פ' יתרו סעיף לד."],["797","45","<b>בו\"ה</b>: ג: בי\"ה."],["798","46","<b>ביום ההוא יהי'. . יחו\"ע. . יחו\"ת</b>: זכרי' יד, ט. נסמן לעיל רסב, א."],["799","47","<b>ויהי' ב' פעמים י\"ה</b>: ראה לקו\"ת להאריז\"ל זכרי' שם."],["800","48","<b>ב' פעמים י\"ה</b>: תוקן ע\"פ בד: ובתו\"ח כאן: ה'."]]],[2300550139,"אחד בזכור לדכורא וב' בשמור לנוק' די\"ה י\"ה<sup data-n=\"801\">49</sup> כולל ב' יחודים יחו\"ע ויחו\"ת שהן שוין ומתאחדים כאחד בשבת דוקא כמ\"ש כגוונא דאינון מתייחדין<sup data-n=\"802\">50</sup> לעילא אוף הכי לתתא<sup data-n=\"803\">51</sup> ממש שזהו בשבת<sup data-n=\"804\">*51</sup> דוקא כידוע וד\"ל).\n[ב<sup data-n=\"805\">52</sup> ] ואחר כ\"ז הנה תחלה יש להבין בשרש ענין השבת מהו, להיות ידוע בכללות ענין וימ\"ב שהן בחי' הוי\"ו מדות<sup data-n=\"806\">53</sup> דאצי' עם בחי' המוחין דחו\"ב מקורם שמתלבשים באותיות דמח' ודבור העליון בי' מאמרות להיות מקור לכל בריאה ובריאה שיברא מאין ליש ע\"י מאמר זה בפרט, כמו מאמר יהי אור<sup data-n=\"807\">54</sup> הוא המקור להתהוות מציאות האור בפו\"מ מאין ליש וכן ממאמר יהי רקיע<sup data-n=\"808\">55</sup> נתהווה הרקיע כו', וכה\"ג בכל המאמר[ים] בכלל ובפרט כמו ממאמר תדשא הארץ דשא<sup data-n=\"809\">56</sup> כו' נתהוו כמה מיני דשאים ועשבים גם [עתה] שיולד מכח הצומח שבארץ כו'. וידוע שאין אותיות דבור העליון כדבור האדם בע\"ג שאי[נו] פועל כלום, אבל בדבר ה' הרי זה דבר מלך שגוזר ואמר ויהי כן בפו\"מ כמ\"ש ודבר אלקינו יקום לעולם<sup data-n=\"810\">57</sup> וכתיב בדבר ה' שמים נעשו<sup data-n=\"811\">58</sup> וברוח פיו כל צבאם שהן ע\"י בחי' צירופי אותיות די' מאמרות העליונים שבהן [הוא] גילוי אור האלקי ממש, שהדבור מורה ענין התגלות לחוץ כמ\"ש בזהר דאתוון אתגליפו<sup data-n=\"812\">59</sup> כו' שאותיות אלקי' אלה הן נמשכים ו[מ]תגלפים בתוך כל בריאה מן צרופי אותיות די' מאמרות, כמו מי שאמר לשמן<sup data-n=\"813\">60</sup> וידל[י]ק הוא [י]אמר לחומץ וידל[י]ק שיתחלק צירופי אותיות האלקי' דשמן שמזה נעשה טבע היסודות בשמן להדליק הוא [י]אמר בצירוף זה לחומץ כו'. <span data-k=\"pg\">שפז</span> ּ וכה\"ג גם במלאכים ועולמות עליונים [ה]רוחני' יש לכל מלאך ומלאך צירוף מיוחד מצירופי' דשם אלקי' וכמ\"ש בס\"י ה' אבנים בונות<sup data-n=\"814\">61</sup> כו' מכאן ואילך צא וחשוב כו' כידוע שאין מספר לרבוי הצרופי' כו', וכך אין מספר לעולמות ומלאכים כמ\"ש היש מספר לגדודיו<sup data-n=\"815\">62</sup> אלף אלפי' ישמשוני'<sup data-n=\"816\">63</sup> כו' וכידוע, וכ\"ז [ב]בחי' צירופי אותיות הדבור [העליון] שנק' עלמא דאתגלייא ש[נ]חלק[ו] לריבוי רבבות צירופי' לאין שיעור כלל. וכמו\"כ ודאי יש בבחי' אותיות המח' עליונה שנק' עלמא דאתכסייא<sup data-n=\"817\">64</sup> (כמו שאמר דכל מה שיש ביבשה<sup data-n=\"818\">65</sup> [בחי'] עלמא דאתגלייא יש בים כו'). ואע\"פ שאין דבורו ומחשבתו כמו דבור ומח' שלנו כמ\"ש כי לא מחשבותי מחשבותיכם<sup data-n=\"819\">66</sup>, מ\"מ",[["801","49","<b>לנוק' די\"ה י\"ה</b>: בד: לנוק' דיהי' זה."],["802","50","<b>כגוונא דאינון מתייחדין</b>: זהר תרומה קלה, סע\"א [בדילוג]."],["803","51","<b>לעילא. . לתתא</b>: ב: כו'. ד: ליתא. . ב: איהי. ד: ליתא."],["804","*51","<b>כגוונא. . בשבת</b>: ראה גם לקמן פ' תצוה שנא, ג."],["805","52","<b>ב</b>: ב: נרשם כאן פ\"ד. וראה לעיל הערה 38."],["806","53","<b>וימ\"ב. . הוי\"ו מדות</b>: ראה זהר ויחי רמז, א. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["807","54","<b>יהי אור</b>: בראשית א, ג."],["808","55","<b>יהי רקיע</b>: שם א, ו."],["809","56","<b>תדשא הארץ דשא</b>: בראשית א, יא."],["810","57","<b>ודבר אלקינו יקום לעולם</b>: ישעי' מ, ח."],["811","58","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["812","59","<b>דאתוון אתגליפו</b>: ראה זהר בראשית טו, ב. שעה\"י קמא, ב הערה 46."],["813","60","<b>מי שאמר לשמן</b>: תענית כה, א (ובע\"י). ראה גם לעיל פ' שמות כ, א. וש\"נ."],["814","61","<b>ה' אבנים בונות</b>: נסמן לעיל רנב, ב."],["815","62","<b>היש מספר לגדודיו</b>: איוב כה, ג."],["816","63","<b>אלף אלפי' ישמשוני'</b>: דניאל ז, י."],["817","64","<b>הדבור. . עלמא דאתגלייא. . המח'. . דאתכסייא</b>: ראה גם לעיל פ' בשלח קמג, ד. וש\"נ."],["818","65","<b>דכל מה שיש ביבשה</b>: חולין קכז, א. ראה גם לעיל פ' שמות יח, ג. וש\"נ."],["819","66","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."]]],[2300550171,"דברה תורה כלשון בנ\"א<sup data-n=\"820\">67</sup> שאע\"פ שאין לו גוף<sup data-n=\"821\">68</sup> ואין לו דמות הגוף ח\"ו כמ\"ש כי לא ראיתם כל תמונה<sup data-n=\"822\">69</sup> עכ\"ז אמר וירא ה'<sup data-n=\"823\">70</sup> וישמע<sup data-n=\"824\">71</sup> כו', אך זה כענין שאמר הנוטע אזן הלא ישמע<sup data-n=\"825\">72</sup> היוצר<sup data-n=\"826\">73</sup> עין כו' שהן מלאכים עליונים הנק' עינים ואזנים<sup data-n=\"827\">74</sup> כו'. אבל מסט' דשכינת[א] עצמה אמר כי לא ראיתם כל תמונה<sup data-n=\"828\">75</sup> כו' כידוע רק מה שנוכל להשיג למעלה בבחי' אדם העליון דאצי' שגם שאינו בערך ויחוס המשתווים בתוארי אדם, הוא רק ממה שידוע שבצלם אלקי' עשה את האדם<sup data-n=\"829\">76</sup> התחתון במוחין ומדות וראי' ושמיעה ומח' ודבור ע\"כ אמר מבשרי אחזה אלוה<sup data-n=\"830\">77</sup> להבין ולהשכיל בדוגמא דדוגמא כזאת למעלה. וכמו\"כ מח' ודבור העליון נוכל להבין ממח' ודבור שבאדם התחתון להיות שהוא נברא בצלם אלקי' כו', ועכ\"ז אמר כי לא אדם הוא<sup data-n=\"831\">78</sup> כו'. ולזאת כמו שאנו רואים באדם שאותיות המח' הן בהעלם ולא בגילוי כלל כאותיות הדבור כך הוא למעלה באותיות המח' העליונה שע\"ז אמר מה גדלו מעשיך<sup data-n=\"832\">79</sup> מאד עמקו מחשבותיך וכן אמר נפלאותיך ומחשבותיך אלינו עצמו מספר<sup data-n=\"833\">80</sup> כו', והיינו ריבוי רבבות עולמות העליונים ביותר שמתהוים מצרופי אותיות המח' שלמעלה מצרופי אותיות די' מאמרות דמע\"ב שבאין בהתגלות מאין ליש ממש, אבל צרופי אותיות המח' שהן בהעלם ממש מהן נתהוו עלמין דאתכסיי' (וכמו נשמות הגבוה[ות] שנק' נוני<sup data-n=\"834\">81</sup> ימא<sup data-n=\"835\">82</sup> כו' כנשמות האבות<sup data-n=\"836\">83</sup> וכנשמת משה דמן המים עליונים משיתיהו<sup data-n=\"837\">84</sup> וכה\"ג).\n<b>וזהו</b> ההפרש בין מ\"ם סתומה למ\"ם פתוחה שזהו מאמר סתום ומאמר פתוח<sup data-n=\"838\">85</sup> דמח' ודבור, דמח' נק' מאמר סתום ודבור נק' מאמר פתוח (וגם בחי' המח' שמלובש בדבור נק' מאמר פתוח מאחר שבא לגילוי באותיות הדבור כמו [ב]מחשבה דמאמר יהי אור אע\"פ שעיקר התהוות האור מן המאמר דיהי אור עצמו מ\"מ מלובש בזה גם המח' של אותיות אלה, וזהו מי ברא אלה<sup data-n=\"839\">86</sup> דבחי' אלקי' מוסתר באותיות בכל מאמר ומאמר די' מאמרות בכל פרטיהם כמ\"ש במ\"א). אבל אותיות המח' עצמה כמו שהיא בהעלם בלתי נגלית באותיות הדבור נק' מאמר סתום וגם בחי' המדות והשכל והרצון [שבמח'] הסתומה הן בבחי' ההעלם שנק' פנימי' המוחין ומדות (וז\"ש מאד עמקו מחשבותיך וכן נפלאותיך ומחשבותיך כו'). והנה אנו רואים שהמדות שבלב מלובשים במח'",[["820","67","<b>דברה תורה כלשון בנ\"א</b>: ברכות לא, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a>."],["821","68","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל. רמב\"ם פיה\"מ סנהדרין פ\"י היסוד הג'."],["822","69","<b>כי לא ראיתם כל תמונה</b>: ואתחנן ד, טו."],["823","70","<b>וירא ה'</b>: בראשית ו, ה."],["824","71","<b>וישמע</b>: בהעלותך יא, א."],["825","72","<b>הנוטע אזן הלא ישמע</b>: תהלים צד, ט."],["826","73","<b>היוצר</b>: בתהלים שם: אם יוצר — ראה לעיל פ' בשלח קסה, ד. לקמן פ' תצוה שכו, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670066\" data-slug=\"torat-chaim\" data-id=\"2300670066\">תו\"ח וירא צז, ג</a> ובהערה 26."],["827","74","<b>מלאכים. . הנק' עינים ואזנים</b>: [בד: שנק' עיינין ואודנין]: ראה ת\"ז ת\"ע (קלא, א)."],["828","75","<b>מסט' דשכינת[א]. . תמונה</b>: ראה זהר (רע\"מ) פינחס רלט, א. מאמרי אדה\"א בראשית ע' שעז. ויקרא ח\"א ע' תכז. וש\"נ."],["829","76","<b>שבצלם אלקי' עשה את האדם</b>: נח ט, ו."],["830","77","<b>מבשרי אחזה אלוה</b>: איוב יט, כו [ושם: ומבשרי]. ראה הנסמן לעיל פ' בא צח, ב."],["831","78","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["832","79","<b>מה גדלו מעשיך</b>: תהלים צב, ו [בדילוג]."],["833","80","<b>נפלאותיך ומחשבותיך. . מספר</b>: תהלים מ, ו [בדילוג]."],["834","81","<b>נשמות. . נוני ימא</b>: ראה גם לעיל פ' בשלח רז, א. וש\"נ."],["835","82","<b>נוני ימא</b>: [ב: ניתוסף: רבא]: זהר בלק קפז, א. ראה גם הנסמן לעיל פ' בא צט, ג."],["836","83","<b>האבות</b>: ראה גם לקמן פ' ויקהל תל, סע\"ב ואילך. מאמרי אדה\"א ויקרא ח\"א ע' רנב בהערה שו\"ה שבבריאה. ד: רשב\"י — ראה גם לעיל פ' בא צט, ג."],["837","84","<b>משה דמן המים עליונים משיתיהו</b>: שמות ב, י. ראה לעיל פ' שמות מג, א. וש\"נ."],["838","85","<b>מאמר סתום ומאמר פתוח</b>: שבת קד, א. ראה גם לעיל פ' בשלח קמג, ד ואילך. הנסמן לעיל יב, ב."],["839","86","<b>מי ברא אלה</b>: ישעי' מ, כו. ראה גם לעיל פ' וארא עג, ג."]]],[2300550203,"ודבור שבאים <span data-k=\"pg\">776</span> ּ בגילוי באהבה וחסד או דין וממוצע הכל מלובש בדבור ומח', שהרי אין אדם חושב ומדבר רק [מה] שנולד בלבו התפעלות המדה אינו<sup data-n=\"840\">87</sup> חסד או דין כו' והתפעלות של המדות שבלב נולדים מחו\"ב שבמוח שמולידים אותן בשני אופנים שנק' או\"א להוליד המדות להמשיך בהן בחי' התפשטות והתחלקות [ב]פרטיות כו'. וכך יובן למעלה בכללות דמע\"ב די' מאמרות במח' ודבור העליונים שיצאו מהתפעלות [ה]מדות דאצי' שמלובש בהן (שנק' ז\"א שמלובש במח' ודבור) והן מקבלים מחו\"ב דאצי' שנק' או\"א שמולידים המדות וז\"ש בראשית ברא אלקים<sup data-n=\"841\">88</sup> בראשית אור אבא שאמר לאימא<sup data-n=\"842\">89</sup> שהוא אלקים כו' כמ\"ש בזהר ואח\"כ נמשך למדות דאצי' שהן נמשכים במח' ודבור דאימא<sup data-n=\"843\">90</sup> די' מאמרות כנ\"ל ולכך נק' וימ\"ב כידוע וד\"ל (וז\"ש<sup data-n=\"844\">91</sup> דבמאמר אחד יכול להבראות שזהו מאמר דבראשית<sup data-n=\"845\">92</sup> דחכ' שכולל הכל בינה ומדות ומח' ודבור די' מאמרות וכמ\"ש כולם בחכ' עשית כו'<sup data-n=\"846\">93</sup>.\n<b>והנה</b> באמת אע\"פ שבצלם אלקים עשה את האדם כנ\"ל עכ\"ז אין לדמות לאדם התחתון למעלה ממש רק שהוא בדוגמא ודומה לעליון, אך אין הדוגמא הזאת דאדם אמיתית למעלה שנא' בו כי לא אדם הוא להנחם שזהו להנחם לבא בהשתנות ממדה למדה כו', לפי שאין מדותיו ית' עושין בחי' שינוי והתפעלות ממש בעצמות אוא\"ס כמדות דאדם שעושין שינוי והתפעלות בעצם הנפש מחסד לדין ומאהבה לשנאה ורוגז וכן להיפך להתפעל ולהשתנות מדין לחסד ומרוגז לאהבה כו'. לפי שהמדות שבאדם הן כחות נוספים על עצם הנפש אע\"פ שהן יצאו מכח השכל שבנפש, אבל למעלה באדם דאצי' הרי נאצלים המדות מעצמיות המאציל בדרך צמצום וירידה גדולה דהיינו רק להיות מקור לבי\"ע שז\"ש לאחזאה לאתנהג בהון עלמין<sup data-n=\"847\">94</sup>, אבל מצד עצמות המאציל לאו דאית לי' צדק ידיעא דאיהו דין כו' ולאו מכא\"מ כלל<sup data-n=\"848\">95</sup> דהיינו רק בשביל שיהי' הנהגת העולמות בחסד ודין ורחמים כו' שהן חג\"ת דאצי' (וכמו וינחם ה' ויתעצב אל לבו<sup data-n=\"849\">96</sup> כו' שנתפעל במדה\"ד ממש כמו וחרה אף ה'<sup data-n=\"850\">97</sup> כו', וכה\"ג להיפך בהתפעלות החסד והטוב באה\"ר וכן התפעלו' הרחמים כי רחום וחנון וחפץ חסד כו', וכמו שמוזכר בכמה [מקומות ב]כתובי' הכל הוא בא מעצמות המאציל בבחי' צמצום",[["840","87","<b>אינו</b>: ב: אם. ד: או."],["841","88","<b>בראשית ברא אלקים</b>: בראשית א, א."],["842","89","<b>אבא שאמר לאימא</b>: ראה זהר בראשית כב, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרכה ואילך. וש\"נ. דברים ח\"ב ע' תרנא ואילך."],["843","90","<b>דאימא</b>: בד: ליתא."],["844","91","<b>וז\"ש</b>: ב: נרשם כאן פ\"ה. וראה לעיל הערה 52."],["845","92","<b>דבמאמר אחד. . מאמר דבראשית</b>: נסמן לעיל פ' יתרו רנב, ב."],["846","93","<b>כו'</b>: כנצ\"ל: כו')."],["847","94","<b>לאחזאה לאתנהג בהון עלמין</b>: ראה ת\"ז בהקדמה (יז, ב)."],["848","95","<b>לאו דאית לי'. . מכא\"מ כלל</b>: ראה ת\"ז שם."],["849","96","<b>וינחם. . אל לבו</b>: בראשית ו, ו [בדילוג]."],["850","97","<b>וחרה אף ה'</b>: עקב יא, יז."]]],[2300550235,"להיות נק' רחום וחנון כמ\"ש ויעבור הוי' כו' ויקרא<sup data-n=\"851\">98</sup> הוי' הוי' אל כו' וז\"ש לאחזאה לאתנהגא כו'. וכמו גוף התהוות העולמות שנתהוו ונמשכו מאין ליש ממדות דאצי' כמחנה מיכאל בחי' החסד נתהוו מחסד דאצי' וכה\"ג בנשמות דחסד דמל' דבריאה זהו ג\"כ ע\"י צמצום אור ה[מ]אצי' להיות אור חסד דאצי' מצומצם בכלי להיות מקור לחסד דבריאה ויצי' וכן להיפך להאציל בחי' גבו' דאצי' להיות מקור לגבורות דבי\"ע כו', אבל מדות דאצי' עצמן אין עושין שינוי כלל בעצמות המאציל כנ\"ל כמ\"ש אני הוי' לא שניתי<sup data-n=\"852\">99</sup> כו'. וגם בחי' מדות דאצי' מטעם הנ\"ל דלאו מכא\"מ כלל ונק' ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"853\">100</sup> כו' להיותם מיוחדי' וכלולים בעצמות המאציל ממש דאיהו וחיוהי חד<sup data-n=\"854\">101</sup> ממש כמשל השלהבת הקשורה בגחלת<sup data-n=\"855\">102</sup> כמ\"ש בס\"י וכה\"ג כי עצמות אוא\"ס הוא אחדות פשוט בתכלית הפשיטות וא\"א שיקבל שינויי' [מ]התפעלו' <span data-k=\"pg\">שפח</span> ּ מדותיו בחסד ודין כמדת האדם כמ\"ש כי לא אדם הוא כו').\n<b>אך</b><sup data-n=\"856\">103</sup> באמת אין [ה]ענין כך דא\"כ איך אנו אומרים אלקי עולם ברחמיך הרבים<sup data-n=\"857\">104</sup> רחם עלינו דמשמע ברחמיך הרבים שבעצמות ממש שנק' רחום וחנון בעצם, וכן רב טוב וחסד<sup data-n=\"858\">105</sup> בעצם רחם עלינו היינו שיתפעל ברחמים עלינו ממש ברחמים גשמיי' להשפיע פרנסה גשמיית וחיים גשמיי' כו' והרי התפעלות זו שינוי הוא כו', וכן [א' אבינו] אב הרחמים<sup data-n=\"859\">106</sup> וכה\"ג וכמ\"ש זכור רחמיך וחסדיך כי מעולם המה מעולם הא\"ס<sup data-n=\"860\">107</sup> עצמו ששם אמר חסדי ה' כי לא תמנו<sup data-n=\"861\">108</sup> כו' שהוא בבחי' א\"ס ממש משום דלגדולתו אין חקר<sup data-n=\"862\">109</sup>, וכה\"ג בכל המדות כמו גם במדה\"ד שבעצמות[ו] הרי אמר מי יודע עוז אפך<sup data-n=\"863\">110</sup> וכיראתך עברתיך כו' וכן בשאר המדות כמ\"ש לך הוי' הגדולה<sup data-n=\"864\">111</sup> והגבורה והתפארת כו'. וגם משמע שמדות עליונות באים למעלה בבחי' התפעלו' ממש וכפשט הכתוב וחרה אף כו' וכה\"ג, וכן להיפך בבחי' התפעלו' הרחמים כמו ותעל שועתם<sup data-n=\"865\">112</sup> וידע אלקים<sup data-n=\"866\">113</sup> וכה\"ג ברחמיך הרבים רחם עלינו כו' וממילא יש שינוי כמו שאמר יה\"ר מלפניך שיכבשו<sup data-n=\"867\">114</sup> רחמיך את כעסך כו' וכמו וינחם ה' על הרעה<sup data-n=\"868\">115</sup> כו' ואע\"פ שנא' כי לא אדם הוא להנחם בשינוי כנ\"ל. אך האמת הוא דאדרבה משום דאיהו וחיוהי חד כמו שלהבת הקשורה בגחלת כנ\"ל וכה\"ג הרי מדותיו ית' כלולים בעצמות[ו] ממש והן ע\"ס הגנוזות<sup data-n=\"869\">116</sup> בעצמו' דא\"ס שהם בבחי' א\"ס ממש ע\"כ אומר ברחמיך הרבים דוקא רחם עלינו שהוא מדה\"ר שבעצמות א\"ס וכן יהי חסדך ה' עלינו<sup data-n=\"870\">117</sup> וכה\"ג בכל המדות ויתפעל ברחמים אלה להיות שינוי מכח הדין לכח החסד כו' כמו",[["851","98","<b>ויעבור. . ויקרא</b>: תשא לד, ו."],["852","99","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["853","100","<b>ע\"ס בלי מ\"ה בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["854","101","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["855","102","<b>השלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["856","103","<b>אך</b>: ב: נרשם כאן פ\"ו. וראה לעיל הערה 91."],["857","104","<b>אלקי עולם ברחמיך הרבים</b>: ברכת יוצר."],["858","105","<b>טוב וחסד</b>: בד: חסד וטוב."],["859","106","<b>אבינו] אב הרחמים</b>: [ב: הרחמן]: ברכת ק\"ש שחרית."],["860","107","<b>זכור רחמיך. . מעולם הא\"ס</b>: תהלים כה, ו [בדילוג השם]. ראה גם לעיל פ' וארא סא, ב. וש\"נ."],["861","108","<b>חסדי ה' כי לא תמנו</b>: איכה ג, כב."],["862","109","<b>דלגדולתו אין חקר</b>: תהלים קמה, יג."],["863","110","<b>מי יודע עוז אפך</b>: תהלים צ, יא."],["864","111","<b>לך הוי' הגדולה</b>: דהי\"א כט, יא."],["865","112","<b>ותעל שועתם</b>: שמות ב, כג."],["866","113","<b>וידע אלקים</b>: שמות שם, כה."],["867","114","<b>יה\"ר מלפניך שיכבשו</b>: סדר תקיעת שופר בסידור האריז\"ל [בדילוג]."],["868","115","<b>וינחם ה' על הרעה</b>: תשא לב, יד."],["869","116","<b>ע\"ס הגנוזות</b>: ראה פרדס (שער סדר אצילות) ש\"ה, פ\"ד. (שער הצחצחות) שי\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו. שעה\"י — לקו\"ב — קפט, ג הערה 2."],["870","117","<b>יהי חסדך ה' עלינו</b>: תהלים לג, כב."]]],[2300550266,"וינחם ה' כו'. ומ\"ש כי לא אדם הוא כו' להנחם בהשתנות מדין לחסד או מחסד לדין זהו שאין השינוי כמו במדות דאדם שמצד השכל שמטה כלפי חסד או ישונה להטות לדין<sup data-n=\"871\">118</sup> כי מדות דא\"ס אין מתלבשים בחכמה דאדם שבא בצמצום דאור וכלי דלאו מכא\"מ כלל, פי' דקדק לומר אינון מדות דאדם אבל למעלה מבחי' אדם במדות העצמיי' ג\"כ יהופך מדין לחסד כמו יהי רצון כו' אלא שאין השינוי מצד החכ' אלא מצד העצמו' משום דמדותיו כלולים בו ממש ואיהו וחיוהי חד ע\"כ מתהפכים מדבר להיפוכו בשינוי הרצון שבעצמות ממש דוקא ועכ\"ז אין זה שינוי בעצמות כלל לפי שכלולים בו בתכלית כו' וד\"ל.\n[ג<sup data-n=\"872\">119</sup> ] והנה כתיב וירא אלקים את כל אשר עשה והנה טוב מאד<sup data-n=\"873\">120</sup>, להיות מבואר למעלה בענין וימ\"ב שמוחין דחו\"ב דאצי' ירדו ונתלבשו במדות דאצי' שנק' וי\"ו יומין עילאין כידוע והמדות מתלבשים ויורדי' במח' ודבור כנ\"ל, וזהו ירידה אחר ירידה עד\"מ אדם שרוצה לעסוק במלאכת הבנין הרי יהי' שכלו מצומצם ומלובש במדות שבלב, כי עצם כח שכלו הוא למעלה משכל זה שמצמצם במלאכת הבנין ונמצא זהו ירידה גדולה מעצמו' כח שכלו להשכיל במלאכה זו ולהתבונן בו. וכ\"ש ירידה שני' שמצמצם השכל הזה במדות שבלב באהבה וחשק למלאכה זו שזהו ירידה גדולה יותר, וכ\"ש ירידה ג' ממדות שבלב לחשוב במח' <span data-k=\"pg\">778</span> ּ לעשות וממח' לדבור ומדבור למעשה בפו\"מ שכל אלה ירידות רבות ממדריגה למדריגה עד שבאה למעשה בפו\"מ. וכמו מלאכת הכתיבה גם שכותב דבר חכמה הרי שכל זה בא במח' ומהמח' לבחי' פעולה דיד גם בהבדלת כח ותנועה שביד שנבדל מעצם כח היד לכתוב או לצייר דבר מה כו'. וכך הוא במע\"ב שנק' מעשה כמ\"ש אף ידי יסדה ארץ<sup data-n=\"874\">121</sup> כו' שמלובש במעשה מבחי'<sup data-n=\"875\">122</sup> מח' ודבור העליון ובמח' ודבור מלובש המדות ובמדות מלובש החכ' שירדה מעצמות החכמה כו'. ונמצא שכמו שפעולה הפרטי' ירד[ה] מעצמות כחה כך כל בחי' מח' ודבור שהן המדות והשכל ירדה מעצמות החכ' ורצון במח' ודבור כו', וכל ירידות אלה הוא רק בשביל סוף מעשה לבד דנעוץ תחב\"ס<sup data-n=\"876\">123</sup> כנ\"ל<sup data-n=\"877\">124</sup> וד\"ל. וזהו וירא אלקי' את כל אשר עשה דהיינו בכל אשר עשה בי' מאמרות בוימ\"ב שהכל נק' עשי' סוף מעשה כי גם הי' מאמרות שאינו רק בחי' דבור ומלובש בהם המח' ומדות והשכל בירידות המדרגות כנ\"ל עכ\"ז הכל בחי' עשי' הוא כמ\"ש כולם בחכ' עשית דגם החכ' מקור הראשון נק' עשי' כמו שכל שבעשי' שגם הוא נק' בשם עשי' וכ\"ש המדות",[["871","118","<b>ישונה להטות לדין</b>: ב: ישנה להטות כלפי דין. ד: כלפי דין."],["872","119","<b>ג</b>: ב: נרשם כאן פ\"ז. ראה לעיל הערה 103."],["873","120","<b>וירא אלקים. . טוב מאד</b>: בראשית א, לא."],["874","121","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["875","122","<b>מבחי'</b>: ב: זאת. ד: זו מבחי'."],["876","123","<b>דנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["877","124","<b>כנ\"ל</b>: בד: כו'."]]],[2300550296,"ומח' ודבור. וראי' לזה ממ\"ש וי\"ו ימים עשה ה'<sup data-n=\"878\">125</sup> כו' הרי וי\"ו יומין עילאין שהן בחי' המדות דאצי' עשה את השמים כו' לפי שהן מקורים למח' ודבור העליוני' דאצי' שבאים לבחי' המעשה ממש ע\"כ אמר וי\"ו ימים עצמן עשה כמו בחכ' עשית כו' וד\"ל.\n<b>אך</b> הנה כל בחי' ירידות האלה מרצון העליון לחכמה ומחכ' למדות ומח' ודבור ומעשה הי' בוימ\"ב בדרך או\"י שהולך ויורד מלמעלה למטה דוקא ולכך נק' וימ\"ב דחכ' שירד בעשי' כנ\"ל, אבל מ\"ש וירא אלקי' את כל אשר עשה היינו לאחר תשלום כל הירידות דחכ' ומדות ומח' ודבור בסוף גמר כל המעשה די' מאמרות ראה את כל אשר עשה בי\"מ והנה טוב מאד שזהו בחי' העלא[ה ד]או\"ח בליל שבת שהוא העלאות התענוג מכל אשר עשה וברא בחכ' ומדות ומחודו\"מ כו'. וזהו בכללות<sup data-n=\"879\">126</sup> יום הששי<sup data-n=\"880\">127</sup> ויכולו השמים והארץ<sup data-n=\"881\">128</sup> כו' לשון תענוג<sup data-n=\"882\">129</sup> כמו כלתה נפשי<sup data-n=\"883\">130</sup> וכן ויכל אלקים<sup data-n=\"884\">131</sup> כו', לפי שכל עיקר התענוג דמשפיע הוא בכלות השפע<sup data-n=\"885\">132</sup> כאשר גמר כל מלאכתו [ו]שובת ונח [ש]רואה והוטב בעיניו כל אשר עשה כו' שאז יש עלי' לחכ' ומדות כו' במקורא דכולא<sup data-n=\"886\">133</sup> כמ\"ש כי בו שבת מכל מלאכתו כו', עד\"מ מלאכה הגשמיי' שכאשר שובת ונח יחזור כח התפשטות היד לכח העצמות שביד כך יחזירו אותיות מח' ודבור למקורם במדות וגם המדות יחזרו לשכל וגם השכל ינוח מטרדתו במלאכה זו למקורו. ובכלל ג' מדרגות הן נר\"נ נייחא דנפשא הוא השביתה בכח המעשה ונייחא דרוחא במדות ומח' ודבור ונייחא דנשמתא<sup data-n=\"887\">134</sup> במוחין דחו\"ב כו' כידוע. וזהו כי בו שבת וינפש<sup data-n=\"888\">135</sup> בעצמותו ממש, וזהו ע\"י בחי' העלאות התענוג מכל אשר עשה שהוא בבחי' או\"ח למקורו, וזהו שבת דמעלי שבתא, אבל שבת דיומא<sup data-n=\"889\">136</sup> הוא בבחי' ירידה והמשכה חדשה מעצמיות התענוג העליון בחכ' ומדות ומח' ודבור להיות מחדש למע\"ב בוימ\"ב דחול<sup data-n=\"890\">137</sup> שאחר השבת כו' <span data-k=\"pg\">שפט</span> ּ (שזהו לעשות את השבת<sup data-n=\"891\">138</sup> כו' וכמ\"ש וקראת לשבת ענג<sup data-n=\"892\">139</sup> כו'). וזהו שארז\"ל אלמלא שמרו בנ\"י<sup data-n=\"893\">140</sup> ב' שבתות כהלכתן מלמטה למעלה ומלמעלמ\"ט כו' כמ\"ש במ\"א וד\"ל.\n[ד] <b>וזהו</b> ממצוא חפצך ודבר דבר<sup data-n=\"894\">141</sup> דגם דיבור של חול אסור בשבת, לפי שהדבור הוא בחי' ההתפשטו' למטה בגילוי לחוץ ובשבת בחי' דבור העליון הוא בעלי' רק חיצוני'",[["878","125","<b>וי\"ו ימים עשה ה'</b>: תשא לא, יז."],["879","126","<b>בכללות</b>: בד: בכלות."],["880","127","<b>יום הששי</b>: בראשית א, לא."],["881","128","<b>ויכולו השמים והארץ</b>: בראשית ב, א."],["882","129","<b>ויכולו. . לשון תענוג</b>: ראה גם לעיל פ' בשלח רכ, ב. וש\"נ."],["883","130","<b>כלתי נפשי</b>: תהלים פד, ג."],["884","131","<b>ויכל אלקים</b>: בראשית ב, ב. ראה גם לעיל פ' שמות לה, ד. וש\"נ."],["885","132","<b>עיקר התענוג. . בכלות השפע</b>: ראה גם לעיל פ' בשלח ריט, ד. וש\"נ."],["886","133","<b>במקורא דכולא</b>: זהר בראשית לג, א."],["887","134","<b>נייחא דנפשא. . דרוחא. . דנשמתא</b>: ראה גם שה\"א כט, א ובהנסמן לשם."],["888","135","<b>כי בו שבת וינפש</b>: חיבור שני כתובים בראשית ב, ג. תשא לא, יז. ראה גם הנסמן לעיל פ' בשלח רט, ד הערה 12."],["889","136","<b>שבת דמעלי שבתא. . שבת דיומא</b>: זהר בהקדמה ה, ב."],["890","137","<b>בוימ\"ב דחול</b>: ד: בו' ימי החול."],["891","138","<b>לעשות את השבת</b>: תשא לא, טז."],["892","139","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["893","140","<b>אלמלא שמרו בנ\"י</b>: ראה שבת קיח, ב. לעיל פ' בשלח רח, ד. וש\"נ."],["894","141","<b>ממצוא חפצך ודבר דבר</b>: ישעי' נח, יג. ראה שבת קיג, רע\"ב. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'רנו-א'רנח. וראה גם לעיל פ' בשלח רטו, ד ובהנסמן שם."]]],[2300550323,"שלו מאיר למטה, שאל\"כ הי' הכל חוזר לאין כמ\"ש במ\"א דהיינו בחי' חכ' שבדבור הפנימי' עולה למעלה כו' באור אבא דאצי' שנק' חכ' בראש וזהו ודבר דבר מל' דלאו אורחי' דמלכא לאשתעי<sup data-n=\"895\">142</sup> כו'. וזהו השביתה בדבור שנק' שבת תתאה והשביתה בחכ' בראש נק' שבת עילאה<sup data-n=\"896\">143</sup> וכתיב כי בו שבת מכל מלאכתו אפי' בחכ' בראש שחוזר גם הוא למקורו בפנימי' ועצמות החכ', שזהו כמו דבר<sup data-n=\"897\">144</sup> מלך שמדבר בדבר חכ' לעצמו כפי כח חכ' העצמי שלמעלה הרבה מחכ' ושכל שמצמצם עצמו לענין הנהגת המדינה ולבנין ולמלאכה וכה\"ג. וזהו ודבר דבר אפי' דבר מלך להנהגות העולמות משום דכלא ממש חשיב לגבי חכמה העצמי' (וע\"כ מותר לדבר ד\"ת בשבת<sup data-n=\"898\">*145</sup>, וז\"ש ממצוא חפצך אבל חפצי שמים מותרים<sup data-n=\"899\">145</sup> ) (ומ\"ש בירושלמי בקושי התירו לדבר בתורה בשבת<sup data-n=\"900\">146</sup> היינו דברי תנחומין ולא ד\"ת כידוע).\n<b>ובכ\"ז</b> מובן הטעם שבכל מע\"ב לא נזכר שם הוי' כלל אלא שם אלקים<sup data-n=\"901\">*147</sup> [לבדו] כמו בראשית ברא אלקים ויאמר אלקים יהי אור כו' עד שגמר כל מלאכתו וקידש יום השבת אז אמר אלה תולדות השמים כו' ביום עשות הוי' אלקים ארץ ושמים<sup data-n=\"902\">147</sup> אז הזכיר שם הוי' עם אלקים, דהיינו לאחר שאמר ויכולו השמים כו' שעלה הכל בבחי' או\"ח לקדמותו שנק' נייחא דרוחא כו' כי בו שבת כו' בג' מיני שביתה הנ\"ל בנר\"ן כו' אז נתגלה שם הוי' במע\"ב. כי הנה בחי' שם אלקים הוא בחי' הצמצום והסתר להסתיר ולהעלים שם הוי' כמ\"ש כי שמש ומגן<sup data-n=\"903\">148</sup> הוי' אלקים כו', ומע\"ב שהי' הכל בבחי' ירידה וצמצום בחו\"ב ומדות ומח' ודבור כנ\"ל הכל הוא בבחי' צמצום דשם אלקי' שמעלים ומסתיר למוחין דחו\"ב י\"ה ומדות ודבור הן ו\"ה שירדו מן העצמות לבא לבחי' המעשה כנ\"ל. והיינו כל וימ\"ב שנברא הכל בצמצום דש' אלקים כו' ולא נז' שם הוי' כלל, לפי ששם הוי' הוא בבחי' עצמיות אוא\"ס שבע\"ס דאצי' דאיהו וחיוהי חד כו' שמיוחד במדותיו וחכמתו כו' שמפני זה אמר אני הוי' לא שניתי כנ\"ל, ע\"כ לא נתגלה במע\"ב רק אחר גמר המלאכה דוקא שנק' נייחא דרוחא דאו\"ח לעצמותו ממש, דהיינו שחו\"ב ומדות [ומו\"ד ע]לו בעצמות [אור] המאציל כמו ששם הוי' מיוחד בעצמותו אז נאמר שם הוי' עם שם אלקי' כמ\"ש ביום עשות הוי' אלקים<sup data-n=\"904\">149</sup> כו' וד\"ל (אך לפ\"ז הי' עלי' דאו\"ח למעלה דוקא וא\"כ למה אמר ביום עשות הוי' אלקי' דמשמע דגם העשי' דמע\"ב הי'",[["895","142","<b>דלאו אורחי' דמלכא לאשתעי</b>: ראה זהר בהעלותך קמט, ב. סידור שער התפלה יח, סע\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי כה, ד</a>."],["896","143","<b>שבת תתאה. . שבת עילאה</b>: זהר בהקדמה ה, ב."],["897","144","<b>דבר</b>: בד: ליתא."],["898","*145","<b>מותר לדבר ד\"ת בשבת</b>: ראה גם לעיל פ' בשלח רטז, ד. וש\"נ."],["899","145","<b>חפצי שמים מותרים</b>: שבת קיג, סע\"א."],["900","146","<b>בירושלמי בקושי התירו לדבר בתורה בשבת</b>: ראה ירושלמי שבת פט\"ו, ה\"ג. רבינו יונה בס' היראה. מאמרי אדה\"א נ\"ך ע' קנו. וש\"נ."],["901","*147","<b>שבכל מע\"ב. . שם אלקים</b>: ראה גם לקמן פ' תרומה שה, א. הנסמן לעיל פ' שמות ל, ב הערה 128."],["902","147","<b>אלה תולדות. . ארץ ושמים</b>: בראשית ב, ד."],["903","148","<b>אלקים. . הצמצום. . כי שמש ומגן</b>: תהלים פד, יב. ראה שער היחוד והאמונה רפ\"ו. הנסמן לעיל פ' שמות לד, ד."],["904","149","<b>ביום עשות הוי' אלקים</b>: בראשית ב, ד."]]]]});
